// Expanded interview bank (Iter 3) — additional full-schema questions merged
// into BANK by data/interview-bank.js. Same schema as the core bank:
//   { tier, cat, q, short, detailed, example?, mistake, followup, senior }
// Authored in category batches, de-duplicated against the core bank and across
// batches, and schema-checked by tools/content-lint.mjs.
export const EXTRA_BANK = [
  { tier:"beginner", cat:"ELT vs ETL", q:"How does dbt fit the ELT paradigm versus traditional ETL?", short:"In ELT you load raw data into the warehouse first, then transform in-place with dbt, leveraging warehouse compute instead of a separate transformation engine.", detailed:"Traditional ETL transforms data in a dedicated engine before loading. ELT loads raw data first and pushes transformation down into the warehouse where storage and compute are cheap and scalable. dbt is the T in ELT: it issues SQL the warehouse executes, so transformations are versioned, testable, and reproducible SQL rather than opaque pipeline steps.", mistake:"Claiming dbt is an ETL tool that moves data between systems.", followup:"When might ETL still be preferable to ELT?", senior:"When data cannot legally or practically land raw in the warehouse (PII that must be masked or tokenized pre-load), when the source is streaming and needs in-flight enrichment, or when the warehouse compute cost of transforming massive raw volumes exceeds the cost of pre-processing upstream." },
  { tier:"beginner", cat:"Models", q:"What is a dbt model and how does it relate to a warehouse table or view?", short:"A model is a single .sql file containing a SELECT statement; dbt materializes it into the warehouse as a view, table, or other materialization you configure.", detailed:"Each model is one SELECT. The model name maps to the object name in the warehouse. The materialization config decides the physical form: view (default) builds a view, table rebuilds a table on each run, incremental appends/merges new rows, and ephemeral inlines the SQL as a CTE without creating an object.", mistake:"Assuming one model can contain multiple SELECTs that each create separate tables, or that a model is always a table.", followup:"What materializations ship with dbt Core and when would you pick each?", senior:"view (cheap, always fresh, good for light logic), table (precomputed, faster reads, good for heavy logic queried often), incremental (large append-only or slowly changing data where full rebuilds are costly), and ephemeral (reusable logic you do not want persisted). Snapshots are a separate construct for SCD Type 2 history." },
  { tier:"beginner", cat:"ref vs source", q:"What is the difference between ref() and source()?", short:"ref() references another dbt model and builds a dependency edge in the DAG; source() references a raw table loaded outside dbt that you declare in YAML.", detailed:"ref('model_name') resolves to the compiled relation of a model dbt manages and creates a node-to-node edge for ordering. source('source_name', 'table_name') resolves to a raw table dbt does not build but is declared in a sources YAML block. Both abstract away hard-coded schema/database names so the same code works across environments.", mistake:"Hard-coding schema.table names instead of using ref/source, which breaks environment portability and lineage.", followup:"Why should you never hard-code a table name that another model builds?", senior:"Hard-coding breaks the DAG so dbt cannot order builds or detect the dependency, it breaks environment switching because schema names differ per target, and it breaks lineage and selection (state:modified+, graph operators). ref() keeps all of that automatic and correct." },
  { tier:"beginner", cat:"DAG", q:"What is the DAG in dbt and how is it built?", short:"The DAG is the directed acyclic graph of model dependencies that dbt infers from ref() and source() calls, determining build order and enabling lineage.", detailed:"dbt parses every model, collects its ref() and source() calls, and constructs a dependency graph. It topologically sorts that graph to run models in the correct order and to parallelize independent models up to your thread count. The DAG also powers node selection, lineage in docs, and state-based selection.", mistake:"Thinking you must manually specify run order; dbt infers it from refs.", followup:"What happens if your refs create a cycle?", senior:"dbt raises a compilation error because a DAG must be acyclic; it cannot topologically sort a cycle. You resolve it by refactoring the circular logic, often by introducing an intermediate model or moving shared logic upstream so dependencies flow one direction." },
  { tier:"intermediate", cat:"Orchestration", q:"What is the difference between transformation and orchestration, and which does dbt Core provide?", short:"Transformation is building the datasets (dbt Core); orchestration is scheduling, triggering, and monitoring when those builds run, which dbt Core does not provide on its own.", detailed:"dbt Core executes transformations when invoked but has no scheduler, retry policy, or alerting of its own. Orchestration tools (Airflow, Dagster, dbt Cloud jobs, cron) decide when to invoke dbt, in what order relative to ingestion, and how to handle failures and notifications.", mistake:"Believing dbt Core schedules its own runs.", followup:"How do teams commonly orchestrate dbt in production?", senior:"Common patterns: dbt Cloud scheduled jobs; Airflow using the BashOperator/dbt operators or Cosmos to render dbt models as individual Airflow tasks; Dagster software-defined assets; or a container run on a cron/CI schedule. Finer-grained task mapping (per-model tasks) gives better retry and observability than a single monolithic dbt build task." },
  { tier:"intermediate", cat:"When not to use dbt", q:"When is dbt NOT the right tool?", short:"dbt is a poor fit for real-time streaming transforms, for extraction/loading, for row-by-row operational transactions, or when you have no cloud warehouse/SQL-queryable store.", detailed:"dbt operates in batch on SQL-queryable warehouses. It is not meant for sub-second streaming pipelines, for ingesting data from APIs, for application transactional writes, or for unstructured/ML feature pipelines that are not SQL-expressible. It also adds overhead that is hard to justify for a tiny one-off analysis.", mistake:"Trying to use dbt for streaming ingestion or as an application database layer.", followup:"Can dbt do near-real-time at all?", senior:"Only in a micro-batch sense: frequent incremental runs (e.g. every few minutes) on warehouses, or materialized/streaming tables on some platforms. True streaming belongs to tools like Flink, Materialize, or warehouse-native streaming features; dbt coordinates batch SQL, not event-time stream processing." },
  { tier:"beginner", cat:"dbt_project.yml", q:"What is the purpose of dbt_project.yml?", short:"It is the required project configuration file that defines the project name, version, paths, and default configurations for models, seeds, snapshots, and tests.", detailed:"dbt_project.yml marks the root of a dbt project and sets global defaults: model-path, seed-path, the profile to use, and hierarchical config blocks like the models: key where you set materializations, schemas, tags, and more by folder. Settings here are the lowest-precedence layer, overridable in property YAML and in-model config().", mistake:"Confusing dbt_project.yml (project config) with profiles.yml (connection credentials).", followup:"What is the relationship between the profile key in dbt_project.yml and profiles.yml?", senior:"dbt_project.yml names a profile; profiles.yml (by default in ~/.dbt/) defines that profile with one or more targets (dev, prod) holding connection details. The project references the profile by name so credentials stay out of the repo and vary by developer/environment." },
  { tier:"beginner", cat:"profiles.yml", q:"What does profiles.yml contain and where does it live?", short:"profiles.yml holds warehouse connection credentials organized into profiles and targets; by default it lives in ~/.dbt/ and is kept out of version control.", detailed:"A profile maps to the profile named in dbt_project.yml and contains an outputs block of targets (e.g. dev, prod), each with adapter type, host/account, database, schema, and auth. A default target picks which one runs when --target is not passed. It stays outside the repo because it contains secrets.", mistake:"Committing profiles.yml with credentials into the repo.", followup:"How do you keep secrets out of profiles.yml safely?", senior:"Use environment variables via the env_var() Jinja function inside profiles.yml (e.g. password: \"{{ env_var('DBT_PASSWORD') }}\"), or rely on keyring/SSO/key-pair auth. In dbt Cloud, connection and environment credentials are managed in the UI rather than a file." },
  { tier:"intermediate", cat:"Targets", q:"What is a target in dbt and how do you switch between them?", short:"A target is a named set of connection settings within a profile (like dev or prod); you switch with the --target flag or by setting a default target.", detailed:"Targets let one profile define multiple environments. dbt run --target prod uses the prod output block; without --target it uses the target set as default in the profile. target.name and other target.* variables are also available in Jinja for environment-aware logic.", mistake:"Hard-coding environment-specific schema names in models instead of relying on target-driven schema generation.", followup:"How would you make a model write to different schemas per environment?", senior:"Rely on custom schema generation: dbt concatenates the target schema with any custom schema via generate_schema_name. Override that macro to get clean prod schemas but prefixed dev schemas (e.g. dbt_alice_marts), and use the + custom schema config on folders rather than hard-coding." },
  { tier:"intermediate", cat:"Config precedence", q:"What is the precedence order for model configuration in dbt?", short:"In-model config() beats property YAML, which beats dbt_project.yml; more specific config wins over more general, and within a file later keys do not merge across levels by default.", detailed:"Configs resolve from most to least specific: a config() block inside the model file is highest, then the model's schema/property YAML entry, then folder-level and project-level settings in dbt_project.yml. Most configs override rather than merge, though a few (like tags, meta, grants in some cases) merge additively.", mistake:"Assuming dbt_project.yml always wins, or that all configs merge instead of override.", followup:"Which configs merge additively rather than override?", senior:"tags accumulate across levels, meta dictionaries merge, and grants merge (with + prefix) rather than fully replacing. pre_hook/post_hook also append across levels. Most scalar configs like materialized, schema, and alias override, with the nearest level winning." },
  { tier:"intermediate", cat:"Environment variables", q:"How do you use environment variables in a dbt project?", short:"Use the env_var() Jinja function, optionally with a default, in profiles.yml, dbt_project.yml, or models to inject values at parse/compile time.", detailed:"env_var('VAR_NAME') reads an OS environment variable; env_var('VAR_NAME', 'default') supplies a fallback. It is commonly used for credentials in profiles.yml and for environment-conditional config. Variables prefixed with DBT_ENV_SECRET_ are scrubbed from logs.", mistake:"Putting secrets directly in YAML instead of referencing env_var, or expecting a missing env var without a default to be silently empty.", followup:"How does dbt handle secret environment variables in logs?", senior:"Environment variables prefixed with DBT_ENV_SECRET_ (historically DBT_ENV_SECRET) are treated as secrets: their values are automatically masked in logs and output. They can only be used in profiles.yml, packages.yml, and a few connection contexts, not arbitrarily rendered into compiled SQL, to prevent leakage." },
  { tier:"intermediate", cat:"Vars", q:"What are dbt vars and how do you override them from the CLI?", short:"vars are project variables defined in dbt_project.yml and read with var(); you override them at runtime with --vars on the command line.", detailed:"You declare defaults under the vars: key in dbt_project.yml and read them with var('name', default). At runtime, dbt run --vars '{key: value}' (YAML/JSON) overrides those defaults for that invocation, which is useful for backfills, date ranges, or feature flags.", mistake:"Confusing vars (project variables) with env_var (OS environment variables).", followup:"When would you choose a var over an env_var?", senior:"Use vars for project-controlled, non-secret parameters that belong in the repo and vary per invocation (date windows, feature toggles, test row limits). Use env_var for secrets and for values owned by the runtime environment rather than the codebase. vars are overridable per-run via --vars; env_var depends on the process environment." },
  { tier:"fouryear", cat:"Naming conventions", q:"What is a common dbt project layering and naming convention?", short:"A common pattern is staging (stg_), intermediate (int_), and marts (fct_/dim_) layers, with one staging model per source table and business logic concentrated in marts.", detailed:"Staging models (stg_source__entity) lightly clean and rename one source each. Intermediate models (int_*) hold reusable multi-step logic not exposed to BI. Marts contain the final fct_ (facts) and dim_ (dimensions) consumed downstream. Folder structure mirrors these layers and drives config inheritance.", mistake:"Putting heavy joins in staging or exposing intermediate models directly to BI tools.", followup:"Why keep staging models one-to-one with source tables?", senior:"A thin, consistent staging layer gives a single, testable interface to each raw source: renames, type casts, and basic cleaning live in exactly one place, so downstream models never reference raw sources directly. This isolates source schema changes to one model and keeps lineage and refactoring predictable." },
  { tier:"senior", cat:"Groups and access", q:"How do groups and the access config enforce model boundaries in dbt?", short:"A group assigns models an owner and a boundary; the access modifier (private, protected, public) controls whether models outside the group may ref() them.", detailed:"You define groups in YAML with an owner, assign models to a group, and set access per model. private means only same-group models can ref it; protected (the default) means any model in the same project; public means any project (relevant for cross-project refs in dbt Mesh). dbt raises an error on disallowed references.", mistake:"Assuming access controls warehouse permissions rather than dbt-level reference rules.", followup:"What does access: public specifically enable?", senior:"public marks a model as a stable, intended interface that other dbt projects can reference via cross-project ref() in dbt Mesh. It signals an API contract you commit to maintaining. Cross-project referencing itself is a platform feature (dbt Cloud / dbt Mesh), so public has full effect there, while within a single project protected already allows internal refs." },
  { tier:"fouryear", cat:"Project versioning", q:"What is the version key in dbt_project.yml and the require-dbt-version setting?", short:"version in dbt_project.yml is a free-form project version string; require-dbt-version pins which dbt Core versions are allowed to run the project.", detailed:"The project version is informational metadata. require-dbt-version (a version range) causes dbt to error if the running dbt Core version falls outside it, protecting against incompatible-version runs. Note that in recent dbt versions the top-level project version key became optional.", mistake:"Confusing project version with model-level versions (the versioned models feature).", followup:"How is require-dbt-version different from model versions?", senior:"require-dbt-version constrains the dbt Core executable. Model versions (the versions: block with defined_in and the v= arg to ref) let you maintain multiple versions of a single model simultaneously for safe, staged migration of downstream consumers, with deprecation dates. One governs the tool; the other governs a model as a published interface." },
  { tier:"beginner", cat:"Sources", q:"How do you declare a source in dbt and why?", short:"You declare sources in a YAML file under a sources: block naming the source, its tables, and their database/schema, then reference them with source().", detailed:"Declaring sources documents raw data, enables source() referencing (which abstracts the physical location), adds the tables to lineage, and allows source-level tests and freshness checks. Without a declaration you would hard-code raw table names, losing lineage and portability.", mistake:"Referencing raw tables directly with hard-coded schema.table instead of declaring and using source().", followup:"What metadata can you attach at the source level?", senior:"You can set database, schema, loaded_at_field, freshness thresholds, tags, meta, descriptions, tests, and table-level overrides. loader and description document provenance, and quoting/identifier overrides handle nonstandard raw names, all centralized so downstream models never touch raw identifiers." },
  { tier:"intermediate", cat:"Source freshness", q:"What is source freshness and how is it different from data completeness?", short:"Source freshness measures how recently raw data arrived, based on a loaded_at_field compared to now; completeness is whether all expected rows/records are present, which freshness does not check.", detailed:"dbt source freshness evaluates max(loaded_at_field) against warn_after and error_after thresholds to detect stale ingestion. It answers how old the newest record is, not whether rows are missing, duplicated, or correct. Completeness and correctness need tests (not_null, unique, row counts, reconciliation).", mistake:"Assuming a passing freshness check means the data is complete or correct.", followup:"Which command runs freshness and where are results stored?", senior:"dbt source freshness runs the checks and writes results to sources.json in the target directory (and reflects them in docs). It uses the loaded_at_field, or the warehouse metadata where supported. Freshness is a timeliness SLA signal; pair it with tests and volume/anomaly checks for a fuller data-quality picture." },
  { tier:"beginner", cat:"Seeds", q:"What is a dbt seed and when is it appropriate?", short:"A seed is a small CSV file in the seeds directory that dbt loads into the warehouse with dbt seed; it suits small, static, version-controlled lookup data.", detailed:"Seeds are CSVs checked into the repo and materialized as tables via dbt seed. Good uses: country-code maps, status mappings, test fixtures, small reference lists that change rarely and benefit from version control and code review.", mistake:"Using seeds to load large or frequently changing production data.", followup:"Why are seeds a bad fit for large or sensitive data?", senior:"Seeds are parsed and inserted by dbt row by row (or via adapter bulk load), which is slow and memory-heavy at scale, and the data lives in Git so it is inappropriate for large volumes or PII/secrets. Large or changing data belongs in proper EL ingestion and should be declared as a source." },
  { tier:"beginner", cat:"dbt docs", q:"What does dbt docs generate do?", short:"It produces documentation artifacts (including catalog.json) and, with dbt docs serve, a browsable website showing models, columns, descriptions, tests, and lineage.", detailed:"dbt docs generate compiles the project, queries the warehouse for catalog metadata (column names/types/stats) into catalog.json, and combines it with manifest.json to power the docs site. dbt docs serve launches a local web server to view it, including an interactive DAG.", mistake:"Thinking docs generate runs or tests your models; it does not build model data, it collects metadata.", followup:"Why does docs generate query the warehouse?", senior:"It needs the catalog: actual column names, data types, and table statistics that only exist after objects are built. That is why you typically run dbt run/build before docs generate, and why docs generate can run with --no-compile but needs warehouse access for catalog.json unless you pass flags to skip catalog population." },
  { tier:"beginner", cat:"Documentation", q:"How do you document a model and its columns?", short:"Add description keys in the model's YAML properties file at the model and column level; descriptions can include Markdown and doc blocks.", detailed:"In schema/property YAML you set a model description and per-column descriptions. These render in the docs site and in lineage. For longer or reused text you define a docs block ({% docs name %}...{% enddocs %}) in a .md file and reference it with {{ doc('name') }}.", mistake:"Leaving descriptions blank, or duplicating long text instead of using doc blocks.", followup:"What is a doc block and why use it?", senior:"A doc block is reusable Markdown defined once in a .md file and referenced via {{ doc('name') }} in any description. It avoids duplication, keeps definitions consistent across models (e.g. a shared metric definition), and lets you maintain rich formatting in one place." },
  { tier:"fouryear", cat:"Exposures", q:"What is an exposure in dbt?", short:"An exposure is a YAML-defined node representing a downstream use of dbt models (a dashboard, app, or ML pipeline), adding it to lineage and enabling selection.", detailed:"Exposures declare dependencies on models/sources with a type, owner, and URL. They appear in the docs DAG so you can see what consumes your data, and you can select them (e.g. dbt build --select +exposure:weekly_kpis) to run everything feeding a given exposure.", mistake:"Thinking an exposure creates or refreshes the dashboard; it only documents and links the dependency.", followup:"How do exposures improve impact analysis?", senior:"Because exposures sit at the downstream edge of the DAG, you can traverse upstream from them to answer which dashboards or ML jobs a model change affects, run only the models powering a critical exposure, and surface ownership. They turn informal knowledge of consumers into queryable, version-controlled lineage." },
  { tier:"senior", cat:"Contracts", q:"What is a model contract in dbt and how does it differ from a test?", short:"A contract enforces a model's column names, data types, and constraints at build time, failing the run if the output does not match; tests assert data conditions after the build.", detailed:"With contract: {enforced: true} plus a defined columns spec, dbt verifies the model's shape (and applicable constraints) as it builds, preventing a schema-drifting model from materializing. Tests (not_null, unique, custom) instead query already-built data and report pass/fail. Contracts are structural and preventative; tests are data-quality and detective.", mistake:"Conflating contracts (enforced structure at build) with constraints or with data tests.", followup:"How do constraints relate to contracts, and are they enforced everywhere?", senior:"Constraints (not_null, primary_key, foreign_key, check) are declared in the contract columns spec, but enforcement depends on the adapter/warehouse: some enforce at DDL (e.g. not null), others only document or validate informationally. dbt enforces name/type matching itself, while true constraint enforcement varies by platform, so you cannot assume a foreign_key constraint is actually checked on every warehouse." },
  { tier:"senior", cat:"dbt Mesh", q:"What is dbt Mesh and cross-project references?", short:"dbt Mesh is a pattern of splitting work into multiple governed dbt projects that reference each other via public models using two-argument ref(); cross-project ref is a dbt Cloud/platform feature.", detailed:"In Mesh, teams own separate projects connected through models marked access: public and consumed with ref('project_name', 'model_name'). It relies on groups, access, versions, and contracts for governance. Cross-project referencing is enabled by dbt Cloud (or equivalent platform metadata sharing), not by dbt Core alone.", mistake:"Assuming cross-project ref works in plain dbt Core without the platform layer.", followup:"What governance features make Mesh safe across teams?", senior:"Public access designates stable interfaces, model versions allow non-breaking migration with deprecation windows, contracts guarantee the shape consumers depend on, and groups assign clear ownership. Together they let a producing team evolve internals while giving consuming projects a reliable, documented, versioned API rather than fragile direct coupling." },
  { tier:"intermediate", cat:"Model versions", q:"How do dbt model versions and deprecation work?", short:"You define multiple versions of a model under a versions: block; consumers pin a version with ref(name, v=N), and you can set deprecation_date to warn about retiring old versions.", detailed:"Versioned models let one logical model have v1, v2, etc., each optionally backed by a separate SQL file via defined_in. A latest_version marks the default. deprecation_date triggers warnings when deprecated versions are referenced or built, enabling staged migration of downstream users.", mistake:"Thinking you must duplicate and rename models manually to evolve them.", followup:"How do you migrate consumers off a deprecated model version safely?", senior:"Publish the new version alongside the old, set a deprecation_date on the old one so refs emit warnings, communicate the window, and use lineage/exposures to find every consumer. Consumers repoint ref(..., v=) incrementally and are validated against the new contract before you drop the old version, avoiding a breaking big-bang cutover." },
  { tier:"beginner", cat:"CLI", q:"What is the difference between dbt run and dbt build?", short:"dbt run executes models only; dbt build runs models, tests, snapshots, and seeds together in DAG order, testing each node as it is built.", detailed:"dbt run materializes models. dbt build is a superset: it seeds, runs models, snapshots, and runs tests in dependency order, and crucially it tests a model right after building it so a failing test can stop dependents. This gives safer, data-quality-aware execution.", mistake:"Thinking build is just run plus a separate test pass; it interleaves tests within the DAG.", followup:"Why is interleaved testing in build valuable?", senior:"Because a failing test on an upstream model halts its downstream dependents before they consume bad data, rather than building the whole graph and testing at the end. This fail-fast behavior limits blast radius, and combined with selection it lets you rebuild and validate a slice atomically." },
  { tier:"beginner", cat:"CLI", q:"What does dbt compile do versus dbt run?", short:"dbt compile renders Jinja-SQL models into executable warehouse SQL in the target directory without running them; dbt run compiles and then executes them.", detailed:"compile resolves refs, sources, macros, and Jinja into plain SQL written under target/compiled (and updates the manifest) but issues no DDL/DML. It is useful for debugging generated SQL, previewing changes, and feeding compiled SQL to other tools. run does the compile step and then materializes.", mistake:"Believing compile also builds or validates data in the warehouse.", followup:"Where can you see the compiled SQL for a model?", senior:"In target/compiled/<project>/<path>/<model>.sql after compile or run. You can also use dbt show to preview a query's results, and in the dbt docs or the manifest to inspect compiled_code. Reading compiled SQL is the first debugging step when a model behaves unexpectedly." },
  { tier:"intermediate", cat:"CLI", q:"What does dbt parse do and how does it relate to partial parsing?", short:"dbt parse reads the project and builds the manifest without connecting to the warehouse; partial parsing speeds this up by only re-parsing changed files between invocations.", detailed:"Parsing constructs the internal graph/manifest from project files. dbt parse performs just that step (useful for CI validation and timing). Partial parsing caches the prior manifest and reparses only files that changed, significantly reducing startup time on large projects.", mistake:"Assuming every dbt command fully re-parses the whole project every time.", followup:"When should you disable or clear partial parsing?", senior:"Clear it (or use --no-partial-parse / delete target/partial_parse.msgpack) when environment variables, vars, or external macros that the cache does not track change, or when you see stale-parse anomalies. Changing things partial parsing cannot detect can make the cached manifest inconsistent, so a clean full parse resolves confusing ghost errors." },
  { tier:"beginner", cat:"CLI", q:"What does dbt test do and what are the two main kinds of tests?", short:"dbt test runs data tests against built models; the two kinds are generic (reusable, e.g. not_null, unique) and singular (a one-off SQL query in the tests directory).", detailed:"Generic tests are parameterized and applied in YAML (unique, not_null, accepted_values, relationships, plus package tests). Singular tests are standalone .sql files asserting a condition by returning failing rows. A test passes when it returns zero rows.", mistake:"Thinking a test passes by returning rows; it passes when it returns zero failing rows.", followup:"How do you write a custom generic test?", senior:"Define a test macro with {% test my_test(model, column_name, ...) %} in the tests/generic (or macros) path that returns a SELECT of failing rows, then reference it by name in YAML with any args. You can also set config like severity (warn/error), error_if/warn_if thresholds, and store_failures to persist failing rows for inspection." },
  { tier:"beginner", cat:"CLI", q:"What does dbt seed do?", short:"dbt seed loads the CSV files in the seeds directory into the warehouse as tables.", detailed:"It reads each configured CSV, applies seed configs (types, delimiter, schema), and creates or replaces the corresponding table. It is part of dbt build and can be run alone, with selection like dbt seed --select country_codes.", mistake:"Expecting dbt seed to pull data from an external source rather than from repo CSVs.", followup:"How does dbt seed handle changes to a seed file over time?", senior:"By default dbt drops/recreates (full-refresh style) the seed table on each dbt seed, so edits to the CSV fully replace the table. There is no incremental merge for seeds; large or frequently updated reference data is better modeled from a proper source. Use --full-refresh semantics are effectively always on for seeds." },
  { tier:"intermediate", cat:"Snapshots", q:"What does dbt snapshot do?", short:"dbt snapshot captures slowly changing dimension (SCD Type 2) history by recording changes to mutable source records over time into a snapshot table.", detailed:"Snapshots use a strategy (timestamp or check) to detect row changes and maintain validity columns (dbt_valid_from, dbt_valid_to) so you preserve historical states of records that the source overwrites. dbt snapshot runs them; they are also included in dbt build.", mistake:"Confusing snapshots with incremental models; snapshots preserve change history, incrementals just avoid rebuilding.", followup:"What is the difference between the timestamp and check snapshot strategies?", senior:"The timestamp strategy relies on an updated_at column to detect changes and is efficient and reliable when such a column exists and is trustworthy. The check strategy compares a specified list of columns (or all columns) between runs to detect changes, used when there is no reliable updated-at timestamp, at the cost of comparing column values each run." },
  { tier:"intermediate", cat:"CLI", q:"What does dbt ls (list) do?", short:"dbt ls lists the nodes (models, tests, sources, etc.) that match a selection, without running anything; it is useful for debugging selectors and scripting.", detailed:"dbt ls applies the same --select/--exclude syntax as run/build and prints matching resources. With --output and --resource-type you can get JSON, paths, or names for CI tooling, and it is a safe way to verify a selector hits exactly the intended nodes before executing.", mistake:"Thinking dbt ls executes or compiles models; it only resolves and prints selection.", followup:"How would you use dbt ls in CI?", senior:"Use it to enumerate state-based changes, e.g. dbt ls --select state:modified+ --state <prod_manifest> to list changed models and their descendants, feeding that into a targeted build or into notifications. Its machine-readable output (--output json/name/path) lets CI compute blast radius and drive slim, deferred runs." },
  { tier:"intermediate", cat:"CLI", q:"What does dbt show do?", short:"dbt show compiles and runs a model or inline query against the warehouse and prints a small preview of the result set to the terminal.", detailed:"It is a lightweight way to inspect data without materializing: dbt show --select my_model --limit 5, or dbt show --inline 'select ...'. It executes the query (so it hits the warehouse) but does not create or replace any object.", mistake:"Assuming dbt show materializes the model or that it does not touch the warehouse.", followup:"How does dbt show differ from dbt compile for debugging?", senior:"compile renders the SQL without executing, so you inspect the generated statement; show actually executes and returns rows, so you inspect the data. In practice you compile to verify the SQL is correct and show to verify the results are correct, often in sequence when diagnosing a wrong-output model." },
  { tier:"intermediate", cat:"CLI", q:"What does dbt retry do?", short:"dbt retry re-runs only the nodes that failed (and those skipped because of the failure) in the previous invocation, using the last run_results.json.", detailed:"After a run/build partially fails, dbt retry reads run_results.json to resume from the point of failure rather than rebuilding everything. It preserves the original selection and only tackles failed and downstream-skipped nodes, saving time and compute on large graphs.", mistake:"Rebuilding the entire project after a partial failure instead of using retry.", followup:"What does dbt retry depend on and when does it not help?", senior:"It depends on a valid run_results.json from the immediately prior invocation in the same target directory. It does not help if you changed the selection or code in a way that invalidates the prior graph, or if the failure was environmental and still present. In those cases rerun with explicit selection (e.g. state:error+ patterns) instead." },
  { tier:"beginner", cat:"CLI", q:"What does dbt clean do?", short:"dbt clean deletes the directories listed in clean-targets (typically target and dbt_packages) to remove compiled artifacts and installed packages.", detailed:"It wipes generated output and dependency installs so you can start fresh, which helps clear stale compiled SQL, old manifests, or corrupted partial-parse state. The folders removed are whatever you configure under clean-targets in dbt_project.yml.", mistake:"Thinking dbt clean touches the warehouse or drops tables; it only deletes local directories.", followup:"When is running dbt clean a useful troubleshooting step?", senior:"When you suspect stale artifacts: a partial_parse cache causing ghost errors, outdated compiled SQL, or a broken packages install. clean followed by dbt deps and a fresh run removes local-state confounders so you can distinguish a real code/warehouse issue from stale build output." },
  { tier:"beginner", cat:"CLI", q:"What does dbt deps do?", short:"dbt deps installs the packages declared in packages.yml (or dependencies.yml) into the dbt_packages directory.", detailed:"Packages are reusable dbt projects (like dbt_utils) pulled from the dbt Hub, Git, or local paths. dbt deps resolves and downloads the pinned versions so their macros, models, and tests become available. It must be run after cloning and whenever package specs change.", mistake:"Forgetting to run dbt deps before run/build, causing missing-macro errors.", followup:"How should you pin package versions and why?", senior:"Pin exact or tightly ranged versions in packages.yml (e.g. version: 1.1.1 or a revision/tag for Git packages) rather than floating ranges, so builds are reproducible and an upstream release cannot silently change behavior. Commit package-lock.dependencies where supported, and bump versions deliberately with testing rather than auto-upgrading." },
  { tier:"beginner", cat:"CLI", q:"What does dbt debug do?", short:"dbt debug validates your setup: it checks the profiles.yml connection, dependencies, and project configuration, confirming dbt can connect to the warehouse.", detailed:"It reports whether the profile is found and valid, whether required connection fields are set, and whether a test connection to the warehouse succeeds, plus the versions of dbt and the adapter. It is the first thing to run when a project will not connect.", mistake:"Using dbt debug to debug model SQL; it debugs environment/connection, not query logic.", followup:"A teammate's dbt debug passes but dbt run fails with permission errors; why?", senior:"dbt debug confirms it can authenticate and reach the warehouse, but it does not exercise create/write privileges on the target schema. A role may connect yet lack CREATE/USAGE on the dev schema or database. The fix is granting the appropriate warehouse privileges (or using a schema the role owns), not changing dbt config." },
  { tier:"intermediate", cat:"CLI", q:"What does dbt source freshness do and when do you run it?", short:"dbt source freshness checks the configured freshness thresholds on sources and reports warn/error based on how stale the data is; you run it to monitor ingestion timeliness.", detailed:"It queries loaded_at_field (or warehouse metadata) per source table, compares to warn_after/error_after, and writes results to sources.json. Teams run it on a schedule before transformations to gate on fresh enough raw data or to alert on stalled pipelines.", mistake:"Running transformations without checking freshness and then wondering why reports are stale.", followup:"How would you gate a dbt build on source freshness?", senior:"Run dbt source freshness first and branch on its exit code or parse sources.json: if a critical source errors, skip or fail the downstream build and alert. In orchestration (Airflow/dbt Cloud), model freshness as an upstream task whose failure short-circuits the transformation job, so you never publish built data on top of stale ingestion." },
  { tier:"fouryear", cat:"Artifacts", q:"What is manifest.json and what is it used for?", short:"manifest.json is the artifact describing the fully parsed project: every node, its config, dependencies, compiled code, and metadata; it powers docs, selection, and state comparison.", detailed:"Produced on parse/compile/run, manifest.json is the serialized DAG and project state. dbt uses it for the docs site, for state:modified selection (comparing a prior manifest), and external tools read it for lineage, catalogs, and metadata. It is the single source of truth about project structure.", mistake:"Confusing manifest.json (project structure) with run_results.json (execution outcomes) or catalog.json (warehouse metadata).", followup:"How does manifest.json enable slim CI?", senior:"By passing a production manifest as --state, dbt compares the current project to it and selects state:modified+ plus using defer to resolve unbuilt refs against prod. This lets CI build only changed models and their descendants instead of the whole project, dramatically cutting CI time and warehouse cost while still testing real dependencies." },
  { tier:"fouryear", cat:"Artifacts", q:"What does run_results.json capture?", short:"run_results.json records the outcome of the most recent invocation: per-node status, timing, row counts, and error messages.", detailed:"After run/test/build/seed/snapshot, dbt writes run_results.json with each executed node's status (success/error/skipped), execution time, and messages. dbt retry reads it to resume failures, and observability tools ingest it to track performance and failures over time.", mistake:"Expecting run_results.json to describe project structure; that is manifest.json.", followup:"How would you build run observability from run_results.json?", senior:"Parse run_results.json after each invocation to load per-node timings and statuses into a monitoring table, trending model runtime, failure rates, and test outcomes. Combined with manifest.json for metadata, you can detect regressions (a model suddenly slow), alert on recurring test failures, and attribute cost, often via packages like dbt_artifacts." },
  { tier:"fouryear", cat:"Artifacts", q:"What is catalog.json and how is it produced?", short:"catalog.json holds warehouse metadata (column names, types, and table stats) for the built objects; dbt docs generate produces it by querying the information schema.", detailed:"Unlike manifest.json which comes from parsing code, catalog.json requires querying the warehouse for the actual materialized objects. dbt docs generate collects this and merges it with the manifest so the docs site shows real column types and statistics, not just declared ones.", mistake:"Assuming catalog.json is built from the code; it requires a warehouse query against existing objects.", followup:"Why might catalog.json be empty or incomplete?", senior:"Because it reflects objects that actually exist in the warehouse. If models were not built, or the role lacks visibility into the information schema/metadata, or you ran docs generate with flags to skip the catalog, columns go missing. Ensure the objects are materialized and the role has metadata read access before generating docs." },
  { tier:"intermediate", cat:"Compilation", q:"How does Jinja compilation work in a dbt model?", short:"dbt renders the model's Jinja (ref, source, macros, control flow, vars) into pure SQL at compile time, then sends that SQL to the warehouse.", detailed:"Models mix SQL with Jinja. During compile, dbt resolves ref()/source() to real relations, expands macros, evaluates loops/conditionals, and substitutes vars/env vars, producing deterministic SQL under target/compiled. The warehouse only ever sees plain SQL, never Jinja.", mistake:"Believing the warehouse understands or executes Jinja directly.", followup:"What is the difference between parse time and run time in Jinja execution?", senior:"Parsing evaluates enough Jinja to build the graph (refs, sources, configs) without running queries; some Jinja (like run_query or adapter calls) only executes at run/compile against the warehouse. This two-phase model is why operations that query the database must guard against the parse phase (e.g. using execute checks) to avoid running during parsing." },
  { tier:"senior", cat:"Compilation", q:"What is the execute flag in dbt Jinja and why does it matter?", short:"execute is a boolean that is false during parsing and true during the actual run/compile phase; you guard warehouse-querying Jinja with it to avoid errors at parse time.", detailed:"dbt parses models in two passes; during parsing execute is false and relations may not yet resolve. Wrapping run_query or results-dependent logic in {% if execute %} prevents it from firing (and failing) during parse, running only when dbt truly executes.", mistake:"Calling run_query unconditionally in a model, which errors or returns None during parsing.", followup:"Give a concrete case where you must check execute.", senior:"A model that dynamically pivots on distinct values fetched from the warehouse: you call run_query to get the column list, but at parse time execute is false and the query result is None. You wrap it as {% if execute %}{% set results = run_query(...) %}{% endif %} and provide a safe fallback so parsing succeeds and the real query runs only at execution." },
  { tier:"scenario", cat:"Environments", q:"A model works in dev but writes to the wrong schema in prod; how do you investigate?", short:"Check the custom schema config and the generate_schema_name macro, and confirm the target schema differs between dev and prod profiles.", detailed:"dbt composes the final schema from the target schema plus any custom +schema config via generate_schema_name. The default macro prefixes the target schema; a custom override may concatenate differently. If prod lands in dev_marts or similar, the macro or the prod target schema is misconfigured.", mistake:"Hard-coding schemas in models to fix it instead of correcting schema generation.", followup:"How would you implement environment-aware schema naming cleanly?", senior:"Override generate_schema_name so that in prod it uses the custom schema as-is (e.g. marts) while in dev it namespaces per developer (e.g. dbt_alice_marts), keyed on target.name. This gives clean production schemas and isolated dev schemas from the same code, with no hard-coded names and correct behavior under both targets." },
  { tier:"scenario", cat:"CI", q:"How would you make CI only build the models a pull request changed?", short:"Use state-based selection against a production manifest: dbt build --select state:modified+ --defer --state path/to/prod/artifacts.", detailed:"Store the prod manifest.json, then in CI run with --select state:modified+ to pick changed models and descendants, and --defer so unbuilt upstream refs resolve to the prod relations. This slim CI builds only the PR's blast radius while still testing against real dependencies.", mistake:"Rebuilding the whole project in CI on every PR, wasting time and warehouse cost.", followup:"What are the risks of defer and how do you mitigate them?", senior:"Defer resolves unselected refs to prod objects, so if prod is stale or you deferred a model that actually changed upstream, you can test against outdated data or miss a real break. Mitigate by keeping the state manifest fresh, including descendants (the +), and periodically running full builds to catch issues slim CI cannot see." },
  { tier:"scenario", cat:"Backfill", q:"You need to backfill one incremental model for a historical date range; how?", short:"Run it with --full-refresh to rebuild, or pass a date var that overrides the incremental window, selecting just that model.", detailed:"For a full rebuild: dbt run --select my_model --full-refresh. For a bounded backfill without rebuilding everything, parameterize the incremental WHERE clause with a var (e.g. start/end dates) and run dbt run --select my_model --vars '{backfill_start: ..., backfill_end: ...}', designing the model to honor those bounds idempotently.", mistake:"Full-refreshing the entire project when only one model needs backfilling.", followup:"How do you make the backfill idempotent?", senior:"Use a merge or delete+insert strategy keyed on the unique/partition key so reprocessing a date range replaces rather than duplicates rows, and bound the window precisely with vars. Then re-running the same backfill produces the same result. On partitioned warehouses, aligning the delete+insert to partition boundaries makes the operation cheap and safe to repeat." },
  { tier:"architecture", cat:"Layering", q:"How do you decide between view, table, and incremental for a mart serving a BI dashboard?", short:"Weigh freshness needs, query frequency, data size, and build cost: views for small/cheap logic, tables for frequently queried heavier logic, incrementals for large append-heavy data where full rebuilds are too costly.", detailed:"If the mart is small and logic is light, a view keeps it always fresh at zero storage. If it is queried often and expensive to compute, a table precomputes once per run for fast reads. If it is huge and mostly append, incremental avoids rebuilding history each run. The decision balances read latency, build time, and cost.", mistake:"Defaulting everything to table or everything to view without considering size and query patterns.", followup:"What signals push you from table to incremental?", senior:"Full-refresh build time and cost growing with history, an append-mostly or clearly time-partitioned load pattern, and a reliable incremental key/timestamp. Once rebuild time threatens the SLA or cost budget and the data is largely immutable once written, incremental (with periodic full-refresh to correct drift) becomes worth its added complexity." },
  { tier:"architecture", cat:"Testing strategy", q:"How do you design a layered testing strategy across staging, intermediate, and marts?", short:"Test primary keys and source assumptions at staging, enforce business-rule and relationship integrity at marts, and reserve heavier custom/singular tests for critical outputs.", detailed:"At staging, assert not_null/unique on keys and accepted_values on enums to catch source drift early. In marts, add relationships (referential integrity), uniqueness of grain, and singular business-logic tests. Use severity and store_failures strategically, and consider source freshness as the first gate.", mistake:"Only testing at the end, so failures surface far from their cause.", followup:"How do you prevent test sprawl while keeping coverage meaningful?", senior:"Focus on grain and contracts: every model should assert its unique grain and not-null keys; push shared assumptions to the staging layer so they are tested once. Use contracts for structural guarantees, reserve singular tests for genuinely business-critical invariants, tune severity to avoid alert fatigue, and track failures via store_failures rather than multiplying redundant generic tests." },
  { tier:"architecture", cat:"Macros", q:"When should logic live in a macro versus a model?", short:"Put reusable, parameterized SQL-generation logic in macros; keep business transformations that produce a dataset in models.", detailed:"Macros are Jinja functions that return SQL snippets, ideal for DRYing up repeated patterns (surrogate keys, date spines, dynamic column lists) and for cross-model utilities. Models represent concrete datasets in the DAG. Overusing macros for core business logic hurts readability and lineage; overusing copy-paste SQL hurts maintainability.", mistake:"Encoding an entire business entity in a macro instead of a model, hiding it from lineage and tests.", followup:"What are downsides of heavy macro use?", senior:"Macros are invisible to the DAG and harder to test directly, they can obscure what SQL actually runs, and deeply nested macro expansion complicates debugging compiled output. They also create implicit coupling. The guideline is macros for mechanical SQL generation and utilities, models for data you want to version, test, document, and see in lineage." },
  { tier:"debugging", cat:"Errors", q:"dbt run fails with Compilation Error: model depends on a node named X which was not found; what is wrong?", short:"A ref() points to a model name that does not exist (typo, deleted model, wrong case, or missing package), so the DAG cannot resolve it.", detailed:"This is a parse-time failure: the referenced node is not in the manifest. Causes include a misspelled model name in ref(), a model that was renamed/removed, a case-sensitivity mismatch, or a package providing the model not installed. dbt cannot build the graph until the ref resolves.", mistake:"Assuming it is a warehouse permission or data issue; it is a graph-resolution problem before any SQL runs.", followup:"How do you systematically locate the bad ref?", senior:"Read the error's node path to find the offending model, inspect its ref() calls, and run dbt ls to confirm the target name exists and is spelled/cased correctly. If it comes from a package, verify dbt deps ran and the package is installed. For renames, grep the project for the old name to catch every stale reference." },
  { tier:"debugging", cat:"Errors", q:"Your model compiles but produces duplicate rows downstream; how do you find the cause?", short:"Check the join grain: a many-to-many or fan-out join is the usual culprit; verify each join key is unique on at least one side.", detailed:"Duplicates after a join mean one side has multiple matching rows per key, fanning out the result. Isolate by compiling the model, then querying intermediate CTEs or using dbt show to count rows per key at each join. Add a unique test on the model's declared grain to catch it.", mistake:"Blindly adding SELECT DISTINCT instead of fixing the join that causes the fan-out.", followup:"Why is DISTINCT a dangerous fix here?", senior:"DISTINCT masks the real grain problem: it can silently collapse legitimately different rows, inflate compute, and break aggregations that depended on the true cardinality. The correct fix is to pre-aggregate or deduplicate the offending side to the right grain before joining, then assert uniqueness with a test so regressions surface instead of being hidden." },
  { tier:"debugging", cat:"Performance", q:"A dbt build has gotten much slower over time; how do you diagnose it?", short:"Parse run_results.json for per-model timings to find the slow nodes, then investigate their materialization, volume growth, and warehouse plan.", detailed:"Use run_results.json (or dbt_artifacts) to rank models by execution time and spot regressions. Common causes: a view that should be a table or incremental, a full-refresh on a growing table, an exploding join, missing clustering/partitioning, or under-sized warehouse/thread count. Target the worst offenders first.", mistake:"Globally bumping warehouse size instead of fixing the specific slow models.", followup:"A single incremental model dominates runtime despite the incremental filter; what might be wrong?", senior:"Likely the incremental predicate is not actually pruning: a non-sargable filter, scanning the whole table in the merge, or a unique_key merge that rewrites large partitions. Inspect the compiled SQL and the warehouse query plan, confirm is_incremental() is applying the bound, align the key to the table's partition/cluster keys, and consider delete+insert on partitions so only touched partitions are rewritten." },
  { tier:"sql", cat:"Window functions", q:"How would you dedupe to the latest record per key in a dbt staging model?", short:"Use row_number() over the key ordered by an updated timestamp and keep rn = 1, typically with qualify where supported.", detailed:"Partition by the business key, order by the update/load timestamp descending, and filter to the first row. On warehouses with QUALIFY (Snowflake, BigQuery) you can do it in one pass; otherwise wrap in a subquery/CTE and filter where rn = 1.", example:"select *\nfrom {{ source('app', 'users') }}\nqualify row_number() over (\n  partition by user_id order by updated_at desc\n) = 1", mistake:"Using DISTINCT, which cannot pick the latest row deterministically.", followup:"What if two rows share the same key and timestamp?", senior:"The ordering is non-deterministic, so you add a tiebreaker to the ORDER BY (a monotonic surrogate like an ingestion sequence, file/offset, or a hash) to make the selection stable and reproducible. Without a deterministic tiebreaker, re-runs can pick different rows, which breaks idempotency and downstream diffs." },
  { tier:"sql", cat:"Grain", q:"What does the grain of a table mean and why does dbt care about it?", short:"Grain is what one row represents (e.g. one order, one order-line); defining it drives correct joins, aggregations, and uniqueness tests.", detailed:"Every model should have a clear grain. Facts are at an event/transaction grain, dimensions at an entity grain. Knowing the grain tells you the primary key to test for uniqueness, prevents fan-out joins, and ensures aggregations are not double-counted. dbt tests encode the grain via a unique test on the key.", mistake:"Building a model without a defined grain, leading to ambiguous joins and double counting.", followup:"How do you enforce grain in dbt?", senior:"Declare a single column (often a generated surrogate key over the grain columns) and add unique and not_null tests on it, or a dbt_utils.unique_combination_of_columns test over the natural grain. Enforcing it in tests means any upstream change that breaks the grain fails the build immediately rather than silently corrupting metrics." },
  { tier:"sql", cat:"Surrogate keys", q:"How do you generate a surrogate key in dbt and why use one?", short:"Use dbt_utils.generate_surrogate_key over the natural-key columns to create a deterministic hash key, giving a single stable column for joins and uniqueness tests.", detailed:"A surrogate key hashes the business/grain columns into one value, so you get a compact, single-column primary key even when the natural key is composite. It is deterministic across runs (same inputs produce the same key), which supports incremental merges and consistent joins.", example:"select\n  {{ dbt_utils.generate_surrogate_key(['order_id', 'line_number']) }} as order_line_sk,\n  *\nfrom {{ ref('stg_order_lines') }}", mistake:"Using a database sequence or row_number for the key, which is not stable across rebuilds.", followup:"Why must a surrogate key be deterministic for incremental models?", senior:"Incremental merges match on the unique_key to update existing rows. If the key changes between runs (as with a sequence or random id), the merge cannot find the prior row and you get duplicates or orphaned history. A hash of the stable natural columns guarantees the same input always maps to the same key, so merges and reprocessing stay idempotent." },
  { tier:"fouryear", cat:"Packages", q:"What is dbt_utils and give examples of what it provides?", short:"dbt_utils is a widely used package of reusable macros and generic tests, such as generate_surrogate_key, date_spine, star, and tests like unique_combination_of_columns.", detailed:"Installed via packages.yml, dbt_utils provides cross-database macros (surrogate keys, pivoting, date spines, get_column_values, star for column selection) and additional generic tests (expression_is_true, equal_rowcount, unique_combination_of_columns), reducing boilerplate and improving portability.", mistake:"Reimplementing common utilities by hand instead of using the maintained, cross-adapter package.", followup:"Why are cross-database macros in dbt_utils valuable?", senior:"They abstract dialect differences (date arithmetic, hashing, concatenation) behind a single macro so the same model compiles correctly across warehouses, and they are maintained and tested by the community. This improves portability for multi-warehouse or migrating projects and avoids each team hand-rolling subtly incompatible SQL for the same operation." },
  { tier:"intermediate", cat:"Selection", q:"How does dbt node selection syntax work with graph operators?", short:"You select nodes with --select using names, paths, tags, and graph operators: + for ancestors/descendants, @ for a model plus its descendants and their ancestors, and n+ for N levels.", detailed:"model+ selects a model and all downstream; +model selects it and all upstream; +model+ both directions; 1+model limits to one level up. You combine with tag:, path:, source:, config:, and state:, and intersect/union with spaces and commas. --exclude removes nodes.", example:"dbt build --select stg_orders+ --exclude tag:deprecated", mistake:"Confusing +model (upstream) with model+ (downstream), running the wrong slice.", followup:"What does the @ operator do that +model+ does not?", senior:"@model selects the model, all its descendants, AND all ancestors of those descendants. This guarantees everything needed to build the full downstream subtree is included even when a descendant depends on a sibling branch, which plain model+ would miss. It is useful when you must rebuild a model and fully materialize everything downstream from scratch." },
  { tier:"scenario", cat:"Deployment", q:"How would you structure dev and prod runs so developers do not clobber production data?", short:"Use separate targets with isolated schemas (per-developer dev schemas via generate_schema_name) and run prod only from CI/orchestration with a dedicated service role.", detailed:"Developers run against a dev target that namespaces schemas per user, so their builds never touch prod objects. Production runs come only from CI/CD or the orchestrator against the prod target using a service account with appropriate grants. State/defer lets devs reference prod reads without writing there.", mistake:"Letting everyone run against a shared prod target from their laptops.", followup:"How do you keep dev environments cheap yet realistic?", senior:"Use defer against the prod manifest so dev builds only the changed models while reading real prod upstreams, limit dev to a smaller warehouse, and optionally sample or limit data via a var-controlled filter in dev. This gives realistic dependencies and output without rebuilding or duplicating full production volume per developer." },
  { tier:"debugging", cat:"Parsing", q:"After editing a macro, dbt still uses the old behavior; what might be happening?", short:"Stale partial-parse state or a not-reinstalled package macro; clear partial parsing or re-run dbt deps and recompile.", detailed:"Partial parsing caches the manifest and may not pick up certain changes, and if the macro lives in a package you must dbt deps to update it. Symptoms are code changes that seem ignored. Running dbt clean / deleting target/partial_parse.msgpack, then recompiling, forces a fresh parse.", mistake:"Assuming the warehouse is caching results when the issue is local parse state.", followup:"What kinds of changes does partial parsing fail to detect?", senior:"Changes that live outside tracked files or that it cannot reliably invalidate, such as certain environment variable or var changes, external files a macro reads, or edits to files not in the watched paths. When behavior looks stale, disable partial parsing (--no-partial-parse) or clear the cache to confirm, then address the untracked dependency explicitly." },
  { tier:"architecture", cat:"Multi-warehouse", q:"What should you consider when a dbt project must support more than one warehouse adapter?", short:"Favor cross-database macros and dbt_utils, avoid adapter-specific SQL and functions, and isolate any unavoidable dialect differences behind macros with adapter.dispatch.", detailed:"Date functions, string ops, qualify support, incremental strategies, and constraint enforcement differ across Snowflake, BigQuery, Redshift, Databricks, and Postgres. Writing portable SQL, using dispatchable macros, and testing on each adapter in CI keeps one codebase working everywhere.", mistake:"Assuming SQL that works on one warehouse runs unchanged on another.", followup:"How does adapter.dispatch enable portable macros?", senior:"adapter.dispatch resolves a macro name to an adapter-specific implementation (e.g. my_macro__snowflake vs my_macro__bigquery) at runtime based on the active adapter, with a default fallback. This lets a package expose one macro interface while supplying dialect-specific bodies, so consumers call it uniformly and the right SQL is generated per warehouse, which is exactly how dbt_utils achieves cross-database support." },
  { tier:"intermediate", cat:"Layering", q:"How do staging, intermediate, and marts layers differ in a dbt project?", short:"Staging cleans and renames one source 1:1; intermediate holds reusable business logic / joins; marts are the final dimensional tables consumers query.", detailed:"Staging models are thin views over a single source: rename columns, cast types, basic cleaning, usually one staging model per source table. Intermediate models compose staging models into reusable building blocks (joins, aggregations, fan-outs resolved). Marts expose business entities (facts and dimensions) at a defined grain for BI. The separation keeps logic DRY and makes lineage legible.", example:"-- stg_orders.sql (1:1 with source)\nselect\n  id        as order_id,\n  user_id   as customer_id,\n  cast(amount as numeric(18,2)) as order_amount,\n  created_at\nfrom {{ source('shop', 'orders') }}", mistake:"Putting joins and business logic in staging, or letting marts read raw sources directly.", followup:"Where would you put a calculation shared by three different marts?", senior:"Staging is a contract/interface over sources; intermediate is where reusable, often ephemeral/CTE-like logic lives; marts own grain and semantics. Enforce the boundary with naming conventions and selectors so lineage stays acyclic and sources are referenced only by staging." },
  { tier:"intermediate", cat:"Fact vs dimension", q:"What distinguishes a fact table from a dimension table?", short:"Facts record measurable events at a grain (one row per event, numeric measures + foreign keys); dimensions describe entities with descriptive attributes used to slice facts.", detailed:"A fact table stores business events or measurements (orders, payments, clicks) with additive/semi-additive numeric measures and foreign keys to dimensions. A dimension table (customer, product, date) holds descriptive, relatively slowly changing attributes you filter and group by. Facts are long and narrow-ish and grow quickly; dimensions are wider and smaller.", example:"-- fct_orders: grain = one row per order\nselect order_id, customer_id, order_date, order_amount\nfrom {{ ref('stg_orders') }}\n\n-- dim_customers: grain = one row per customer\nselect customer_id, customer_name, country, signup_date\nfrom {{ ref('stg_customers') }}", mistake:"Treating a table as a fact just because it has numbers, or storing descriptive attributes redundantly on the fact.", followup:"Is a daily account-balance snapshot a fact or a dimension?", senior:"Facts are additive measures tied to a grain; classify measures as additive, semi-additive (balances, over time) or non-additive (ratios). A balance snapshot is a semi-additive periodic-snapshot fact, not a dimension." },
  { tier:"sql", cat:"Grain", q:"Why is declaring the grain of a model the first thing you do, and how do you state it?", short:"The grain is the uniqueness definition (what one row means). State it as the column set that is unique, then test it.", detailed:"Grain is the business meaning of a single row (e.g. one row per order line per day). Everything else - which joins are safe, which aggregations are correct - follows from it. You declare it in a comment/doc and enforce it with a uniqueness test on the grain columns.", example:"-- grain: one row per (order_id, line_number)\nselect order_id, line_number, quantity, line_amount\nfrom {{ ref('stg_order_lines') }}\n\n-- schema.yml test\n-- tests:\n--   - dbt_utils.unique_combination_of_columns:\n--       combination_of_columns: [order_id, line_number]", mistake:"Not declaring grain, then silently changing it with a join.", followup:"How would you detect that a join accidentally changed the grain?", senior:"Grain is an invariant; I assert it with a unique_combination_of_columns test at the model boundary so any accidental fan-out fails CI rather than inflating metrics silently downstream." },
  { tier:"scenario", cat:"Grain", q:"A revenue number doubled after someone added a join - how does a join inflate a measure, and how do you fix it?", short:"Joining to a table that has multiple matching rows per key fans out the fact rows, so the additive measure is summed multiple times. Fix by aggregating/deduping the right side to the join grain first.", detailed:"If you join fct_orders (one row per order) to a table with many rows per order (e.g. order_events), each order row is duplicated once per matching event, and SUM(order_amount) multiplies. The fix is to pre-aggregate or deduplicate the right-hand side to one row per order_id before joining, or use a scalar subquery / window so the fact grain is preserved.", example:"-- WRONG: fans out, revenue doubles\nselect o.order_id, sum(o.order_amount) as rev\nfrom orders o\njoin order_events e on e.order_id = o.order_id\ngroup by 1;\n\n-- RIGHT: aggregate events to order grain first\nwith ev as (\n  select order_id, count(*) as n_events\n  from order_events group by 1\n)\nselect o.order_id, o.order_amount, ev.n_events\nfrom orders o\nleft join ev on ev.order_id = o.order_id;", mistake:"Adding SELECT DISTINCT to hide the fan-out, which does not fix a summed measure.", followup:"Why does DISTINCT not fix a doubled SUM?", senior:"A join that changes cardinality changes grain; I pre-aggregate the many-side to the fact grain (or use a window over a partition) so measures stay additive, and I add a row-count regression test to catch future fan-outs." },
  { tier:"intermediate", cat:"Keys", q:"When would you use a surrogate key instead of a natural key?", short:"Use a surrogate (hashed/generated) key when the natural key is composite, mutable, or absent, or when you need a stable single-column join key across SCD versions.", detailed:"A natural (business) key comes from the source (email, SKU). A surrogate key is generated, typically a hash of the grain columns, giving a single stable column that is immune to source key changes and works for SCD Type 2 where the same business entity has multiple versioned rows. dbt_utils.generate_surrogate_key is the idiomatic way.", example:"-- stable single-column key from the grain\nselect\n  {{ dbt_utils.generate_surrogate_key(['order_id', 'line_number']) }} as order_line_sk,\n  order_id, line_number, line_amount\nfrom {{ ref('stg_order_lines') }}", mistake:"Hashing a mutable or non-grain set of columns, producing unstable or non-unique surrogate keys.", followup:"What columns do you hash for an SCD Type 2 dimension surrogate key?", senior:"Surrogate keys decouple joins from source identity; for SCD2 I hash the natural key plus the effective-from timestamp so each version is unique while the natural key stays the join-through for current-state lookups." },
  { tier:"sql", cat:"Dedup", q:"Write a query to keep only the latest row per customer using ROW_NUMBER.", short:"Partition by the business key, order by the recency column descending, and keep rn = 1.", detailed:"ROW_NUMBER assigns a unique sequence within each partition. Partition by the key that defines uniqueness and order by the tiebreaker (updated_at, plus a deterministic secondary tiebreaker to avoid nondeterminism on ties).", example:"with ranked as (\n  select *,\n    row_number() over (\n      partition by customer_id\n      order by updated_at desc, id desc\n    ) as rn\n  from raw_customers\n)\nselect * from ranked where rn = 1;", mistake:"Using DISTINCT or GROUP BY, which cannot pick a full latest row, or ordering by a non-unique column so ties are nondeterministic.", followup:"How would you rewrite this with QUALIFY, and where does QUALIFY work?", senior:"row_number with a deterministic ORDER BY (including a unique tiebreaker) is the correct latest-wins dedup; I add the secondary key so the result is reproducible across runs and warehouses." },
  { tier:"sql", cat:"Dedup", q:"How does QUALIFY simplify a latest-wins dedup, and which warehouses support it?", short:"QUALIFY filters on a window function result without a subquery. It exists on Snowflake, BigQuery, Databricks and DuckDB, but NOT on Postgres or Redshift.", detailed:"QUALIFY is to window functions what HAVING is to aggregates: it lets you filter rows by a window expression inline. It removes the CTE/subquery wrapper around row_number. On Postgres/Redshift you must fall back to the subquery + WHERE rn = 1 pattern.", example:"-- Snowflake / BigQuery / Databricks / DuckDB\nselect *\nfrom raw_customers\nqualify row_number() over (\n  partition by customer_id order by updated_at desc, id desc\n) = 1;", mistake:"Assuming QUALIFY is ANSI/portable and using it in a Postgres or Redshift model.", followup:"How would you make a dedup macro work across both QUALIFY and non-QUALIFY adapters?", senior:"QUALIFY is adapter-specific; in a cross-warehouse dbt project I gate it on target.type or just use the portable subquery pattern so the same model compiles on Redshift and Snowflake." },
  { tier:"sql", cat:"Window functions", q:"Compute a running total of daily revenue ordered by date.", short:"SUM over an ordered window with a frame from the start up to the current row.", detailed:"A running/cumulative total uses SUM() OVER (ORDER BY ...) with a frame of UNBOUNDED PRECEDING to CURRENT ROW. Be explicit about the frame; the default frame with ORDER BY is RANGE UNBOUNDED PRECEDING to CURRENT ROW, which ties same-date rows together.", example:"select\n  order_date,\n  daily_revenue,\n  sum(daily_revenue) over (\n    order by order_date\n    rows between unbounded preceding and current row\n  ) as running_revenue\nfrom daily_rev;", mistake:"Omitting the frame and getting RANGE semantics that lump tied dates together unexpectedly.", followup:"What changes if you use RANGE instead of ROWS here?", senior:"I specify ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW explicitly; with duplicate order_date values RANGE would assign every tied row the same cumulative sum, which is usually not what a running total should do." },
  { tier:"sql", cat:"Window functions", q:"Explain the difference between ROWS and RANGE window frames.", short:"ROWS counts physical rows around the current row; RANGE groups rows by ORDER BY value, so peers (equal values) are treated as one unit.", detailed:"ROWS BETWEEN n PRECEDING AND CURRENT ROW looks at a fixed number of rows. RANGE defines the frame by the ordering values: all rows with the same ORDER BY value fall in the same frame position, so ties are included together. This matters for cumulative sums and moving averages when the order column has duplicates.", example:"-- ROWS: physical 3-row moving sum\nsum(x) over (order by dt rows between 2 preceding and current row)\n\n-- RANGE: all rows sharing dt collapse into the frame\nsum(x) over (order by dt range between unbounded preceding and current row)", mistake:"Believing ROWS and RANGE are always equivalent; they differ whenever the ORDER BY column has duplicates.", followup:"Which do you want for a trailing-3-row moving average?", senior:"For a fixed-window moving average I use ROWS; for value-based windows (e.g. all rows within the same day or a numeric interval) I use RANGE, and I never rely on the implicit default frame." },
  { tier:"sql", cat:"Window functions", q:"When would you use RANK vs DENSE_RANK vs ROW_NUMBER?", short:"ROW_NUMBER is always unique; RANK leaves gaps after ties; DENSE_RANK has no gaps after ties.", detailed:"For the same ORDER BY: ROW_NUMBER gives 1,2,3,4 regardless of ties. RANK gives 1,1,3,4 (skips 2 after a tie). DENSE_RANK gives 1,1,2,3 (no gap). Use ROW_NUMBER for dedup/picking one row, RANK/DENSE_RANK for leaderboards where ties should share a position.", example:"select name, score,\n  row_number() over (order by score desc) as rn,\n  rank()       over (order by score desc) as rnk,\n  dense_rank() over (order by score desc) as drnk\nfrom results;", mistake:"Using RANK for deduplication, which can return multiple rows at rank 1 on ties.", followup:"Why is ROW_NUMBER the right choice for picking exactly one row per key?", senior:"ROW_NUMBER guarantees exactly one row per partition when deduping; RANK/DENSE_RANK are for ranking semantics where tie-sharing is desired, and I add a deterministic tiebreaker to ROW_NUMBER so the survivor is stable." },
  { tier:"sql", cat:"Window functions", q:"Use LAG to compute day-over-day change in revenue.", short:"LAG pulls the prior row value within an ordered partition; subtract it from the current value.", detailed:"LAG(col, 1) returns the value from the previous row by the ORDER BY. The default for the first row is NULL unless you supply a default. Partition by the entity if you have multiple series.", example:"select\n  customer_id, order_date, revenue,\n  revenue - lag(revenue) over (\n    partition by customer_id order by order_date\n  ) as dod_change\nfrom daily_customer_rev;", mistake:"Forgetting PARTITION BY, so LAG bleeds across different customers/series.", followup:"How do you handle the NULL on the first row of each partition?", senior:"LAG with PARTITION BY isolates each series; I pass a default (e.g. lag(revenue,1,0)) or COALESCE depending on whether first-period change should be NULL or the full value, and document which." },
  { tier:"sql", cat:"Window functions", q:"How do you test that a window-function result in a dbt model is correct?", short:"Assert invariants: uniqueness of the chosen row, no partition bleed, and a reconciliation of the aggregate against an independent GROUP BY.", detailed:"Window logic is easy to get subtly wrong. Test the output grain with a uniqueness test, test that a running total's final value per partition equals the plain SUM via a relationship/accepted-values or a custom singular test, and test for NULLs where none should exist.", example:"-- singular test: windowed cumulative final = plain sum\nselect customer_id\nfrom (\n  select customer_id,\n    max(running_revenue) as win_total,\n    sum(daily_revenue)   as agg_total\n  from {{ ref('cust_running') }}\n  group by 1\n) t\nwhere win_total <> agg_total;", mistake:"Eyeballing a few rows instead of writing a reconciliation test.", followup:"What test catches a missing PARTITION BY?", senior:"I reconcile the window result against an independent aggregation in a singular test; a mismatch flags frame or partition errors, and I pair it with a uniqueness test on the output grain." },
  { tier:"intermediate", cat:"SCD", q:"What is an SCD Type 2 dimension and how does dbt snapshot implement it?", short:"SCD2 keeps full history by adding a new row each time a tracked attribute changes, with validity timestamps. dbt snapshots implement it with dbt_valid_from / dbt_valid_to columns.", detailed:"A Type 2 slowly changing dimension versions each change: the old row is closed (valid_to set) and a new row opened. dbt snapshots use a strategy (timestamp or check) to detect changes and maintain dbt_valid_from, dbt_valid_to (NULL for current), and dbt_scd_id. This preserves point-in-time history for as-of joins.", example:"{% snapshot customers_snap %}\n{{ config(\n  target_schema='snapshots',\n  unique_key='customer_id',\n  strategy='check',\n  check_cols=['plan', 'country']\n) }}\nselect customer_id, plan, country, updated_at\nfrom {{ source('app', 'customers') }}\n{% endsnapshot %}", mistake:"Overwriting the dimension in place (Type 1) when history is needed, losing point-in-time truth.", followup:"How do you join a fact to the correct historical version of a dimension?", senior:"SCD2 captures history as closed intervals; I join facts to the version where event_time is between dbt_valid_from and dbt_valid_to (treating NULL valid_to as current) for a correct as-of join." },
  { tier:"sql", cat:"SCD", q:"Write an as-of join matching each fact to the dimension version valid at the event time.", short:"Join on the key and a time-between predicate against the SCD2 validity interval, treating NULL valid_to as open.", detailed:"Point-in-time correctness means the dimension attributes as they were when the event happened. Join on the natural key and event_time >= valid_from and event_time < valid_to (or valid_to is null). Half-open intervals avoid double matches at boundaries.", example:"select f.order_id, f.event_time, d.plan\nfrom fct_orders f\njoin dim_customers_scd d\n  on d.customer_id = f.customer_id\n and f.event_time >= d.dbt_valid_from\n and (f.event_time < d.dbt_valid_to or d.dbt_valid_to is null);", mistake:"Joining only on the key and getting every historical version (fan-out), or using closed intervals and double-matching at boundaries.", followup:"Why use a half-open interval [from, to)?", senior:"Half-open intervals guarantee exactly one matching version per event; I treat NULL valid_to as current and verify with a uniqueness test that the as-of join does not fan out the fact grain." },
  { tier:"scenario", cat:"Late-arriving", q:"How do you handle a late-arriving fact whose dimension version did not exist yet?", short:"Match on the as-of interval; if no version covers the event time, assign a late-arriving/unknown dimension member or backfill the dimension and reprocess.", detailed:"A late-arriving fact is a late event against an existing dimension - solved by the as-of join. The hard case is a fact referencing a dimension key with no row at that time (early-arriving fact / late dimension): you either route it to an inferred \"unknown\" member (-1 surrogate key) and update later, or you backfill an early-effective dimension row.", example:"-- route unmatched facts to the unknown member\nselect f.*,\n  coalesce(d.customer_sk, -1) as customer_sk\nfrom fct_orders f\nleft join dim_customers_scd d\n  on d.customer_id = f.customer_id\n and f.event_time >= d.dbt_valid_from\n and (f.event_time < d.dbt_valid_to or d.dbt_valid_to is null);", mistake:"Dropping facts that have no matching dimension version, silently losing revenue.", followup:"What is the difference between a late-arriving fact and a late-arriving dimension?", senior:"I never inner-join facts to dimensions; I LEFT JOIN with as-of logic and a -1 unknown member so unmatched facts are retained and auditable, then reconcile once the dimension backfills." },
  { tier:"sql", cat:"Null handling", q:"Why can COUNT, AVG, and = behave surprisingly with NULLs, and how do you guard against it?", short:"NULL means unknown: it is excluded from COUNT(col) and AVG, and any comparison with = yields NULL (not true). Use IS NULL, COALESCE, and COUNT(*) deliberately.", detailed:"COUNT(col) skips NULLs while COUNT(*) counts rows. AVG ignores NULLs in both numerator and denominator. x = NULL is never true; use IS [NOT] DISTINCT FROM or IS NULL. NULLs also drop rows silently in inner joins and in WHERE col <> value.", example:"-- NULL-safe equality and null handling\nselect\n  count(*)            as rows_total,\n  count(discount)     as rows_with_discount,\n  avg(coalesce(discount, 0)) as avg_discount_incl_zero\nfrom orders\nwhere status is distinct from 'cancelled';", mistake:"Writing WHERE status <> 'cancelled' and silently dropping rows where status IS NULL.", followup:"Why does WHERE col <> 'x' exclude NULL rows?", senior:"NULL propagates three-valued logic; I use IS [NOT] DISTINCT FROM for null-safe comparisons, choose COUNT(*) vs COUNT(col) deliberately, and COALESCE before arithmetic to avoid silent row loss and skewed averages." },
  { tier:"sql", cat:"Date logic", q:"How do you correctly bucket events into days when data is stored in UTC but the business reports in a local time zone?", short:"Convert the UTC timestamp to the business time zone before truncating to a date, so day boundaries align with local midnight.", detailed:"Truncating a UTC timestamp to date puts events near midnight in the wrong local day. Convert to the target zone first (AT TIME ZONE on Postgres, CONVERT_TIMEZONE on Snowflake/Redshift, TIMESTAMP in zone on BigQuery), then DATE_TRUNC. Store the zone as metadata, do not hardcode offsets (DST breaks fixed offsets).", example:"-- Snowflake\nselect date_trunc('day',\n  convert_timezone('UTC', 'America/New_York', event_ts)) as local_day,\n  count(*) as events\nfrom events group by 1;\n\n-- Postgres\n-- date_trunc('day', event_ts at time zone 'America/New_York')", mistake:"Subtracting a fixed interval (e.g. -5 hours) and getting DST wrong twice a year.", followup:"Why is a hardcoded UTC offset wrong for a zone that observes DST?", senior:"Named time zones handle DST; I convert to the named business zone before DATE_TRUNC, keep timestamps in UTC at the storage layer, and surface the reporting zone as a documented variable rather than a magic offset." },
  { tier:"sql", cat:"Financial precision", q:"Why should monetary values use NUMERIC/DECIMAL rather than FLOAT, and how does rounding order matter?", short:"FLOAT is binary and cannot represent many decimals exactly, causing cent drift. Use NUMERIC(p,s); and round once at the reporting boundary, not mid-calculation.", detailed:"Floating point introduces representation error that accumulates over sums, so totals can be off by cents. DECIMAL/NUMERIC stores exact base-10 values. Also, rounding each row then summing can diverge from summing then rounding; define and apply a single rounding policy (usually sum in full precision, round at the end) consistently with finance.", example:"-- keep full precision through aggregation, round at the boundary\nselect\n  order_id,\n  round(sum(unit_price * quantity), 2) as order_total\nfrom order_lines\ngroup by 1;  -- unit_price/quantity are numeric(18,4)", mistake:"Using FLOAT for currency, or rounding each line item before summing and then failing reconciliation by a cent.", followup:"When is it correct to round per line instead of at the end?", senior:"Currency is NUMERIC with an explicit scale; I carry extra scale through intermediate math and round once at the presentation grain - unless the business invoices per line, in which case rounding is a per-line rule I encode and test for reconciliation." },
  { tier:"sql", cat:"Joins", q:"Find customers with no orders (orphans / anti-join).", short:"Use a LEFT JOIN with the right key IS NULL, or NOT EXISTS - both express an anti-join.", detailed:"An anti-join returns rows in the left table with no match on the right. LEFT JOIN ... WHERE right.key IS NULL and NOT EXISTS are the two standard forms. Prefer NOT EXISTS over NOT IN because NOT IN returns no rows if the subquery contains any NULL.", example:"-- NOT EXISTS (NULL-safe anti-join)\nselect c.customer_id\nfrom dim_customers c\nwhere not exists (\n  select 1 from fct_orders o\n  where o.customer_id = c.customer_id\n);", mistake:"Using NOT IN against a subquery that can return NULL, which yields an empty result set unexpectedly.", followup:"Why can NOT IN silently return nothing?", senior:"NOT EXISTS is my default anti-join because it is NULL-safe and often optimizes to an anti-semi-join; NOT IN is a trap when the inner set contains NULL due to three-valued logic." },
  { tier:"intermediate", cat:"Joins", q:"How do you safely handle a many-to-many relationship between two entities?", short:"Introduce a bridge/junction table at the pair grain, and never let a many-to-many join directly feed an additive measure without resolving allocation.", detailed:"A many-to-many (e.g. orders to promotions) must be modeled through a bridge table with one row per associated pair. Joining a fact through a bridge fans out measures, so you either report counts, or apply an allocation factor (weighting) so the measure stays additive after the join.", example:"-- bridge grain: one row per (order, promo)\nselect order_id, promo_id,\n  1.0 / count(*) over (partition by order_id) as alloc_weight\nfrom order_promos;\n-- then revenue * alloc_weight stays additive across promos", mistake:"Joining fact to dimension through a many-to-many and summing the measure, double counting it.", followup:"How does an allocation weight keep a measure additive across a bridge?", senior:"I model M:N as an explicit bridge and, when attributing an additive measure across the many side, multiply by an allocation factor that sums to 1 per fact row so totals reconcile to the un-bridged fact." },
  { tier:"sql", cat:"Pivoting", q:"Pivot order counts by status into columns without a PIVOT clause.", short:"Use conditional aggregation: SUM(CASE WHEN status = ... THEN 1 ELSE 0 END) per target column.", detailed:"Conditional aggregation is the portable pivot: one aggregate per output column filtered by a CASE. It works on every warehouse, unlike dialect-specific PIVOT. dbt_utils.pivot can generate it. FILTER (WHERE ...) is a cleaner ANSI form where supported.", example:"select\n  customer_id,\n  count(*) filter (where status = 'paid')     as paid_orders,\n  count(*) filter (where status = 'refunded') as refunded_orders,\n  count(*) filter (where status = 'pending')  as pending_orders\nfrom orders\ngroup by 1;  -- or sum(case when ... then 1 else 0 end)", mistake:"Relying on a warehouse-specific PIVOT and breaking portability, or forgetting ELSE 0 and getting NULLs.", followup:"How would you generate pivot columns dynamically in dbt?", senior:"Conditional aggregation (FILTER where available, else CASE) is my portable pivot; for a dynamic column set I generate the CASE expressions from a macro over a known values list so the pivot stays declarative." },
  { tier:"sql", cat:"Reconciliation", q:"How do you reconcile a mart total against the source system?", short:"Aggregate both sides to a shared grain (e.g. per day) and compare totals; assert equality (within a tolerance) in a test.", detailed:"Reconciliation builds confidence that transformations did not lose or inflate data. Pick a grain present in both source and mart, sum the measure on each, full-outer-join on the grain, and surface any difference beyond tolerance as a failing test. Tolerance accounts for legitimate rounding only.", example:"select coalesce(s.d, m.d) as d,\n  s.src_total, m.mart_total,\n  abs(coalesce(s.src_total,0) - coalesce(m.mart_total,0)) as diff\nfrom (select date(created_at) d, sum(amount) src_total from raw.orders group by 1) s\nfull outer join (select order_date d, sum(order_amount) mart_total from fct_orders group by 1) m\n  on s.d = m.d\nwhere abs(coalesce(s.src_total,0) - coalesce(m.mart_total,0)) > 0.01;", mistake:"Comparing only grand totals, which can hide offsetting per-day errors.", followup:"Why reconcile per grain rather than just the grand total?", senior:"I reconcile at a shared grain with a full outer join so offsetting errors cannot cancel, bound the diff by a rounding tolerance, and wire it as a singular test that fails CI on drift." },
  { tier:"intermediate", cat:"Incremental", q:"How does an incremental dbt model avoid reprocessing all history, and what guards correctness?", short:"It filters new/changed source rows using is_incremental() and an updated_at watermark, then merges on a unique_key. A late-arriving window and unique_key prevent gaps and duplicates.", detailed:"Incremental models only transform rows newer than what is already built. The is_incremental() block adds a predicate like updated_at > (select max from this). A unique_key enables merge/upsert so updates are not duplicated. Use a lookback window to catch late data and backfill with --full-refresh when logic changes.", example:"{{ config(materialized='incremental', unique_key='order_id') }}\nselect * from {{ ref('stg_orders') }}\n{% if is_incremental() %}\nwhere updated_at > (select max(updated_at) from {{ this }})\n  -- lookback for late data:\n  -- > (select max(updated_at) - interval '3 days' from {{ this }})\n{% endif %}", mistake:"Filtering on an append-only id when rows can be updated, or omitting unique_key so merges duplicate.", followup:"How do you catch records that arrive late relative to the watermark?", senior:"Incremental correctness rests on the right watermark column, a unique_key for idempotent upserts, and a lookback window for late data; I design the model so a full-refresh reproduces the same result as incremental runs." },
  { tier:"scenario", cat:"Correctness", q:"Give an example of technically valid SQL that returns a wrong business result.", short:"A LEFT JOIN plus a WHERE filter on the right table silently becomes an INNER JOIN, dropping the unmatched rows you meant to keep.", detailed:"The query parses and runs, but putting right.col = x in WHERE rather than the ON clause nullifies the LEFT JOIN semantics, because WHERE evaluates after the join and NULLs from unmatched rows fail the predicate. The business intent (keep all left rows) is violated.", example:"-- WRONG: becomes inner join, loses customers with no 2024 order\nselect c.customer_id, o.order_id\nfrom customers c\nleft join orders o on o.customer_id = c.customer_id\nwhere o.order_date >= '2024-01-01';\n\n-- RIGHT: filter in the ON clause\nselect c.customer_id, o.order_id\nfrom customers c\nleft join orders o on o.customer_id = c.customer_id\n and o.order_date >= '2024-01-01';", mistake:"Assuming a filter position does not change LEFT JOIN results.", followup:"Where else does predicate placement change results - HAVING vs WHERE?", senior:"Filters on the outer-joined table belong in the ON clause; in WHERE they demote a LEFT JOIN to INNER. I audit outer joins for right-side WHERE predicates as a standard correctness check." },
  { tier:"sql", cat:"Dedup", q:"Deduplicate by business key keeping the latest, then test uniqueness.", short:"row_number over the business key ordered by recency, keep rn=1, and assert uniqueness of the business key downstream.", detailed:"Latest-wins dedup combines a window filter with a uniqueness contract. After selecting rn=1, the business key must be unique; a dbt unique test (or unique_combination_of_columns) enforces it so a future source change that breaks uniqueness fails CI.", example:"with ranked as (\n  select *, row_number() over (\n    partition by customer_email\n    order by updated_at desc, source_id desc) as rn\n  from stg_customers_raw\n)\nselect * from ranked where rn = 1;\n-- schema.yml: columns: customer_email: tests: [unique, not_null]", mistake:"Deduping but never testing, so a new duplicate source silently reintroduces fan-out downstream.", followup:"What breaks if two source rows have identical updated_at?", senior:"I pair latest-wins dedup with a deterministic tiebreaker and a unique test on the business key, so ties are resolved reproducibly and any regression in source uniqueness is caught at build time." },
  { tier:"sql", cat:"Aggregation", q:"Why can COUNT(DISTINCT) over a fanned-out join give the right count but SUM give the wrong total?", short:"COUNT(DISTINCT) de-duplicates the inflated key set, but SUM blindly adds every duplicated row, so the measure is multiplied by the fan-out factor.", detailed:"After a join fans out the fact, distinct keys are unchanged so COUNT(DISTINCT order_id) is still correct, but the additive measure now appears multiple times, so SUM(amount) multiplies. This is why a dashboard can show the right order count yet wrong revenue.", example:"-- after joining orders to multiple shipments per order:\nselect\n  count(distinct order_id) as orders,   -- correct\n  sum(order_amount)        as revenue   -- WRONG, inflated\nfrom orders_x_shipments;", mistake:"Trusting that a correct distinct count implies the SUM is also correct.", followup:"How would you get a correct SUM here without removing the join?", senior:"Distinct counts survive fan-out but additive sums do not; I either aggregate the many-side to the fact grain before summing, or divide by the duplication count per key - and I treat a correct count next to a wrong sum as the classic fan-out signature." },
  { tier:"sql", cat:"Date logic", q:"Generate a continuous date spine to fill gaps in a daily time series.", short:"Build a complete calendar (date spine) and LEFT JOIN the sparse data onto it, COALESCEing measures to 0.", detailed:"Sparse event data has missing days; downstream running totals and moving averages need every day present. Generate a date spine (dbt_utils.date_spine or generate_series) covering the range, then LEFT JOIN actual data and COALESCE null measures to 0.", example:"with spine as (\n  {{ dbt_utils.date_spine(\n    datepart=\"day\",\n    start_date=\"cast('2024-01-01' as date)\",\n    end_date=\"cast('2024-12-31' as date)\") }}\n)\nselect s.date_day,\n  coalesce(sum(o.order_amount), 0) as revenue\nfrom spine s\nleft join fct_orders o on o.order_date = s.date_day\ngroup by 1;", mistake:"Computing moving averages directly on sparse data, so missing days shift the window incorrectly.", followup:"Why does a date spine matter for a 7-day moving average?", senior:"A date spine guarantees a dense axis so ROWS-based windows count real days, not just present rows; I left-join actuals onto the spine and COALESCE measures so gaps read as zero rather than being skipped." },
  { tier:"sql", cat:"Grain", q:"A periodic snapshot fact has one row per account per day - why can you not SUM the balance across days?", short:"Balance is semi-additive: additive across accounts within a day, but not across days. Summing over days double-counts; use the end-of-period value or an average instead.", detailed:"In a periodic snapshot (e.g. daily balances), the measure is a state, not a flow. It is additive across the account dimension on a single day but not across the time dimension. To aggregate over time you take the latest snapshot (closing balance) or a time-average, never a plain SUM.", example:"-- closing balance per account for the month\nselect account_id,\n  max(snapshot_date) as as_of,\n  (array_agg(balance order by snapshot_date desc))[1] as closing_balance\nfrom daily_balances\nwhere snapshot_date between '2024-06-01' and '2024-06-30'\ngroup by account_id;", mistake:"Summing a balance over the time dimension and reporting a meaningless inflated figure.", followup:"Which aggregations are valid for a semi-additive measure over time?", senior:"Semi-additive balances aggregate with LAST/closing or AVG over time but never SUM; I document each measure as additive, semi-additive, or non-additive so the semantic layer applies the correct aggregation per dimension." },
  { tier:"sql", cat:"Window functions", q:"Compute a 7-day trailing moving average of revenue per customer.", short:"AVG over a window partitioned by customer, ordered by date, framed ROWS 6 PRECEDING to CURRENT ROW (on a dense date axis).", detailed:"A trailing N-day average uses ROWS BETWEEN 6 PRECEDING AND CURRENT ROW to cover 7 rows. This is only a true 7-day average if the series is dense (one row per day); otherwise join to a date spine first so gaps count as zero days.", example:"select customer_id, date_day, revenue,\n  avg(revenue) over (\n    partition by customer_id order by date_day\n    rows between 6 preceding and current row\n  ) as ma7\nfrom customer_daily_rev;  -- dense via date spine", mistake:"Running the window on sparse data so 7 rows span more than 7 calendar days.", followup:"How would you express a true 7-calendar-day window with RANGE instead?", senior:"For a strict calendar window I either densify with a date spine and use ROWS, or use RANGE with a date interval where the adapter supports interval ranges; I never assume rows map one-to-one to days." },
  { tier:"intermediate", cat:"Testing", q:"What dbt tests would you add to a fact table to protect its grain and relationships?", short:"A uniqueness test on the grain, not_null on keys and measures, relationships tests to each dimension, and accepted_values on status enums.", detailed:"Grain is protected by unique/unique_combination_of_columns; referential integrity by relationships tests pointing at dimension keys; completeness by not_null; domain validity by accepted_values. Add custom singular tests for reconciliation and for measures that should be non-negative.", example:"# schema.yml\nmodels:\n  - name: fct_orders\n    tests:\n      - dbt_utils.unique_combination_of_columns:\n          combination_of_columns: [order_id]\n    columns:\n      - name: customer_id\n        tests:\n          - not_null\n          - relationships:\n              to: ref('dim_customers')\n              field: customer_id", mistake:"Testing only not_null and skipping grain uniqueness and referential integrity.", followup:"What does a relationships test catch that not_null does not?", senior:"I treat tests as the model's executable contract: grain uniqueness, referential integrity to every dimension, enum domains, and reconciliation singular tests - so a breaking source change fails the build instead of a dashboard." },
  { tier:"sql", cat:"Joins", q:"How do you detect which side of a join causes a fan-out before it corrupts a measure?", short:"Check cardinality: count distinct keys vs row count on each side; if the join key is not unique on a side, that side fans out.", detailed:"Before joining, verify the join key is unique on at least one side. A quick audit compares COUNT(*) to COUNT(DISTINCT key); if they differ, that table has multiple rows per key and will multiply the other side. dbt_utils.unique_combination_of_columns formalizes this as a test.", example:"-- audit: is customer_id unique in this table?\nselect count(*)              as rows,\n       count(distinct customer_id) as keys,\n       count(*) - count(distinct customer_id) as dup_rows\nfrom dim_customers;  -- dup_rows > 0 means fan-out risk", mistake:"Assuming a dimension key is unique without testing it.", followup:"What test would make this a permanent guardrail?", senior:"I confirm the join key is unique on the one-side with a dbt unique test, so I know every join is 1:N (safe) rather than N:M; the count-vs-distinct audit is my quick manual check before adding the test." },
  { tier:"sql", cat:"Null handling", q:"How does COALESCE differ from NULLIF, and when do you use each?", short:"COALESCE returns the first non-null argument (replace NULLs); NULLIF returns NULL when two values are equal (create NULLs, e.g. to avoid divide-by-zero).", detailed:"COALESCE(a, b, c) picks the first non-null, used to default missing values. NULLIF(a, b) returns NULL if a = b else a, commonly to turn 0 into NULL before dividing so the result is NULL instead of an error.", example:"-- safe division: 0 denominator becomes NULL, not an error\nselect revenue / nullif(orders, 0) as revenue_per_order,\n       coalesce(region, 'unknown') as region\nfrom customer_stats;", mistake:"Dividing by a possibly-zero denominator without NULLIF, causing errors or infinities.", followup:"What does revenue / nullif(orders,0) return when orders is 0?", senior:"NULLIF(denominator, 0) is my standard divide-by-zero guard yielding NULL, and COALESCE sets business defaults; combining them keeps ratios safe and explicit without CASE noise." },
  { tier:"sql", cat:"Window functions", q:"Use a window function to flag the first order per customer.", short:"row_number partitioned by customer ordered by order time; rn = 1 is the first order. Or compare order_date to MIN over the partition.", detailed:"First-event flags are common for cohorting. ROW_NUMBER = 1 marks the earliest row per customer; alternatively, order_date = MIN(order_date) OVER (PARTITION BY customer_id) flags it without a subquery filter and handles ties by flagging all tied earliest rows.", example:"select order_id, customer_id, order_date,\n  case when row_number() over (\n    partition by customer_id order by order_date, order_id\n  ) = 1 then true else false end as is_first_order\nfrom fct_orders;", mistake:"Using MIN in a GROUP BY and losing the other order columns, or flagging ties inconsistently.", followup:"How does your choice change if two orders share the earliest timestamp?", senior:"row_number with a tiebreaker flags exactly one first order; if the business wants all simultaneous first orders flagged I switch to the MIN-over-partition comparison, and I state which tie rule applies." },
  { tier:"architecture", cat:"Layering", q:"Why should marts never reference sources or other marts directly?", short:"Sources belong only to staging (one interface layer), and mart-to-mart refs create coupling and cycles; shared logic belongs in intermediate models.", detailed:"Referencing sources only from staging gives a single, testable interface to raw data, so a source change is handled in one place. Marts depending on marts creates tight coupling, risks cycles, and makes grain reasoning harder; extract shared logic to intermediate models that both marts reference.", example:"-- lineage intent:\n-- source -> stg_* -> int_* -> fct_*/dim_*\n-- fct_orders refs int_orders_enriched, not raw or another mart\nselect * from {{ ref('int_orders_enriched') }}", mistake:"Chaining marts off each other and reading raw sources from a mart, scattering source logic.", followup:"How do you share a metric used by two marts without a mart-to-mart ref?", senior:"I keep sources behind staging and factor shared logic into intermediate models so marts stay leaf-ish and independently testable; mart-to-mart edges are a smell I refactor into a shared intermediate." },
  { tier:"sql", cat:"Dedup", q:"How do you dedup an append-only CDC stream to the current state of each record?", short:"Partition by primary key, order by the CDC sequence/commit time desc, keep rn=1, and drop rows whose latest op is a delete.", detailed:"Change-data-capture emits inserts/updates/deletes as append-only rows. Current state is the latest row per primary key by commit LSN/timestamp. Keep rn=1 but filter out records whose latest operation is a delete so removed rows do not reappear.", example:"with latest as (\n  select *, row_number() over (\n    partition by pk order by commit_ts desc, lsn desc) as rn\n  from cdc_raw\n)\nselect * from latest\nwhere rn = 1 and op <> 'D';  -- drop records last seen as delete", mistake:"Keeping rn=1 but forgetting to exclude deletes, resurrecting deleted records.", followup:"Why order by LSN as a tiebreaker rather than timestamp alone?", senior:"CDC current-state is latest-op-wins per key by commit order (LSN beats wall-clock on ties), and I materialize only non-delete latest rows so tombstones are respected; this is the backbone of an incremental snapshot." },
  { tier:"sql", cat:"Aggregation", q:"Why can filtering in WHERE vs HAVING change aggregate results?", short:"WHERE filters rows before aggregation; HAVING filters groups after. Moving a condition between them changes which rows feed the aggregate.", detailed:"WHERE restricts input rows, so aggregates only see the surviving rows. HAVING restricts the grouped output using aggregate conditions. Putting a row-level predicate in HAVING (or an aggregate condition in WHERE) is either wrong or an error.", example:"-- customers whose PAID orders total > 1000\nselect customer_id, sum(amount) as paid_total\nfrom orders\nwhere status = 'paid'          -- row filter before aggregation\ngroup by customer_id\nhaving sum(amount) > 1000;      -- group filter after aggregation", mistake:"Putting status = 'paid' in HAVING (it is a row predicate) or sum(amount) > 1000 in WHERE (aggregates not allowed there).", followup:"Which clause runs first logically, WHERE or GROUP BY?", senior:"Logical order is FROM/WHERE then GROUP BY then HAVING; I put row predicates in WHERE to shrink the input and reserve HAVING for aggregate conditions, which also helps the planner prune early." },
  { tier:"sql", cat:"Keys", q:"Why hash a surrogate key instead of using an auto-incrementing integer in dbt?", short:"Hashes are deterministic and warehouse-agnostic - recomputable on every run and stable across full-refreshes - whereas sequences depend on insertion order and do not survive rebuilds.", detailed:"dbt rebuilds tables, so an auto-increment would reassign different integers each run, breaking joins and history. A hash of the grain columns is deterministic: the same inputs always produce the same key, so it is stable across environments and reproducible, which is essential for idempotent models and SCD snapshots.", example:"select\n  {{ dbt_utils.generate_surrogate_key(['order_id','line_number']) }} as sk,\n  *\nfrom {{ ref('stg_order_lines') }}\n-- same inputs -> same sk on every run, across dev/prod", mistake:"Using row_number() or a sequence as a surrogate key, producing keys that change between runs.", followup:"What risk does a hash key carry that an integer does not?", senior:"Deterministic hash keys are idempotent and environment-independent, which auto-increments are not; I accept the tiny collision risk (and wider key) because reproducibility across rebuilds and SCD versions matters more." },
  { tier:"sql", cat:"Date logic", q:"How do you compute the number of full months between two dates correctly?", short:"Use DATEDIFF at month granularity carefully, or compute from year/month components and adjust for the day-of-month, rather than dividing days by 30.", detailed:"Dividing day differences by 30 is wrong because months vary in length. DATEDIFF('month', a, b) counts month-boundary crossings, which may overcount if b's day is earlier than a's. For completed months, subtract one when the end day is before the start day.", example:"-- Snowflake: completed whole months\nselect datediff('month', start_date, end_date)\n  - case when day(end_date) < day(start_date) then 1 else 0 end\n  as full_months\nfrom subscriptions;", mistake:"Approximating months as days/30 or trusting DATEDIFF(month) to mean completed months.", followup:"Why does DATEDIFF month overcount for Jan 31 to Feb 1?", senior:"DATEDIFF at month grain counts boundary crossings, not elapsed whole months; I adjust by comparing day-of-month, and across adapters I verify DATEDIFF semantics because they differ (boundary count vs truncation)." },
  { tier:"intermediate", cat:"SCD", q:"What is an SCD Type 1 and when is it the right choice over Type 2?", short:"Type 1 overwrites the attribute in place, keeping no history. Choose it when historical values have no analytical value (e.g. correcting a typo).", detailed:"SCD Type 1 simply updates the current value; you lose the prior state. It is correct for error corrections or attributes nobody reports on historically. Type 2 is for attributes where point-in-time accuracy matters (plan at time of purchase). Many dimensions mix both per column.", example:"-- Type 1: current-state dimension, overwrite on reload\nselect customer_id,\n  customer_name,   -- corrected in place, no history kept\n  current_country\nfrom {{ ref('stg_customers') }};  -- rebuilt each run = overwrite", mistake:"Using Type 1 for an attribute that drives historical reporting, destroying point-in-time truth.", followup:"How do you mix Type 1 and Type 2 columns in one dimension?", senior:"I pick SCD type per attribute by whether history has analytical value: corrections are Type 1, report-driving attributes are Type 2, and a hybrid dimension can carry both current and versioned columns." },
  { tier:"sql", cat:"Window functions", q:"Sessionize events: assign a session id when gaps exceed 30 minutes.", short:"Use LAG to get the previous event time, flag a new session when the gap exceeds 30 minutes, then cumulative-SUM the flags per user.", detailed:"Gap-and-island sessionization: within each user ordered by time, a new session starts when the gap from the prior event exceeds the threshold. A running SUM of the new-session flags produces monotonically increasing session numbers.", example:"with flagged as (\n  select *, case when extract(epoch from event_ts\n      - lag(event_ts) over (partition by user_id order by event_ts))\n      > 1800 or lag(event_ts) over (partition by user_id order by event_ts) is null\n    then 1 else 0 end as new_session\n  from events\n)\nselect *, sum(new_session) over (\n  partition by user_id order by event_ts\n  rows between unbounded preceding and current row) as session_seq\nfrom flagged;", mistake:"Forgetting the first-event NULL gap, so the first event gets no session, or not partitioning by user.", followup:"How would you turn session_seq into a globally unique session id?", senior:"Sessionization is a gap-and-island with LAG for the gap flag and a running SUM for the island id; I handle the first-event NULL explicitly and build a global id by hashing user_id with session_seq." },
  { tier:"scenario", cat:"Correctness", q:"A COUNT(*) grouped report shows more rows than exist - what likely happened?", short:"A join to a one-to-many table multiplied the rows before the COUNT, so you are counting joined rows, not entities. Count distinct the entity or aggregate before joining.", detailed:"COUNT(*) counts rows after joins, so a fan-out inflates it. If you meant to count customers but joined to orders, each customer is counted once per order. Use COUNT(DISTINCT entity_key) or collapse the many-side before counting.", example:"-- WRONG: counts customer-order rows\nselect region, count(*) as customers\nfrom customers c join orders o on o.customer_id = c.customer_id\ngroup by region;\n\n-- RIGHT:\nselect region, count(distinct c.customer_id) as customers\nfrom customers c join orders o on o.customer_id = c.customer_id\ngroup by region;", mistake:"Reading COUNT(*) as entity count after a one-to-many join.", followup:"When is COUNT(DISTINCT) itself still wrong after a join?", senior:"After any 1:N join, COUNT(*) counts the fact grain, not the entity; I use COUNT(DISTINCT key) or pre-aggregate - and note distinct count also misleads if the entity key itself is duplicated upstream." },
  { tier:"sql", cat:"Joins", q:"What is the difference between an inner join and a LEFT JOIN when validating data completeness?", short:"Inner join hides unmatched rows; LEFT JOIN keeps all left rows so you can see what failed to match. Use LEFT JOIN plus IS NULL to find gaps.", detailed:"For data-quality checks you want to see missing matches, which an inner join silently discards. A LEFT JOIN retains every driving-table row and NULLs the right side when there is no match, exposing orphans and referential gaps you would otherwise never notice.", example:"-- find orders whose customer is missing from the dimension\nselect o.order_id, o.customer_id\nfrom fct_orders o\nleft join dim_customers c on c.customer_id = o.customer_id\nwhere c.customer_id is null;", mistake:"Using an inner join in a pipeline and never noticing that unmatched facts vanished.", followup:"How would you turn this gap check into a dbt test?", senior:"I default pipeline joins to LEFT JOIN so unmatched rows surface rather than disappear, and I encode the match expectation as a relationships test so orphans fail CI instead of quietly dropping." },
  { tier:"sql", cat:"Financial precision", q:"How do you allocate a discount across line items so the parts sum exactly to the order total?", short:"Allocate proportionally, then assign the rounding residual to one line (largest-remainder) so the summed allocations equal the total to the cent.", detailed:"Proportional allocation with per-line rounding usually leaves a penny gap. The largest-remainder method rounds each share and distributes the leftover cents to the lines with the largest fractional remainders, guaranteeing the parts reconcile exactly to the whole.", example:"-- proportional share, then force exact reconciliation\nwith a as (\n  select line_id, order_id,\n    round(order_discount * line_amount / sum(line_amount)\n      over (partition by order_id), 2) as disc_alloc\n  from order_lines\n)\nselect * from a;  -- then add the residual (order_discount - sum(disc_alloc)) to one line", mistake:"Rounding each allocation independently and ending up a cent short or over the order total.", followup:"Why does naive per-line rounding fail reconciliation?", senior:"Independent per-line rounding does not sum to the whole; I use largest-remainder allocation so the residual cents are deterministically placed and the parts reconcile exactly, then test sum(alloc) = total per order." },
  { tier:"sql", cat:"Window functions", q:"Fill forward the last known non-null value per entity (gap fill).", short:"Create a group id from a running COUNT of non-null values, then take MAX of the value within each group ordered by time.", detailed:"LOCF (last observation carried forward) is done by counting non-nulls cumulatively to form groups, then selecting the value within each group. Equivalently, many warehouses support IGNORE NULLS with LAST_VALUE/LAG for a cleaner form.", example:"-- BigQuery/Snowflake: IGNORE NULLS\nselect entity_id, ts,\n  last_value(status ignore nulls) over (\n    partition by entity_id order by ts\n    rows between unbounded preceding and current row) as status_ffill\nfrom status_events;", mistake:"Using plain LAST_VALUE without IGNORE NULLS (or the counting trick), which returns NULLs where you wanted the carried value.", followup:"How do you do LOCF on an adapter without IGNORE NULLS?", senior:"Where IGNORE NULLS exists I use it; otherwise I build a group id via a cumulative count of non-nulls and take MAX within the group - both give deterministic forward-fill, and I bound the frame explicitly." },
  { tier:"intermediate", cat:"Grain", q:"How do you change a model from one-row-per-order to one-row-per-order-line safely?", short:"Redeclare the grain, update the uniqueness test, re-derive any order-level measures as line-level or via windows, and check that downstream SUMs are not double counted.", detailed:"Changing grain is a breaking change. The order-level total now repeats on every line if copied naively. You must either move the measure to line level (line_amount) or divide/allocate it, update the grain test, and audit downstream models that summed the old grain.", example:"-- new grain: one row per order line\nselect order_id, line_number,\n  line_amount,                       -- line-level measure (correct to SUM)\n  order_total                        -- repeats per line: do NOT SUM downstream\nfrom stg_order_lines;\n-- test: unique_combination_of_columns [order_id, line_number]", mistake:"Carrying the order-level total onto every line and letting downstream SUM it per line.", followup:"Which columns become unsafe to SUM after the grain change?", senior:"Any measure defined at the coarser grain becomes a repeating attribute at the finer grain and must not be summed; I move measures to the new grain or mark them as degenerate order-level attributes, and update the grain test accordingly." },
  { tier:"sql", cat:"Joins", q:"Explain why a FULL OUTER JOIN is useful for reconciling two datasets.", short:"It keeps rows present on either side, so you see keys missing from the left, missing from the right, and mismatched values in one pass.", detailed:"Reconciliation needs to catch records in A not in B and vice versa, plus value differences. A FULL OUTER JOIN on the key with COALESCE and difference flags surfaces all three cases, unlike inner (hides both-sided gaps) or left (hides right-only rows).", example:"select coalesce(a.id, b.id) as id,\n  case when a.id is null then 'missing_in_a'\n       when b.id is null then 'missing_in_b'\n       when a.amount <> b.amount then 'value_diff'\n       else 'match' end as recon_status\nfrom source_a a\nfull outer join source_b b on a.id = b.id;", mistake:"Using an inner join for reconciliation and missing the records absent from one side.", followup:"How would you summarize the reconciliation into counts per status?", senior:"FULL OUTER JOIN with a status CASE gives a complete reconciliation surface (left-only, right-only, value-diff, match); I aggregate it to per-status counts and fail a test on any non-match beyond tolerance." },
  { tier:"sql", cat:"Null handling", q:"Why do NULLs affect GROUP BY and DISTINCT differently than you might expect?", short:"GROUP BY and DISTINCT treat all NULLs as a single group/value (they are \"the same\" for grouping), even though NULL = NULL is never true in a predicate.", detailed:"In comparisons NULL is unknown so NULL = NULL is NULL (not true). But GROUP BY and DISTINCT use a different notion: they collapse all NULLs into one group. This asymmetry surprises people who expect NULL = NULL semantics to govern grouping.", example:"-- all NULL regions collapse to one group row\nselect region, count(*) from customers group by region;\n-- region = NULL appears as a single group, not excluded", mistake:"Expecting NULL rows to be dropped from a GROUP BY the way they are dropped by an equality filter.", followup:"How do you make NULLs show as a labeled group in output?", senior:"Grouping/DISTINCT treat NULL as one bucket while predicates treat it as unknown; I COALESCE to an explicit sentinel when I want a labeled \"unknown\" group, and I never rely on equality to filter NULLs." },
  { tier:"sql", cat:"Window functions", q:"Compute each row's share of its group total using a window aggregate.", short:"Divide the value by SUM over the partition - a window SUM keeps every detail row while giving the group total.", detailed:"A window aggregate (SUM OVER PARTITION BY) returns the group total on every row without collapsing them, so you can compute percent-of-total inline. Guard the denominator with NULLIF for empty/zero groups.", example:"select order_id, category, line_amount,\n  line_amount / nullif(\n    sum(line_amount) over (partition by order_id), 0) as pct_of_order\nfrom order_lines;", mistake:"Joining back a separate GROUP BY total (extra work and fan-out risk) instead of a window aggregate.", followup:"Why is the window form safer than self-joining the group total?", senior:"A partitioned window SUM gives percent-of-total without a self-join or fan-out risk; I wrap the denominator in NULLIF so empty groups yield NULL rather than a divide-by-zero." },
  { tier:"debugging", cat:"Incremental", q:"An incremental model is missing recently updated rows - how do you debug it?", short:"Check the is_incremental predicate: a strictly-greater-than watermark or an append-only id misses updates and late data. Add a lookback window and verify unique_key merges.", detailed:"Common causes: filtering on an id that never changes on update, using > max(updated_at) with no lookback so late-arriving rows below the watermark are skipped, or a missing/incorrect unique_key so upserts do not replace old rows. A --full-refresh should reproduce the correct result; if it differs, the incremental filter is the bug.", example:"{% if is_incremental() %}\nwhere updated_at >= (\n  select max(updated_at) from {{ this }}\n) - interval '3 days'   -- lookback catches late/updated rows\n{% endif %}", mistake:"Using > instead of >= with no lookback, or keying incremental on an immutable created_at.", followup:"How does comparing incremental output to a full-refresh isolate the bug?", senior:"I diff incremental against full-refresh output; divergence localizes the bug to the is_incremental filter or unique_key. Fixes are usually a lookback window plus an update-sensitive watermark and a correct merge key." },
  { tier:"sql", cat:"Pivoting", q:"Unpivot wide monthly columns into a long month/value format.", short:"UNION ALL one SELECT per source column, or use a cross join against a values list; each output row is one (entity, month, value).", detailed:"Unpivoting (wide to long) is the inverse of pivot. Portable approach: UNION ALL a SELECT per column tagging the month label. Some warehouses have UNPIVOT; dbt_utils.unpivot generates the portable form. Long format is what BI tools and time-series windows expect.", example:"select id, 'jan' as month, jan_sales as sales from wide_sales\nunion all\nselect id, 'feb', feb_sales from wide_sales\nunion all\nselect id, 'mar', mar_sales from wide_sales;", mistake:"Leaving data wide and writing twelve near-identical measures downstream instead of unpivoting once.", followup:"Why is long format better for time-series window functions?", senior:"Long format lets a single window function run over the month axis instead of repeating logic per column; I generate the UNION ALL via dbt_utils.unpivot so adding a month does not mean rewriting SQL." },
  { tier:"sql", cat:"Dedup", q:"How do you remove exact duplicate rows that have no unique key?", short:"GROUP BY all columns (or SELECT DISTINCT) collapses exact duplicates; if you must keep one of near-duplicates, use row_number over a hash of the columns.", detailed:"For fully identical rows, DISTINCT or GROUP BY every column removes them. For rows that are duplicates on a business subset but differ on metadata, dedup with row_number partitioned by the business columns and a deterministic order on the metadata.", example:"-- exact duplicates\nselect distinct * from raw_feed;\n\n-- near-duplicates: keep latest-loaded per business key\nselect * from (\n  select *, row_number() over (\n    partition by txn_id order by loaded_at desc) rn\n  from raw_feed) t\nwhere rn = 1;", mistake:"Using DISTINCT when rows differ only by a load timestamp, so true business duplicates survive.", followup:"How do you decide which columns define a business duplicate?", senior:"Exact dupes go to DISTINCT; business dupes need an explicit key definition plus deterministic latest-wins row_number, and I confirm the chosen key with a uniqueness test so the dedup is verifiable." },
  { tier:"intermediate", cat:"Fact vs dimension", q:"What is a degenerate dimension and where does it live?", short:"A degenerate dimension is a dimensional attribute (like an order number or transaction id) stored directly on the fact table with no separate dimension table.", detailed:"Some identifiers (invoice number, PO number) are used for grouping/filtering but have no descriptive attributes worth a dimension table. They live as columns on the fact (degenerate dimensions), avoiding a pointless one-column dimension and an extra join.", example:"-- order_number is a degenerate dimension on the fact\nselect order_id, order_number, customer_sk, product_sk, order_amount\nfrom fct_order_lines;  -- no dim_order_number table needed", mistake:"Building a separate dimension table that only holds the identifier itself.", followup:"When would you promote a degenerate dimension to its own table?", senior:"Degenerate dimensions keep transaction identifiers on the fact without a trivial join; I promote one to a real dimension only once it accrues descriptive attributes worth conforming across facts." },
  { tier:"sql", cat:"Date logic", q:"How do you count business days between two dates excluding weekends?", short:"Join to a calendar/date-spine dimension flagged with is_business_day and COUNT the flagged days, rather than computing with modular arithmetic.", detailed:"Weekend/holiday rules are data, not arithmetic. The clean approach is a date dimension with is_weekend and is_holiday flags; count rows between the two dates where is_business_day. This also handles holidays that pure weekday math cannot.", example:"select count(*) as business_days\nfrom dim_date\nwhere date_day >= :start_date\n  and date_day <  :end_date\n  and is_business_day;", mistake:"Hardcoding weekday modular math that ignores holidays and is hard to audit.", followup:"Why put holiday logic in a date dimension instead of in each query?", senior:"Business-day rules belong in a conformed date dimension with holiday flags; querying it is auditable and consistent across models, whereas inline weekday arithmetic silently ignores holidays and regional calendars." },
  { tier:"senior", cat:"Architecture", q:"How do you design a semantic layer so a metric like revenue is computed once and consistently?", short:"Define the metric and its aggregation/grain centrally (a metrics/semantic layer or a single mart measure), and forbid re-deriving it ad hoc in BI.", detailed:"Metric drift happens when revenue is redefined in each dashboard. Centralize the definition: a single additive measure at a known fact grain, exposed through dbt metrics / a semantic layer or a governed mart, so every consumer aggregates the same column with the same filters and the same additivity rules.", example:"-- one governed measure at a known grain\n-- fct_orders: order_amount (additive), grain = one row per order\n-- revenue := sum(order_amount) over the semantic layer,\n-- never redefined per-dashboard", mistake:"Letting each report write its own revenue SQL, producing several conflicting numbers.", followup:"How do you stop a BI user from redefining the metric downstream?", senior:"I encode revenue once as an additive measure at a declared grain in the semantic layer, with its additivity and filters governed centrally, so every surface resolves the same number; divergent definitions become a review failure, not a dashboard surprise." },
  { tier:"sql", cat:"Correctness", q:"Why can SELECT DISTINCT with an ORDER BY on a non-selected column behave unexpectedly?", short:"After DISTINCT collapses rows, ordering by a column not in the SELECT is ambiguous or disallowed, because that column no longer identifies a single value per output row.", detailed:"DISTINCT operates on the selected columns; a column not in the projection may map to multiple pre-distinct values per output row, so ORDER BY on it is ill-defined. Many engines error; others pick arbitrarily. The fix is to include the ordering column or aggregate it (e.g. MAX).", example:"-- ambiguous: order_date not in the distinct projection\n-- select distinct customer_id from orders order by order_date;  -- error/arbitrary\nselect customer_id, max(order_date) as last_order\nfrom orders group by customer_id\norder by last_order;", mistake:"Assuming DISTINCT + ORDER BY on a hidden column is deterministic.", followup:"How do you get a deterministic \"one row per customer, latest first\" result instead?", senior:"DISTINCT plus ordering by a non-projected column is ambiguous; I express intent explicitly with GROUP BY and an aggregate, or row_number dedup, so the result set and its order are both deterministic." },
  { tier:"sql", cat:"Aggregation", q:"How do GROUPING SETS / ROLLUP help produce subtotals in one pass?", short:"They compute multiple aggregation levels (detail + subtotals + grand total) in a single query, avoiding repeated self-unions.", detailed:"ROLLUP(a, b) yields aggregates for (a,b), (a), and (). GROUPING SETS lets you specify arbitrary combinations. GROUPING() identifies which rows are subtotals. This is far cheaper and cleaner than UNION ALL of separate aggregations.", example:"select region, product, sum(amount) as rev,\n  grouping(region) as is_region_total\nfrom sales\ngroup by rollup (region, product)\norder by region, product;", mistake:"Writing three separate aggregate queries UNIONed together instead of one ROLLUP.", followup:"How do you distinguish a real NULL from a subtotal NULL in the output?", senior:"ROLLUP/GROUPING SETS produce multi-level subtotals in one scan; I use GROUPING() to tag subtotal rows so a true NULL dimension is not confused with an aggregate placeholder, which matters for correct BI labeling." },
  { tier:"sql", cat:"Joins", q:"What is a range/inequality join and where does it show up in analytics?", short:"A join whose condition uses <, >, or BETWEEN rather than equality - common for as-of joins, tiering, and matching events to validity intervals.", detailed:"Range joins match rows by an interval or threshold (event time between valid_from/valid_to, amount into a price tier). They are correct but can be expensive (no hash equality), so you often add an equality key to bound them and watch for unintended multiple matches that fan out.", example:"-- tier each order amount via a range join\nselect o.order_id, t.tier_name\nfrom fct_orders o\njoin price_tiers t\n  on o.order_amount >= t.min_amount\n and o.order_amount <  t.max_amount;  -- half-open, one tier per order", mistake:"Using overlapping/closed tier bounds so an amount matches two tiers and fans out.", followup:"How do you guarantee exactly one match in a range join?", senior:"Range joins power as-of and tiering logic; I make intervals half-open and non-overlapping so each row matches exactly one, add an equality key where possible for performance, and test the output grain for fan-out." },
  { tier:"fouryear", cat:"Keys", q:"What makes a good natural key, and why validate it even when you add a surrogate key?", short:"A good natural key is unique, non-null, and stable over time. You still validate it because the surrogate is derived from it - a broken natural key means duplicate or colliding surrogates.", detailed:"The surrogate key is only as trustworthy as the natural key it hashes. If the natural key has duplicates or NULLs, the surrogate inherits them, and joins/SCD logic break silently. So you test the natural key for unique and not_null at staging even though downstream joins use the surrogate.", example:"# schema.yml at staging\ncolumns:\n  - name: customer_id      # natural key\n    tests:\n      - unique\n      - not_null\n# surrogate hashed from it inherits its integrity", mistake:"Trusting the surrogate key while never testing the natural key it is built from.", followup:"What happens to SCD history if the natural key is not stable?", senior:"The surrogate inherits the natural key's integrity, so I enforce unique/not_null on the natural key at staging; an unstable natural key fragments SCD history and breaks current-state joins, so stability is a modeling requirement, not a nicety." },
  { tier:"sql", cat:"Window functions", q:"Why does a window function in the SELECT list not reduce the number of rows, and how does that differ from GROUP BY?", short:"Window functions compute across a partition but return a value per input row, so row count is preserved; GROUP BY collapses each group to one row.", detailed:"A window (OVER) attaches an aggregate to every row without folding rows together, which is why you can show both the detail and the group total side by side. GROUP BY reduces each group to a single output row and drops non-grouped detail columns. Choosing between them is about whether you need to keep detail.", example:"-- keeps every order row, adds the customer total\nselect order_id, customer_id, order_amount,\n  sum(order_amount) over (partition by customer_id) as customer_total\nfrom fct_orders;\n-- GROUP BY would return one row per customer instead", mistake:"Expecting a window SUM to collapse rows like GROUP BY, then getting duplicated group totals downstream.", followup:"When would you still wrap a windowed result in a GROUP BY or DISTINCT?", senior:"Windows preserve grain while annotating it with group-level context; I reach for them when detail must survive, and only collapse with GROUP BY when the output grain is genuinely the group - mixing the two carelessly is a common source of accidental duplication." },
  { tier:"debugging", cat:"Correctness", q:"A model passes all tests but a stakeholder says the numbers are wrong - how do you investigate?", short:"Tests verify structural invariants, not business meaning. Reproduce the stakeholder number at the source, then trace the discrepancy layer by layer against the model lineage.", detailed:"Green tests (unique, not_null, relationships) confirm the data is well-formed, not that the logic matches intent. I define the expected number independently from raw source, then reconcile down the DAG (staging, intermediate, mart) to find the exact layer where it diverges - often a filter semantics, grain change, or timezone/date-boundary issue.", example:"-- reconcile the mart against an independent source computation\nselect 'source' as layer, sum(amount) from raw.orders where created_at::date = '2024-06-01'\nunion all\nselect 'mart', sum(order_amount) from fct_orders where order_date = '2024-06-01';\n-- a gap localizes the layer to inspect next", mistake:"Assuming passing tests mean the business logic is correct.", followup:"What kind of test would have caught this discrepancy automatically?", senior:"Schema tests prove well-formedness, not correctness; I reconcile the disputed figure from raw source down the lineage to localize the diverging layer, then convert the expected value into a reconciliation singular test so the semantic bug cannot silently return." },
  { tier:"beginner", cat:"Jinja", q:"What is the difference between Jinja expression syntax {{ ... }} and statement syntax {% ... %}?", short:"{{ ... }} evaluates an expression and renders its result into the compiled SQL. {% ... %} is a statement for control flow (if/for/set/macro calls that produce no output) and renders nothing by itself.", detailed:"Double curly braces output a value: {{ ref('orders') }} becomes a relation name in the SQL. Percent-brace tags drive logic: loops, conditionals, variable assignment, and macro definitions. A {% set x = 1 %} binds a variable but emits nothing, whereas {{ x }} prints it. Mixing them up is a common source of either missing output or stray text in compiled SQL.", example:"{% set cols = ['a', 'b'] %}\nselect\n{% for c in cols %}\n  {{ c }}{% if not loop.last %},{% endif %}\n{% endfor %}\nfrom {{ ref('src') }}", mistake:"Writing {% ref('x') %} (emits nothing) instead of {{ ref('x') }}, or putting SQL-producing logic inside {% %} expecting it to render.", followup:"How do you call a macro that returns a value versus one that prints directly?", senior:"A macro invoked inside {{ }} renders its {% %}-generated text; the same macro inside {% %} runs for side effects (or you capture its output with {% set result = my_macro() %}). Understanding that macros return the string they render is key to composing them." },
  { tier:"intermediate", cat:"Jinja", q:"Explain the execute variable and the difference between parse time and run time in dbt.", short:"dbt compiles every model twice-ish: a parse phase builds the DAG where execute is False, and an execute phase where execute is True and queries actually run. Guard code that hits the warehouse (like run_query) with {% if execute %}.", detailed:"During parsing, dbt renders Jinja to discover ref/source calls and build the graph, but it does not run adapter queries; execute is False and functions like run_query return None. During execution, execute is True and database calls return real results. Without the guard, parse-time code that assumes a result set will error or misbehave.", example:"{% set payment_methods = [] %}\n{% if execute %}\n  {% set results = run_query('select distinct payment_method from ' ~ ref('payments')) %}\n  {% set payment_methods = results.columns[0].values() %}\n{% endif %}", mistake:"Calling run_query or dbt_utils.get_column_values without wrapping in {% if execute %}, causing failures or empty results during parse.", followup:"Why does ref still work during parse even though execute is False?", senior:"ref/source are resolved structurally to build the DAG, independent of execute; they do not query the warehouse. Only functions that actually read data (run_query, statement results, adapter.get_relation in some cases) depend on the execute phase." },
  { tier:"intermediate", cat:"Jinja", q:"What does the this variable refer to, and when is it useful?", short:"this is the Relation object for the current model (its database, schema, identifier). It is most useful in incremental models and post-hooks to reference the model is own existing table.", detailed:"this resolves to the model being built, equivalent to a self-ref. In an incremental run you select from this to find the max loaded timestamp. In hooks you can grant or index this. It exposes .database, .schema, .identifier and renders to a fully-qualified name.", example:"{% if is_incremental() %}\n  where event_ts > (select max(event_ts) from {{ this }})\n{% endif %}", mistake:"Using {{ ref('current_model') }} to self-reference (dbt forbids a model ref-ing itself) instead of {{ this }}.", followup:"How does this behave on the very first run of an incremental model?", senior:"On first run the relation may not exist yet, but is_incremental() returns False precisely because the table does not yet exist (and it is not a full refresh), so the branch selecting from this is skipped. this is still a valid object; you just must not query it before it exists." },
  { tier:"intermediate", cat:"Jinja", q:"What information does the target variable expose and why should you be cautious using it in logic?", short:"target reflects the active profile/connection: target.name, target.schema, target.database, target.type (adapter), threads, etc. It is handy for environment-aware logic but coupling business logic to target.name is brittle.", detailed:"target lets you branch on dev versus prod (e.g. limit rows in dev) or on adapter type. Overusing target.name == 'prod' to gate behavior spreads environment assumptions through your code and breaks when someone renames a target. Prefer vars, env_vars, or configs for intent, reserving target for genuinely connection-level concerns.", example:"{% if target.name == 'dev' %}\n  where created_at >= dateadd('day', -3, current_date)\n{% endif %}", mistake:"Hardcoding target.name checks everywhere so a renamed target silently changes behavior in production.", followup:"How would you make a dev row-limit configurable instead of hardcoded?", senior:"Expose it via a var with a default (e.g. {{ var('dev_lookback_days', 3) }}) or a dedicated macro, so the limit is explicit, documented, and overridable per invocation without editing model SQL." },
  { tier:"fouryear", cat:"Jinja", q:"Describe Jinja whitespace control and why it matters for compiled SQL.", short:"A minus sign inside a tag ({%- ... -%}) strips adjacent whitespace/newlines. It matters because loops and conditionals otherwise leave blank lines and stray commas that make compiled SQL ugly or, with trailing commas, invalid.", detailed:"Jinja preserves the text around tags, so a {% for %} block emits the surrounding newlines on every iteration. Using {%- and -%} trims whitespace before/after the tag. The real correctness risk is comma placement in generated column lists; whitespace control plus loop.last logic keeps the SQL valid and readable.", example:"select\n{%- for c in cols %}\n  {{ c }}{{ ',' if not loop.last }}\n{%- endfor %}\nfrom {{ ref('t') }}", mistake:"Relying on whitespace stripping alone to fix a trailing comma; stripping whitespace does not remove the comma character itself.", followup:"What tools help you verify the generated SQL is correct?", senior:"Inspect target/compiled/... for the rendered SQL, or use dbt compile / dbt show. Reviewing compiled output is the definitive way to confirm whitespace and comma logic rather than guessing from the template." },
  { tier:"intermediate", cat:"Jinja", q:"What does the loop variable provide inside a Jinja for loop?", short:"Inside {% for %}, Jinja exposes loop with helpers like loop.index (1-based), loop.index0 (0-based), loop.first, loop.last, loop.length, and loop.cycle. loop.last is the standard way to control comma placement.", detailed:"These attributes let you build column lists, pivot cases, or union blocks cleanly. loop.first/loop.last gate leading/trailing separators; loop.index gives ordinal positions. They remove the need for manual counters and make generated SQL more robust.", example:"{% for method in payment_methods %}\nsum(case when method = '{{ method }}' then amount end) as {{ method }}_amount\n{{ ',' if not loop.last }}\n{% endfor %}", mistake:"Maintaining a manual counter variable instead of loop.index0, which is error-prone and unnecessary.", followup:"How do you reference the outer loop counter inside a nested loop?", senior:"Use loop.cycle or capture the outer loop into a named variable, or reference loop in the respective scope; Jinja also allows {% set outer = loop %} at the top of the inner loop to disambiguate nested counters." },
  { tier:"intermediate", cat:"Jinja", q:"Give examples of common Jinja filters you use in dbt and what they do.", short:"Filters transform values with a pipe: {{ x | default(0) }}, {{ name | lower }}, {{ cols | join(', ') }}, {{ val | trim }}, {{ x | string }}, {{ list | unique }}. They keep templates concise.", detailed:"default supplies a fallback for undefined/none; join collapses a list into a delimited string for SELECT lists; lower/upper normalize identifiers; trim cleans whitespace; string coerces types for concatenation. dbt also ships Python-like filters via Jinja plus some dbt-specific context functions.", example:"select {{ columns | join(',\\n  ') }}\nfrom {{ ref('t') }}\nwhere status = '{{ status | default('active') }}'", mistake:"Assuming every Python string method is available; only Jinja filters and whatever dbt exposes work, not arbitrary Python.", followup:"What is the difference between the default filter and Python-style or logic?", senior:"default(value, boolean=False) only substitutes when the variable is undefined; passing boolean=True also substitutes for falsy values. Plain or short-circuits on any falsy value, which can mask legitimately empty-but-defined inputs." },
  { tier:"fouryear", cat:"Jinja", q:"How do you safely use run_query inside a model, and what does it return?", short:"Wrap run_query in {% if execute %}, and it returns an agate Table. Pull columns with result.columns[0].values() or iterate rows. Outside execute it returns None, so unguarded access errors.", detailed:"run_query runs arbitrary SQL during execution and hands back an agate Table object, not a raw list. You typically grab a single column of distinct values to drive pivots or dynamic column lists. The parse-time guard is essential because run_query is a no-op (None) during graph building.", example:"{% set rows = [] %}\n{% if execute %}\n  {% set rows = run_query('select distinct region from ' ~ ref('customers')).columns[0].values() %}\n{% endif %}", mistake:"Treating the return as a plain list immediately, or forgetting the execute guard so parse-time rendering crashes.", followup:"How does statement()/load_result differ from run_query?", senior:"run_query is sugar over the statement block plus load_result: it issues the query, loads the result, and returns the agate Table in one call. The lower-level statement/load_result pair gives finer control (naming results, fetch flags) but run_query covers the common case." },
  { tier:"beginner", cat:"Jinja", q:"How do you declare and use a variable in a Jinja template with set?", short:"{% set name = value %} binds a variable in the current scope; reference it with {{ name }} or in logic. A block form {% set x %}...{% endset %} captures rendered text into x.", detailed:"set supports scalars, lists, dicts, and the result of expressions or macro calls. The block/capture form is useful for building multi-line SQL snippets and assigning them to a name. Scope follows Jinja rules: variables set inside a loop do not reliably leak out due to loop scoping.", example:"{% set threshold = var('min_amount', 100) %}\n{% set clause %}\n  amount >= {{ threshold }}\n{% endset %}\nselect * from {{ ref('t') }} where {{ clause }}", mistake:"Expecting a variable assigned inside a for loop to persist after the loop; Jinja loop scoping discards it (use a namespace object).", followup:"How do you accumulate a value across loop iterations?", senior:"Use {% set ns = namespace(total=0) %} and mutate ns.total inside the loop, because plain set inside a loop body does not propagate outward due to Jinja scope boundaries." },
  { tier:"senior", cat:"Jinja", q:"When does Jinja expand relative to when the SQL runs, and why does that distinction cause bugs?", short:"Jinja fully renders to a static SQL string at compile time; the warehouse then executes that fixed string. You cannot make SQL control Jinja flow, nor react to row values in Jinja, because Jinja is already gone by the time rows exist.", detailed:"A frequent misconception is that Jinja is loop or conditional that runs per-row. In reality, {% for %} unrolls into literal repeated SQL at compile time, and {% if %} picks a branch before any query runs. Values only known at query time (counts, maxes) cannot steer Jinja unless you first fetch them via run_query during execution and feed them back.", example:"{# WRONG idea: Jinja cannot read this row count at compile time #}\n{% if execute %}\n  {% set n = run_query('select count(*) from ' ~ ref('t')).columns[0][0] %}\n  {# now n is a Python value you can branch on #}\n{% endif %}", mistake:"Believing an {% if %} can test a column value, or that a {% for %} iterates warehouse rows; both are compile-time constructs.", followup:"How would you make model structure depend on actual data?", senior:"Fetch the data-derived value with run_query under {% if execute %}, assign it to a Jinja variable, then branch/loop on that. This two-phase pattern is the only way compile-time templating can depend on warehouse state." },
  { tier:"beginner", cat:"Macros", q:"How do you define a macro with arguments and default values?", short:"Use {% macro name(arg1, arg2=default) %}...{% endmacro %}. Defaults make arguments optional; callers can pass positionally or by keyword.", detailed:"Macros live in the macros/ directory. Arguments with defaults must follow those without. The macro renders whatever text its body produces, so it can generate SQL fragments. Keyword arguments improve readability for macros with several parameters.", example:"{% macro cents_to_dollars(column, precision=2) %}\n  round({{ column }} / 100.0, {{ precision }})\n{% endmacro %}\n\nselect {{ cents_to_dollars('amount_cents') }} as amount from {{ ref('t') }}", mistake:"Placing a defaulted argument before a non-defaulted one, which is a syntax error.", followup:"How do you call this macro with only the precision overridden?", senior:"Use a keyword argument: {{ cents_to_dollars('amount_cents', precision=4) }}. Keyword passing avoids positional ambiguity and documents intent, especially for optional behavioral flags." },
  { tier:"intermediate", cat:"Macros", q:"How does a macro return a value versus render SQL text directly?", short:"Macros always render the text their body emits. To return a usable value rather than inline text, use {% do return(value) %}; callers capture it with {% set x = my_macro() %}.", detailed:"A macro used in {{ }} injects its rendered output into SQL. When you need a Python object (a list, a relation, a computed string) back, call return() and assign the result. Many dbt_utils macros (get_column_values, get_relations_by_pattern) use return() so they can feed loops and configs.", example:"{% macro get_cols(relation) %}\n  {% set cols = adapter.get_columns_in_relation(relation) %}\n  {% do return(cols | map(attribute='name') | list) %}\n{% endmacro %}\n\n{% set names = get_cols(ref('orders')) %}", mistake:"Expecting {{ my_macro() }} to give you a Python list; in expression position it renders the list is string form, not a usable object.", followup:"Why use {% do ... %} instead of {{ ... }} for return?", senior:"return() produces no renderable text, so it belongs in a statement context. {% do %} executes an expression for its side effect without printing, which is exactly what calling return (or appending to a list) needs." },
  { tier:"intermediate", cat:"Macros", q:"Can you use ref and source inside a macro, and what should you watch out for?", short:"Yes, ref and source work in macros and are resolved to build the DAG. The caveat is that ref inside a macro still creates a dependency for whichever model invokes the macro, so hidden refs can create surprising DAG edges.", detailed:"Because macros render into a model, ref calls within them attach that dependency to the calling model. This is powerful (shared logic that pulls in upstream models) but can obscure lineage if a widely-used utility macro quietly refs a model. Prefer passing the relation in as an argument when you want explicit, visible dependencies.", example:"{% macro latest_snapshot() %}\n  select * from {{ ref('customers_snapshot') }}\n  where dbt_valid_to is null\n{% endmacro %}", mistake:"Burying ref calls deep in utility macros so lineage no longer reflects actual dependencies when reading model files.", followup:"How can you make dependencies explicit while still sharing logic?", senior:"Pass the relation as a macro argument from the model (my_macro(ref('x'))) so the ref lives in the model file and lineage stays legible, while the macro just operates on whatever relation it receives." },
  { tier:"senior", cat:"Adapter dispatch", q:"Explain adapter.dispatch and how it enables cross-database macros.", short:"adapter.dispatch(name) looks up an adapter-specific implementation by prefixing the macro name with the adapter (e.g. snowflake__macro, default__macro). It lets one macro call route to the right SQL dialect per warehouse.", detailed:"You define a public macro that calls return(adapter.dispatch('thing')(args)), then implement default__thing plus overrides like bigquery__thing. dbt resolves which to run based on the active adapter, with a search order you can extend via the dispatch config for packages. This is how dbt_utils stays portable across Snowflake, BigQuery, Postgres, etc.", example:"{% macro generate_surrogate_key(cols) %}\n  {{ return(adapter.dispatch('generate_surrogate_key', 'my_pkg')(cols)) %}\n{% endmacro %}\n\n{% macro default__generate_surrogate_key(cols) %}\n  md5(cast(coalesce({{ cols | join(\" , \") }}) as varchar))\n{% endmacro %}", mistake:"Writing dialect-specific SQL directly in a shared macro instead of dispatching, so it breaks on other adapters.", followup:"How do you let a project override a package is dispatched macro?", senior:"Configure the dispatch search order in dbt_project.yml so your project namespace is searched before the package, then define your own adapter-prefixed implementation. dbt picks the first match in the configured order, enabling clean overrides without forking the package." },
  { tier:"fouryear", cat:"Macros", q:"How do you test a macro in dbt?", short:"dbt 1.8+ supports unit tests for models that exercise macro logic, and you can also write a test model or generic test that asserts the macro output. Packages often ship an integration_tests project that materializes macro results and checks them.", detailed:"There is no standalone macro test runner, so you test macros indirectly: call the macro in a small model and assert the rendered result (via a singular test or unit test comparing expected rows). dbt unit tests (1.8+) let you provide mock inputs and expected output for the model that uses the macro, isolating the transformation.", example:"unit_tests:\n  - name: test_cents_to_dollars\n    model: amounts\n    given:\n      - input: ref('raw')\n        rows: [{amount_cents: 150}]\n    expect:\n      rows: [{amount: 1.50}]", mistake:"Assuming dbt has a direct test my_macro() command; macros are tested through the models or tests that invoke them.", followup:"What did people do before unit tests existed for this?", senior:"They relied on integration test projects (seed known inputs, materialize, then use data tests to compare against expected seeds) and on compiling the macro to eyeball the SQL. Unit tests in 1.8 formalized input/expected assertions without round-tripping through the warehouse for seeds." },
  { tier:"intermediate", cat:"Macros", q:"What is the risk of over-abstracting with macros?", short:"Excessive macro layers make SQL hard to read, debug, and review: lineage hides inside macros, compiled output diverges from source, and small changes ripple widely. Macros should earn their keep by removing real, repeated complexity.", detailed:"Macros are great for genuine repetition (surrogate keys, date spines, boilerplate). But wrapping trivial SQL or building deeply nested macro call trees obscures intent and forces readers to jump files. Compiled SQL becomes the real source of truth, slowing incident response. Favor clarity; abstract only after a pattern repeats meaningfully.", example:"{# Over-abstracted: a macro for a single trivial cast #}\n{% macro to_date(c) %}cast({{ c }} as date){% endmacro %}\n{# Just write cast(... as date) inline #}", mistake:"Creating a macro for every one-liner, trading a tiny keystroke saving for large readability and debuggability costs.", followup:"What criteria would you use to decide a macro is warranted?", senior:"Rule of three (repeated in 3+ places), nontrivial logic, cross-adapter needs, or a single source of truth for a business rule. If removing the macro would not create meaningful duplication or risk, it probably should not exist." },
  { tier:"beginner", cat:"Macros", q:"How do packages like dbt_utils provide macros, and how do you install and use them?", short:"Packages are declared in packages.yml, installed with dbt deps, and their macros are namespaced: {{ dbt_utils.star(...) }}. They ship reusable, cross-adapter macros you call like your own.", detailed:"A package is just another dbt project added as a dependency. After dbt deps fetches it into dbt_packages/, its macros, tests, and sometimes models become available. You reference its macros with the package namespace to avoid collisions. Pin versions for reproducibility.", example:"packages:\n  - package: dbt-labs/dbt_utils\n    version: 1.3.0\n\n{# usage #}\nselect {{ dbt_utils.generate_surrogate_key(['a', 'b']) }} as id from {{ ref('t') }}", mistake:"Forgetting to run dbt deps after editing packages.yml, so the macros are unresolved and compilation fails.", followup:"What happens if two packages define a macro with the same name?", senior:"Namespacing (package.macro) disambiguates calls, and the dispatch search order controls which adapter-specific implementation wins. Collisions only matter for unqualified dispatch resolution, which the configured search path resolves deterministically." },
  { tier:"intermediate", cat:"Macros", q:"How would you write a macro that generates a SELECT of all columns except a few?", short:"Introspect the relation with adapter.get_columns_in_relation, filter out the excluded names, and join the rest into a column list. dbt_utils.star does exactly this; rolling your own follows the same shape.", detailed:"Column introspection requires execution (the relation must exist), so guard with execute and handle the parse phase. You build a list of column names, remove the exclusions case-insensitively, and emit them comma-separated. This supports evolving schemas without hardcoding every column.", example:"{% macro select_except(relation, exclude=[]) %}\n  {%- set cols = adapter.get_columns_in_relation(relation) | map(attribute='name') | list -%}\n  {%- set keep = cols | reject('in', exclude) | list -%}\n  {{ keep | join(',\\n  ') }}\n{% endmacro %}", mistake:"Comparing column names with mismatched case so exclusions silently fail on case-insensitive warehouses.", followup:"Why can this macro break if the upstream model has not been built?", senior:"adapter.get_columns_in_relation queries catalog metadata, so the relation must already exist. On a clean build or in parse context it returns nothing, so you need execute guards and a correct DAG order ensuring upstream models build first." },
  { tier:"beginner", cat:"Materializations", q:"What are the four built-in materializations and what does each create?", short:"view (a database view), table (a physical table rebuilt each run), incremental (a table updated with only new/changed rows), and ephemeral (no object; inlined as a CTE into downstream models).", detailed:"view stores only a query definition, cheap to build but computes on read. table persists results, fast to read but rebuilt fully each run. incremental persists but loads deltas for scale. ephemeral produces no database object and is interpolated as a CTE wherever it is ref-ed, good for lightweight intermediate logic.", example:"{{ config(materialized='incremental', unique_key='id') }}\nselect * from {{ ref('events') }}\n{% if is_incremental() %}\n  where loaded_at > (select max(loaded_at) from {{ this }})\n{% endif %}", mistake:"Making heavy, frequently-queried models views (slow reads) or tiny lookups tables (needless rebuild cost).", followup:"When would ephemeral be the wrong choice?", senior:"Ephemeral models cannot be queried directly, add nothing to the catalog, and their CTE is duplicated into every consumer, so complex or multiply-referenced logic bloats compiled SQL and can hurt the optimizer. For reused or heavy logic, a view or table is clearer and often faster." },
  { tier:"intermediate", cat:"Materializations", q:"What are the tradeoffs between view and table materializations?", short:"Views are cheap to build and always fresh but push compute to read time. Tables cost storage and full rebuild time but give fast, stable reads. Choose based on read frequency, query cost, and freshness needs.", detailed:"A view re-runs its query on every read, so expensive transformations hit users each time they query. A table pays the compute once per dbt run and stores results, amortizing cost across many reads. For hot, complex models with frequent BI access, tables usually win; for thin passthrough or rarely-read models, views save storage and stay fresh.", example:"{{ config(materialized='table') }}\n{# vs #}\n{{ config(materialized='view') }}", mistake:"Defaulting everything to view to save storage, then wondering why dashboards are slow and warehouse costs spike on reads.", followup:"Where does incremental fit on this spectrum?", senior:"Incremental is a table that avoids full recompute by loading only deltas, trading added complexity (state, strategies, late data handling) for drastically lower build cost on large append-mostly datasets. It is the answer when a full table rebuild is too expensive but you still want fast reads." },
  { tier:"fouryear", cat:"Materializations", q:"What happens during a table materialization run, and how does dbt achieve atomic replacement?", short:"dbt typically builds into a temporary/new relation and then swaps it in (create-or-replace or rename), so consumers see either the old or new table, not a half-built one. The exact mechanism (create or replace, swap, rename) varies by adapter.", detailed:"The materialization logic runs a create statement for the model, often into an intermediate relation, then replaces the target atomically where the warehouse supports it. On Snowflake a create or replace table is effectively atomic; other adapters rename a backup and swap. This minimizes the window where downstream queries could hit an incomplete table.", example:"{{ config(materialized='table') }}\n{# dbt wraps your select in create or replace / swap logic #}", mistake:"Assuming every warehouse gives truly atomic swaps; the guarantee and method are adapter-specific.", followup:"How does this differ for incremental models?", senior:"Incremental does not drop-and-replace on normal runs; it merges/inserts into the existing relation in place, which is not atomic in the same way. A full_refresh rebuilds like a table. Understanding this matters when a run fails mid-merge, since the table may be partially updated depending on strategy and transactionality." },
  { tier:"senior", cat:"Materializations", q:"How do you create a custom materialization, and when is it justified?", short:"Define a {% materialization name, adapter='x' %} (or default) block that returns relations and runs the SQL lifecycle via dbt statements. Justify it only when built-ins plus configs/hooks genuinely cannot express the pattern.", detailed:"A custom materialization controls the full build lifecycle: creating relations, running pre/post hooks, executing load SQL, and returning the set of relations for cleanup. Real uses include special insert patterns, external tables, or vendor-specific features. Because it bypasses battle-tested built-ins, it adds maintenance burden and risk, so it is a last resort.", example:"{% materialization insert_by_period, default %}\n  {# acquire relations, loop periods, run statements, return relations #}\n{% endmaterialization %}", mistake:"Writing a custom materialization for something a post-hook, incremental strategy, or config already handles.", followup:"What must a materialization return and why?", senior:"It must return {'relations': [...]} listing relations it created or modified so dbt can track them for caching and cleanup. Omitting this breaks dbt is relation cache and can leave orphaned temp objects, which is why custom materializations demand careful lifecycle handling." },
  { tier:"intermediate", cat:"Materializations", q:"What does a full refresh do, and how do you trigger and guard it?", short:"dbt run --full-refresh rebuilds incremental models from scratch (dropping and recreating), ignoring is_incremental(). You can protect expensive models with config full_refresh=false so they never full-refresh accidentally.", detailed:"Full refresh is how you recover from schema changes, backfills, or corrupted incremental state. The --full-refresh flag makes is_incremental() return False so the whole SELECT runs and replaces the table. For huge tables you may set full_refresh: false in config to block the flag, forcing a deliberate alternate process.", example:"{{ config(materialized='incremental', full_refresh=false) }}", mistake:"Running --full-refresh on a massive append-only table during peak hours, causing a costly full rebuild and locking.", followup:"If full_refresh=false, how do you ever rebuild that model?", senior:"You rebuild out of band: temporarily remove/override the config, run a controlled backfill, or drop the relation manually so the next run recreates it. The guard forces the rebuild to be an intentional, planned operation rather than an accidental flag." },
  { tier:"beginner", cat:"Incremental", q:"What does is_incremental() return, and under what conditions is it True?", short:"is_incremental() is True only when the model is materialized incremental, the target relation already exists, and the run is not a full refresh. Otherwise it is False and the full SELECT runs.", detailed:"It gates the delta-filter branch. All three conditions must hold: the config is incremental, the table exists from a prior run, and --full-refresh was not passed. On the first run (no table) or on a full refresh it returns False, so the model builds its complete result set.", example:"{% if is_incremental() %}\n  where updated_at > (select max(updated_at) from {{ this }})\n{% endif %}", mistake:"Assuming it is True on the first run; with no existing table it is False, so first run loads everything.", followup:"Why must the table exist for it to be True?", senior:"The incremental branch usually selects max(timestamp) from this, which requires the relation to exist. dbt makes is_incremental() False when the table is absent precisely so that bootstrapping logic (querying this) never runs against a nonexistent relation." },
  { tier:"intermediate", cat:"Incremental", q:"What is unique_key and how does it change incremental behavior?", short:"unique_key identifies a row is primary key (single column or list). With it, dbt can update existing rows rather than only appending, enabling merge or delete+insert so reprocessed keys do not duplicate.", detailed:"Without unique_key, incremental typically just appends new rows, risking duplicates if source rows are reprocessed. With unique_key, dbt matches incoming rows to existing ones and upserts, so late-arriving updates to an existing key replace rather than duplicate. The exact mechanism depends on the chosen strategy and adapter.", example:"{{ config(materialized='incremental', unique_key='order_id') }}\n{# or a compound key #}\n{{ config(materialized='incremental', unique_key=['order_id', 'line_no']) }}", mistake:"Omitting unique_key on a model that reprocesses updated rows, producing duplicate keys over time.", followup:"What if two incoming rows share the unique_key in the same batch?", senior:"Many merge implementations error or nondeterministically pick one when the source has duplicate keys in a single load. You must dedupe within the incremental SELECT (e.g. qualify row_number() over the key by latest timestamp) before the merge to guarantee one row per key." },
  { tier:"senior", cat:"Incremental", q:"Compare the append, merge, delete+insert, and insert_overwrite incremental strategies. Which adapters support them?", short:"append only inserts new rows (no updates). merge upserts by unique_key. delete+insert removes matching keys then inserts. insert_overwrite replaces whole partitions. Support varies: merge/delete+insert on Snowflake/Redshift/Postgres-ish; insert_overwrite is partition-oriented on BigQuery/Spark; never assume one is universal.", detailed:"append is simplest and fastest but cannot correct existing rows. merge updates and inserts in one statement where supported (Snowflake, BigQuery, Spark/Databricks). delete+insert deletes rows matching the incoming keys/predicate then inserts, used where merge is unavailable or less efficient (e.g. Redshift). insert_overwrite swaps entire partitions, ideal for partitioned backfills on BigQuery and Spark but meaningless on warehouses without partitions. Always check the specific adapter is supported strategies.", example:"{{ config(\n  materialized='incremental',\n  incremental_strategy='merge',\n  unique_key='id'\n) }}", mistake:"Claiming insert_overwrite or merge works everywhere; strategy availability and semantics are adapter-specific.", followup:"When is insert_overwrite preferable to merge?", senior:"On partitioned engines (BigQuery, Spark) when you reprocess whole partitions (e.g. a day of data): overwriting partitions is cheaper and cleaner than row-level merge, and it naturally removes rows deleted upstream within those partitions. It requires a partition_by config and a predicate that targets the affected partitions." },
  { tier:"senior", cat:"Incremental", q:"How do you handle late-arriving or out-of-order source rows in an incremental model?", short:"Use a lookback window: filter on max(ts) minus a buffer rather than strict greater-than, and pair with a unique_key merge so reprocessed rows upsert instead of duplicate. The window must cover expected lateness.", detailed:"A naive updated_at > max(updated_at) misses rows that arrive after the watermark advanced. Subtracting a lookback (e.g. 3 days) reprocesses a trailing window each run, and merge/delete+insert on the unique_key dedupes the overlap. Sizing the window is a tradeoff between coverage of lateness and reprocessing cost.", example:"{% if is_incremental() %}\n  where updated_at >= (\n    select dateadd('day', -3, max(updated_at)) from {{ this }}\n  )\n{% endif %}", mistake:"Using strict > max without a lookback plus unique_key, so late rows are permanently lost or duplicated.", followup:"How does microbatch simplify this pattern?", senior:"microbatch (dbt 1.9+, newer feature) formalizes time-windowed processing: you declare event_time, batch_size, and a lookback, and dbt builds each period as an isolated, idempotent batch. It handles the window arithmetic and reprocessing boundaries for you, replacing hand-rolled lookback SQL." },
  { tier:"fouryear", cat:"Incremental", q:"What is the microbatch incremental strategy and how does it differ from traditional incremental?", short:"microbatch is a newer strategy (dbt 1.9+) that splits a model into time-based batches keyed on an event_time column with a batch_size and lookback. dbt processes each period independently and idempotently, rather than one big delta merge.", detailed:"Traditional incremental runs a single SELECT filtered by a watermark. microbatch instead partitions work into discrete time windows (e.g. per day), each built in isolation so retries only reprocess the affected windows. This improves backfills, parallelism, and idempotency, and sidesteps hand-written lookback logic. Mark it as relatively new and adapter-dependent.", example:"{{ config(\n  materialized='incremental',\n  incremental_strategy='microbatch',\n  event_time='event_ts',\n  batch_size='day',\n  lookback=2\n) }}", mistake:"Treating microbatch as universally available or identical to a merge; it is newer, requires event_time, and support depends on the adapter and dbt version.", followup:"How do you backfill a specific date range with microbatch?", senior:"You can target windows with the --event-time-start and --event-time-end flags, so dbt rebuilds only those batches. Because each batch is idempotent and isolated, backfilling a range does not disturb other periods, which is a major advantage over monolithic incremental rebuilds." },
  { tier:"senior", cat:"Incremental", q:"How do you handle hard deletes in a source for an incremental model?", short:"Standard incremental only sees inserts/updates in the delta, so deleted source rows persist in the target. Options: insert_overwrite of affected partitions, a periodic full refresh, a delete+insert keyed on soft-delete flags, or capturing deletes from a CDC feed.", detailed:"Because the incremental SELECT filters by a timestamp, rows that vanished upstream are never selected, so they linger. If the source emits tombstones or a is_deleted flag, you can propagate them via merge or delete+insert. If it offers nothing, partition overwrite or scheduled full refresh reconciles. Pure append/merge on live rows cannot detect deletions.", example:"{{ config(materialized='incremental', incremental_strategy='delete+insert', unique_key='id') }}\nselect * from {{ ref('cdc_feed') }}\n{% if is_incremental() %}\n  where _loaded_at >= (select max(_loaded_at) from {{ this }})\n{% endif %}", mistake:"Assuming a merge on updated rows removes rows deleted upstream; without a delete signal it cannot.", followup:"How does this compare to snapshots with invalidate_hard_deletes?", senior:"Snapshots can detect hard deletes with invalidate_hard_deletes=true by observing keys that disappear from the source and closing their validity window, because the snapshot compares the full current source to prior state. An incremental model only sees the delta, so it structurally cannot infer deletions without an explicit signal." },
  { tier:"scenario", cat:"Incremental", q:"Your incremental run failed halfway through a merge. How do you reason about recovery and idempotency?", short:"Assess whether the failed statement was transactional/atomic on your adapter. If atomic, the table is unchanged and you just rerun. If not, the table may be partially updated; rerun only if your model is idempotent (deterministic SELECT plus merge on unique_key) so reprocessing the same window converges.", detailed:"Idempotency means rerunning the same batch yields the same final state. A merge on a stable unique_key with a deterministic, deduplicated SELECT is idempotent: reprocessing overlapping rows upserts to the same values. Append-only models are not idempotent and can double-insert on rerun. Knowing your adapter is transactionality tells you whether a partial write is even possible.", example:"{# idempotent: dedupe then merge on key #}\nselect * from (\n  select *, row_number() over(partition by id order by updated_at desc) rn\n  from {{ ref('src') }}\n) where rn = 1", mistake:"Blindly rerunning an append-strategy model after a partial failure, duplicating rows that the first run already inserted.", followup:"How would you make an append model safe to rerun?", senior:"Add a unique_key and switch to merge or delete+insert, or incorporate a deterministic lookback window so reruns overwrite the same slice. Design the SELECT to be a pure function of a bounded input window, which is the essence of making incremental loads idempotent and recovery trivial." },
  { tier:"intermediate", cat:"Incremental", q:"What does on_schema_change do, and what are its options?", short:"on_schema_change controls how an incremental model reacts when its SELECT columns differ from the existing table: ignore (default historically), append_new_columns, sync_all_columns, or fail. It governs column drift, not a full rebuild.", detailed:"When you add or remove a column in the model, incremental loads must reconcile with the existing table. ignore leaves the table schema as-is (new columns are dropped from inserts). append_new_columns adds new columns. sync_all_columns adds and removes to match. fail aborts so you handle it deliberately. It only manages schema evolution between runs, not data backfill.", example:"{{ config(\n  materialized='incremental',\n  on_schema_change='append_new_columns'\n) }}", mistake:"Expecting on_schema_change to backfill values for a newly added column; it only alters the table structure, leaving old rows NULL.", followup:"How do you populate the new column for historical rows?", senior:"Run a one-time --full-refresh (if feasible) or a bounded backfill that reprocesses the historical window, because on_schema_change only ALTERs the table to add the column; it does not recompute past rows. For huge tables, a targeted update or partition overwrite of the affected ranges is the pragmatic path." },
  { tier:"intermediate", cat:"Incremental", q:"How do you safely dedupe within an incremental SELECT to avoid duplicate keys?", short:"Use a window function: row_number() over (partition by unique_key order by updated_at desc) and keep rn = 1. This guarantees one row per key per load before the merge, preventing merge errors and duplicates.", detailed:"Source batches often contain multiple versions of the same key. Merge strategies can error or produce nondeterministic results on duplicate keys in the source. Deduplicating in the model SELECT (latest wins by timestamp) makes the merge deterministic and keeps the target clean. This is independent of adapter and strategy.", example:"with ranked as (\n  select *, row_number() over (\n    partition by order_id order by updated_at desc\n  ) as rn\n  from {{ ref('orders_raw') }}\n)\nselect * from ranked where rn = 1", mistake:"Relying on merge to pick the right duplicate; some adapters raise an error on multiple matches and others pick arbitrarily.", followup:"What if two rows share the key and timestamp exactly?", senior:"Add a deterministic tiebreaker to the order by (a load sequence id, file offset, or surrogate) so ranking is stable across runs. Without one, ties break nondeterministically, reintroducing the very nondeterminism dedup was meant to remove." },
  { tier:"scenario", cat:"Incremental", q:"You need to backfill one historical month into a large partitioned incremental model without rebuilding everything. How?", short:"On partitioned engines, use insert_overwrite (or microbatch with an event-time range) scoped to that month is partitions so only those partitions are replaced. Avoid full refresh, which rebuilds the entire table.", detailed:"insert_overwrite with a partition_by and a predicate limited to the target month swaps just those partitions atomically, leaving the rest untouched. With microbatch you pass --event-time-start/--event-time-end to rebuild only that window idempotently. Both avoid the cost and risk of a global rebuild on a huge table.", example:"{{ config(\n  materialized='incremental',\n  incremental_strategy='insert_overwrite',\n  partition_by={'field': 'event_date', 'data_type': 'date'}\n) }}", mistake:"Running --full-refresh to fix one month, triggering a massive, expensive rebuild of the whole table.", followup:"What if the warehouse has no partitioning (e.g. Snowflake)?", senior:"Use delete+insert with a predicate bounding the month (delete where event_date between X and Y, then insert that range) to emulate partition replacement. On non-partitioned warehouses you lean on clustering plus a scoped delete+insert rather than true partition overwrite." },
  { tier:"beginner", cat:"Snapshots", q:"What is a dbt snapshot and what problem does it solve?", short:"A snapshot captures how a mutable source row changes over time, writing type-2 history with validity columns. It solves the loss of history when a source overwrites records in place.", detailed:"Many source systems update rows destructively, so yesterday is value is gone today. A snapshot periodically records the current state and, when a tracked value changes, closes the old version and opens a new one. This preserves a full change history (who/what/when) that the live source does not keep.", example:"{% snapshot customers_snapshot %}\n{{ config(\n  unique_key='id',\n  strategy='timestamp',\n  updated_at='updated_at'\n) }}\nselect * from {{ source('app', 'customers') }}\n{% endsnapshot %}", mistake:"Treating a snapshot as a one-time backup; it must run on a schedule to capture changes as they happen.", followup:"What columns does dbt add to a snapshot?", senior:"dbt adds dbt_valid_from, dbt_valid_to (NULL for the current version), dbt_scd_id (a surrogate per version), and dbt_updated_at. Querying where dbt_valid_to is null gives the current state; the full table gives point-in-time history." },
  { tier:"intermediate", cat:"Snapshots", q:"Compare the timestamp and check snapshot strategies.", short:"timestamp uses an updated_at column to detect change (new timestamp means a new version), which is efficient and reliable. check compares a list of columns (or all) for differences, used when the source has no trustworthy updated_at.", detailed:"timestamp strategy trusts a monotonically updated column; if updated_at advances, dbt records a new version. It is cheap and precise but requires a dependable timestamp. check strategy diffs specified check_cols every run to spot changes, which works without a timestamp but is heavier and can miss changes that revert within a window or be fooled by nondeterministic ordering.", example:"{{ config(\n  strategy='check',\n  unique_key='id',\n  check_cols=['status', 'email']\n) }}", mistake:"Using timestamp strategy on a source whose updated_at is unreliable or not bumped on every change, missing updates.", followup:"What are the downsides of check_cols='all'?", senior:"check with all columns re-hashes/compares every column each run, which is costly on wide tables and fragile to cosmetic changes (type coercion, trailing spaces). It can also create spurious new versions from non-meaningful diffs, so listing only the business-relevant columns is usually better." },
  { tier:"fouryear", cat:"Snapshots", q:"What do dbt_valid_from and dbt_valid_to represent, and how do you query current versus historical state?", short:"dbt_valid_from is when a version became effective; dbt_valid_to is when it was superseded (NULL for the current version). Filter dbt_valid_to is null for current; use a point-in-time between predicate for history.", detailed:"These columns implement the validity interval of SCD type 2. The current row has an open interval (dbt_valid_to is null). To reconstruct state as of a date, you select rows where that date falls within [dbt_valid_from, dbt_valid_to). This gives correct as-of joins against fact data for accurate historical reporting.", example:"select * from {{ ref('customers_snapshot') }}\nwhere '2026-01-15' >= dbt_valid_from\n  and ('2026-01-15' < dbt_valid_to or dbt_valid_to is null)", mistake:"Using an inclusive upper bound (<=) on dbt_valid_to, which double-counts the boundary moment where one version ends and the next begins.", followup:"Why is dbt_valid_to typically exclusive?", senior:"Treating the interval as half-open [from, to) ensures each instant maps to exactly one version with no overlap or gap at the boundary. Using inclusive bounds on both ends would make the transition moment match two versions, breaking point-in-time correctness." },
  { tier:"intermediate", cat:"Snapshots", q:"What does invalidate_hard_deletes do in a snapshot?", short:"invalidate_hard_deletes=true makes the snapshot detect rows that disappeared from the source and close their validity window (set dbt_valid_to), rather than leaving them perpetually current.", detailed:"By default a snapshot only tracks inserts and changes present in the source; a row deleted upstream stays open (dbt_valid_to null) as if still current. With invalidate_hard_deletes enabled, dbt compares the full source to the snapshot and marks missing keys as ended, recording the deletion in history. This requires the source query to represent the complete current set.", example:"{{ config(\n  strategy='timestamp',\n  unique_key='id',\n  updated_at='updated_at',\n  invalidate_hard_deletes=true\n) }}", mistake:"Expecting hard-delete detection by default; without the flag, deleted rows remain flagged as the current version forever.", followup:"Why can a filtered source query break hard-delete detection?", senior:"invalidate_hard_deletes infers deletion from absence, so if your snapshot SELECT filters rows (e.g. where region = X), legitimately present rows look deleted and get closed incorrectly. The source query must return the full universe of keys for absence to mean deletion." },
  { tier:"senior", cat:"Snapshots", q:"How is a snapshot different from an incremental model, and when would you pick each?", short:"An incremental model efficiently loads deltas into a current-state table; a snapshot records change history (SCD2) of mutable rows. Use incremental for scaling large append/update loads, snapshots for preserving how records changed over time.", detailed:"Incremental optimizes build cost and generally keeps one current row per key (with merge). Snapshots deliberately keep many versions per key with validity intervals to answer as-of questions. They solve different problems: throughput and freshness versus historical auditability. You often snapshot a raw mutable source and build incremental marts downstream.", example:"{# snapshot: history #}\n{% snapshot s %}{{ config(strategy='timestamp', unique_key='id', updated_at='updated_at') }}\nselect * from {{ source('app','t') }}{% endsnapshot %}", mistake:"Hand-rolling SCD2 logic in an incremental model when a snapshot already does it correctly and idempotently.", followup:"Could you build SCD2 with an incremental model instead?", senior:"You can, but you reimplement version closing, surrogate keys, and change detection yourself, which is error-prone. Snapshots encapsulate that and are idempotent by design. Rolling your own is justified only for requirements snapshots cannot express (custom validity logic, multi-table effective dating)." },
  { tier:"senior", cat:"Snapshots", q:"A dbt snapshot produces SCD type 2, but is it identical to every SCD2 implementation? Where does it fall short?", short:"No. Snapshots are a specific, opinionated SCD2: one unique_key, change detection by timestamp or check_cols, half-open validity, and run-time granularity. They do not natively handle composite effective-dating, retroactive corrections, bi-temporal history, or sub-run change resolution.", detailed:"Classic SCD2 can involve bi-temporal modeling (valid time vs transaction time), handling of out-of-order or backdated changes, and custom merge rules. dbt snapshots record change as of when the snapshot runs, so changes between runs collapse and you cannot capture multiple intermediate states. Retroactive corrections and effective-date logic beyond the built-in strategies require custom modeling.", example:"{# snapshot granularity = run cadence; two changes between runs appear as one #}", mistake:"Promising full historical fidelity; a snapshot only captures state at each run, so intra-run changes are lost.", followup:"How do you capture changes that happen between snapshot runs?", senior:"You need a true CDC stream (log-based or source-emitted change events) feeding an incremental model, because snapshots sample state on a schedule and inherently miss changes that occur and revert between runs. For high-fidelity history, capture at the source rather than sampling." },
  { tier:"architecture", cat:"Snapshots", q:"When is a dbt snapshot the right tool versus warehouse-native CDC or source-provided change streams?", short:"Use snapshots when the source only exposes current state and run-cadence history is acceptable. Use native CDC/change streams when you need every intermediate change, exact timing, deletes, and low-latency history that periodic sampling cannot provide.", detailed:"Snapshots are simple, version-controlled, and adequate when the source lacks CDC and business history needs match your run frequency. But they sample, so they miss intra-run changes and depend on reliable updated_at or costly column checks. When the platform offers log-based CDC (Streams, change tracking, Debezium, binlog), that captures every change with ordering and deletes, which is superior for audit-grade or high-frequency history.", example:"{# Decision: no CDC + daily history ok -> snapshot; audit-grade + deletes -> source CDC #}", mistake:"Forcing snapshots onto a high-change, audit-critical source where sampling loses required intermediate states and exact timing.", followup:"How might you combine both approaches?", senior:"Land source CDC into raw change tables (capturing every event and delete), then model current-state and history downstream in dbt, optionally snapshotting derived dimensions. dbt orchestrates and tests the transformations while the warehouse/CDC layer guarantees completeness, playing each tool to its strength." },
  { tier:"intermediate", cat:"Snapshots", q:"Why should snapshots be built before the models that depend on them, and where should they live?", short:"Snapshots must run first because they capture source state at run time; downstream models ref the snapshot and need its latest versions. They live in the snapshots path and are selected into runs so history is recorded on the right cadence.", detailed:"Since a snapshot records change as of its execution, running dependent models before the snapshot would read stale history. dbt is DAG handles ordering when models ref the snapshot. Snapshots are often scheduled on their own reliable cadence (close to the source refresh) so no change is missed between runs.", example:"dbt snapshot\ndbt run --select +customers_snapshot+", mistake:"Running snapshots inconsistently or after transforms, causing missed change capture and stale downstream history.", followup:"Should snapshots select from raw sources or from models?", senior:"Best practice is to snapshot as close to the raw source as possible (source() over ref() of a transformed model), so you capture true source history undistorted by transformations that might filter or reshape rows and corrupt change detection or hard-delete inference." },
  { tier:"debugging", cat:"Incremental", q:"An incremental model is producing duplicate rows. Walk through how you would diagnose it.", short:"Check whether unique_key is set and correct, whether the strategy is append (which never updates), whether the source has duplicate keys per batch, and whether the delta filter overlaps without dedup. Inspect compiled SQL and the merge predicate.", detailed:"Duplicates usually come from one of: append strategy with reprocessing, a missing/wrong unique_key, a lookback window overlapping prior loads without merge-based dedup, or duplicate keys within a single source batch. Read target/compiled to see the actual load SQL, then query the target grouping by the key to find where duplication enters.", example:"select order_id, count(*) \nfrom {{ this }}\ngroup by 1 having count(*) > 1", mistake:"Assuming unique_key automatically dedupes in-batch duplicates; it dedupes against existing rows, not within the incoming set.", followup:"The unique_key is set but duplicates persist. What next?", senior:"Check for in-batch duplicate keys (dedupe with row_number in the SELECT), verify the key is actually unique in the source, confirm the strategy supports updates on your adapter, and ensure the lookback overlap is covered by merge rather than append. The compiled merge/insert statement reveals which it is." },
  { tier:"debugging", cat:"Jinja", q:"A model compiles with a trailing comma before FROM and the warehouse rejects it. How do you fix it?", short:"A loop generating columns is emitting a comma after the last item. Gate the separator with loop.last (comma before each item except first, or after each except last) and inspect compiled SQL to confirm.", detailed:"Trailing/leading comma errors come from static separator placement inside {% for %}. The robust fix is loop.last or loop.first logic so the delimiter never dangles at the boundary. Whitespace control helps readability but the comma character itself must be conditionally omitted. Always verify against target/compiled output.", example:"select\n{% for c in cols %}\n  {{ \", \" if not loop.first }}{{ c }}\n{% endfor %}\nfrom {{ ref('t') }}", mistake:"Adding -%} whitespace trimming hoping it removes the comma; trimming whitespace does not remove the comma token.", followup:"What is a clean leading-comma alternative?", senior:"Emit the comma before each column except the first ({{ \", \" if not loop.first }}c), which keeps diffs stable and avoids trailing-comma errors entirely. Many teams standardize on leading commas in generated SQL for exactly this reason." },
  { tier:"debugging", cat:"Jinja", q:"run_query returns None in your model and the code crashes. What is the likely cause?", short:"You are running it during the parse phase where execute is False, so run_query returns None. Wrap the call in {% if execute %} and provide a safe default for the parse branch.", detailed:"dbt renders Jinja at parse time to build the DAG without hitting the warehouse, so database-reading functions return None then. Accessing .columns or iterating that None throws. The fix is the execute guard, initializing your variable to an empty list/dict beforehand so the parse-time render is valid.", example:"{% set vals = [] %}\n{% if execute %}\n  {% set vals = run_query(sql).columns[0].values() %}\n{% endif %}", mistake:"Removing the error by catching exceptions instead of guarding with execute, masking the real parse/execute lifecycle issue.", followup:"Why does dbt render Jinja during parse at all?", senior:"Parsing must resolve ref/source/config to construct the DAG and gather metadata before any model runs. It deliberately avoids warehouse queries for speed and because the objects may not exist yet, which is exactly why data-reading functions are inert until execute." },
  { tier:"sql", cat:"Incremental", q:"Write the canonical incremental filter using is_incremental() and this.", short:"Guard a WHERE clause with is_incremental() that selects only rows newer than the current max watermark in this, optionally with a lookback for late data.", detailed:"The pattern runs the full SELECT on first run/full refresh and, on incremental runs, restricts to new rows by comparing the source timestamp to max(timestamp) in the existing table. Adding a lookback window plus a unique_key merge handles late-arriving data safely.", example:"select * from {{ ref('events') }}\n{% if is_incremental() %}\nwhere event_ts >= (\n  select coalesce(max(event_ts), '1900-01-01') from {{ this }}\n)\n{% endif %}", mistake:"Omitting coalesce, so an empty table is max(event_ts) is NULL and the comparison filters out everything.", followup:"Why the coalesce fallback?", senior:"If this is empty (edge case where the table exists but has no rows), max returns NULL and event_ts >= NULL is never true, loading zero rows. coalesce to a floor date guarantees the first meaningful load proceeds, making the filter robust to empty-but-existing targets." },
  { tier:"sql", cat:"Snapshots", q:"Write a point-in-time query against a snapshot to get each key is value as of a given date.", short:"Select from the snapshot where the as-of date falls within the half-open validity interval: date >= dbt_valid_from and (date < dbt_valid_to or dbt_valid_to is null).", detailed:"Each key has one version whose interval contains the as-of instant. The upper bound is exclusive and the current version has NULL dbt_valid_to, so you handle NULL explicitly. This yields exactly one row per key for the historical state on that date.", example:"select id, status\nfrom {{ ref('customers_snapshot') }}\nwhere date '2026-06-01' >= dbt_valid_from\n  and (date '2026-06-01' < dbt_valid_to or dbt_valid_to is null)", mistake:"Forgetting the dbt_valid_to is null branch, which drops the current version and returns nothing for keys that have not changed since.", followup:"How would you as-of join this to a fact table?", senior:"Join on the key and put the fact is event timestamp into the same interval predicate (fact_ts >= dbt_valid_from and (fact_ts < dbt_valid_to or dbt_valid_to is null)), giving each fact the dimension version that was current when it occurred, which is the correct SCD2 as-of join." },
  { tier:"intermediate", cat:"Jinja", q:"How do var() and env_var() differ, and when do you use each?", short:"var() reads project variables (defined in dbt_project.yml or passed with --vars), good for configuring logic. env_var() reads OS environment variables, good for secrets and deployment-specific values. var() can have defaults inline; env_var() can too.", detailed:"Use var() for business/config knobs tracked in the project (lookback days, feature flags). Use env_var() for things that must not live in code or change per environment (credentials, bucket names, run context). Both support defaults, but env_var pulls from the runtime environment at compile time.", example:"{{ var('lookback_days', 3) }}\n{{ env_var('DBT_TARGET_BUCKET', 's3://default') }}", mistake:"Hardcoding secrets as var() values in dbt_project.yml, committing them to source control.", followup:"When does env_var() read the variable, and why does that matter?", senior:"It reads at compile time, so the value is baked into compiled SQL/artifacts. Changing the env var requires recompiling. For secrets, that means the compiled artifacts can contain the value, so treat compiled output and logs as sensitive and prefer references that the warehouse resolves where possible." },
  { tier:"fouryear", cat:"Materializations", q:"What is an ephemeral model, and what are its practical limitations?", short:"An ephemeral model creates no database object; dbt inlines its compiled SQL as a CTE into every model that refs it. It is good for small shared logic but cannot be queried directly, is not in the catalog, and duplicates into each consumer.", detailed:"Ephemeral keeps the warehouse clean of trivial intermediate objects and avoids extra storage. The cost is that the CTE is copied into each downstream model, so complex or widely-referenced ephemeral logic bloats compiled SQL and can confuse the optimizer. You also cannot inspect or test its output as a standalone relation.", example:"{{ config(materialized='ephemeral') }}\nselect id, lower(email) as email from {{ source('app','users') }}", mistake:"Using ephemeral for heavy logic referenced by many models, multiplying compute and compiled SQL size.", followup:"How do you debug an ephemeral model is output?", senior:"You cannot query it directly, so temporarily materialize it as a view/table, or inspect a consumer is compiled SQL to see the injected CTE. For anything you need to test or observe independently, a view is the better materialization despite the small storage cost." },
  { tier:"intermediate", cat:"Adapter dispatch", q:"Why should cross-database macros avoid dialect-specific functions, and how does dbt help?", short:"Functions like date arithmetic, string concat, and hashing differ across warehouses, so hardcoding one dialect breaks portability. dbt provides cross-db macros (e.g. dbt.dateadd, dbt.datediff, dbt.concat) that dispatch to each adapter is syntax.", detailed:"dbt and dbt_utils ship adapter-aware shims for common operations so your SQL runs on any supported warehouse. Instead of writing Snowflake-specific dateadd, you call the cross-db macro which dispatches to the right implementation. This is essential for packages and multi-warehouse codebases.", example:"select {{ dbt.dateadd('day', 7, 'order_date') }} as due_date\nfrom {{ ref('orders') }}", mistake:"Writing Snowflake or BigQuery native functions in a shared package macro, breaking it on other adapters.", followup:"What if no cross-db macro exists for an operation you need?", senior:"Write your own dispatched macro: a public macro returning adapter.dispatch(...), plus default__ and adapter-specific implementations. This keeps the dialect differences isolated behind one interface, matching how dbt is own cross-db macros are structured." },
  { tier:"architecture", cat:"Materializations", q:"How do you decide materialization per layer in a staging/intermediate/mart architecture?", short:"Commonly: staging as views (thin, fresh, cheap), intermediate as ephemeral or views (reusable logic, sometimes tables if heavy), marts as tables or incremental (fast reads, scaled builds). Decide by read frequency, build cost, and freshness.", detailed:"Staging normalizes raw sources with light transforms, so views keep it fresh and cheap. Intermediate holds reusable building blocks; ephemeral avoids clutter but heavy ones become tables. Marts are consumed by BI, favoring tables for speed and incremental for large fact tables. There is no universal rule; profile cost and usage.", example:"{# stg_*.sql #}{{ config(materialized='view') }}\n{# fct_*.sql #}{{ config(materialized='incremental', unique_key='id') }}", mistake:"Blanket-materializing every layer as table, exploding storage and build time, or everything as view, slowing marts.", followup:"When would you make a staging model a table instead of a view?", senior:"When the staging transform is expensive and consumed by many downstream models, materializing it once as a table avoids recomputing the view per consumer. Also when a view over a huge external/raw source is slow to scan repeatedly, a cached table improves overall DAG performance." },
  { tier:"scenario", cat:"Incremental", q:"A source occasionally re-sends a full day of already-loaded data with corrections. How should your incremental model handle it?", short:"Use a delete+insert or insert_overwrite (partitioned) or merge keyed on the business key, scoped to the affected day, so the corrected rows replace prior ones rather than duplicating. A lookback or event-time window covers the reprocessed day.", detailed:"Corrections mean the same keys arrive with new values. Append would duplicate; you need upsert/replace semantics over the day is key space. On partitioned engines, overwrite that day is partition. Elsewhere, merge on unique_key or delete rows for that day then insert. Ensure the SELECT reprocesses the full corrected window.", example:"{{ config(materialized='incremental', incremental_strategy='delete+insert', unique_key='id') }}\nselect * from {{ ref('daily_feed') }}\n{% if is_incremental() %}\nwhere load_date >= dateadd('day', -2, current_date)\n{% endif %}", mistake:"Using append strategy, so corrected re-sends double the day is rows instead of replacing them.", followup:"How do you make sure the whole corrected day is reprocessed?", senior:"Scope the delete/overwrite predicate to the full day boundary (not just rows above the max watermark) and ensure the SELECT reads the entire corrected window. The replace predicate and the SELECT window must align on the same day grain so no stale rows survive the correction." },
  { tier:"intermediate", cat:"Macros", q:"What is the difference between invoking a macro in {{ }} versus capturing it with set, and how does the dbt operation/run-operation flow relate?", short:"In {{ }} a macro renders into SQL; with {% set x = macro() %} you capture its rendered text or returned value. dbt run-operation executes a macro standalone (for maintenance tasks) outside any model, using return/statements for side effects.", detailed:"Macros are the unit of reuse for both SQL generation (inside models) and operational tasks (grants, vacuum, backfills) run via dbt run-operation. run-operation calls a macro directly with --args, letting you perform imperative work (DDL, API-less admin) through dbt is connection without a model.", example:"dbt run-operation grant_select --args '{role: analyst, relation: analytics.orders}'", mistake:"Trying to put side-effecting admin SQL inside a model where it does not belong, instead of a run-operation macro.", followup:"How does a run-operation macro actually execute SQL?", senior:"It uses statement blocks or the run_query/adapter API to issue SQL against the target connection during execution. Because there is no model relation, you drive everything imperatively with {% do run_query(...) %} or statement/load_result, which is how operational macros perform DDL and maintenance." },
  { tier:"senior", cat:"Incremental", q:"Explain idempotency in incremental models and why it is the key property for safe reruns and orchestration retries.", short:"Idempotency means running the same load twice yields the same final table. Achieve it with a deterministic, deduplicated SELECT over a bounded window plus merge/delete+insert on a stable unique_key, so retries converge instead of duplicating.", detailed:"Orchestrators retry failed tasks, so a load must be safe to repeat. Append strategies are not idempotent (reruns double rows). Upsert on a unique_key with a deterministic SELECT (deduped, fixed window) is idempotent: reprocessing the same slice overwrites to identical values. This makes failures recoverable by simply rerunning.", example:"{# idempotent window + merge #}\n{{ config(materialized='incremental', incremental_strategy='merge', unique_key='id') }}\nselect * from {{ ref('src') }}\n{% if is_incremental() %}where _ts >= dateadd('hour', -6, (select max(_ts) from {{ this }})){% endif %}", mistake:"Shipping an append-strategy model into an auto-retrying orchestrator, guaranteeing duplicates on every transient failure.", followup:"How does microbatch strengthen idempotency guarantees?", senior:"microbatch builds each time window as an isolated, replaceable unit, so reprocessing a batch deterministically overwrites just that period. The per-batch isolation makes idempotency structural rather than something you hand-engineer with lookback plus merge, and it bounds the blast radius of any retry." },
  { tier:"fouryear", cat:"Snapshots", q:"What is dbt_scd_id and why does a snapshot need a surrogate key per version?", short:"dbt_scd_id is a surrogate hash uniquely identifying each version (row) in the snapshot, typically derived from the unique_key plus the change timestamp. It gives every historical version a stable, unique primary key.", detailed:"Since one business key has many versions, the natural key is not unique in the snapshot table. dbt_scd_id provides a per-version surrogate so downstream joins and tests can reference a single version unambiguously. dbt computes it deterministically so the same version always gets the same id across runs.", example:"{# dbt generates dbt_scd_id = hash(unique_key, dbt_updated_at) per version #}\nselect dbt_scd_id, id, status, dbt_valid_from, dbt_valid_to\nfrom {{ ref('customers_snapshot') }}", mistake:"Joining facts to a snapshot on the business key alone, which matches all versions; you need the version-correct row via validity interval or scd_id.", followup:"Why must dbt_scd_id be deterministic?", senior:"Deterministic generation means reruns and incremental snapshot updates produce stable ids for existing versions, so downstream references do not churn and tests stay valid. Nondeterministic surrogates would break joins and uniqueness assumptions every run, defeating the point of a stable historical key." },
  { tier:"debugging", cat:"Snapshots", q:"After changing a snapshot is check_cols, you see unexpected new versions on the next run. Why?", short:"Changing the tracked columns alters change detection: columns now included may differ from the last recorded version, so dbt opens new versions. The first run after the change reconciles current source values against stored ones under the new column set.", detailed:"The check strategy compares the configured columns. Adding columns means differences there now count as changes, so rows whose newly-tracked columns differ from the stored version get a new version on the next run. This is expected one-time churn, not a bug, though it can be surprising at scale.", example:"{# added 'phone' to check_cols -> rows with changed phone since last snapshot get new versions #}", mistake:"Assuming the snapshot is corrupted; it is correctly detecting change under the newly configured columns.", followup:"How do you avoid a mass version explosion when expanding check_cols?", senior:"Plan the change deliberately: communicate the expected one-time churn, consider whether the new columns are genuinely meaningful (not cosmetic), and if the volume is problematic, evaluate rebuilding the snapshot or switching to a timestamp strategy where a reliable updated_at exists, which avoids column-diff churn entirely." },
  { tier:"intermediate", cat:"Jinja", q:"How do config() calls in a model interact with configs set in dbt_project.yml?", short:"In-model config() takes precedence over dbt_project.yml for the same key, which sets defaults by path/folder. This lets you set broad defaults centrally and override per model inline.", detailed:"dbt merges configuration from dbt_project.yml (folder-level), property yml files, and in-file config() with a defined precedence where the most specific (in-model) wins. This supports a pattern of folder-wide defaults (e.g. all staging as views) with targeted overrides for exceptional models.", example:"# dbt_project.yml\nmodels:\n  my_project:\n    staging:\n      +materialized: view\n{# model overrides to table #}\n{{ config(materialized='table') }}", mistake:"Expecting dbt_project.yml to override an in-model config(); the in-model setting is more specific and wins.", followup:"How are list/dict configs like tags merged versus replaced?", senior:"Some configs (like tags, meta, grants in certain cases) merge additively across levels rather than fully replacing, while scalars override. Knowing which clobber and which accumulate prevents surprises, e.g. tags from project and model combine rather than one replacing the other." },
  { tier:"scenario", cat:"Snapshots", q:"You need history of a dimension, but the source has no reliable updated_at and is very wide. What snapshot approach do you choose and what are the risks?", short:"Use the check strategy with a curated list of business-relevant check_cols (not all), since there is no trustworthy timestamp. Risks: compute cost of diffing, missed sub-run changes, and churn if columns are noisy. Consider upstream CDC if fidelity matters.", detailed:"Without a dependable updated_at, timestamp strategy would miss changes, so check is correct. Listing only meaningful columns limits cost and spurious versions on a wide table. Accept that changes between runs collapse and that type/formatting noise can create false versions, so normalize those columns upstream.", example:"{{ config(strategy='check', unique_key='id', check_cols=['status','tier','region']) }}", mistake:"Using check_cols='all' on a very wide table, incurring heavy per-run diff cost and false versions from cosmetic differences.", followup:"When would you escalate beyond snapshots here?", senior:"If the business needs every intermediate change, exact timing, or deletes, periodic check-based sampling is insufficient; move to source-level CDC (log-based change capture) feeding an incremental history model. Snapshots sample state, so audit-grade requirements on a timestamp-less source eventually outgrow them." },
  { tier:"intermediate", cat:"Materializations", q:"What is the difference between a model is ref relationship and how incremental vs table materializations affect downstream freshness?", short:"ref builds the DAG regardless of materialization. But a table/incremental consumer reads persisted data from its last build, while a view consumer recomputes from upstream on each read, affecting how fresh downstream reads are between dbt runs.", detailed:"If an upstream model is a view and you query a downstream view, reads reflect current upstream source data live. If upstream is a table, downstream reads only see data as of the last build. Incremental adds the nuance that only loaded deltas are present. Materialization choice thus shapes end-to-end freshness and consistency between runs.", example:"{# chain of views = always-live but recompute-heavy; chain of tables = snapshot-consistent but stale between runs #}", mistake:"Assuming downstream data is always current; with table/incremental upstreams, reads are only as fresh as the last dbt build.", followup:"How do you get both freshness and performance?", senior:"Materialize expensive shared logic as tables/incremental built on a frequent schedule, and keep thin top layers as views for liveness, or use incremental with short cadences. Freshness is ultimately governed by run frequency for persisted layers, so orchestrate build cadence to meet the SLA rather than relying on materialization alone." },
  { tier:"fouryear", cat:"Incremental", q:"What is a lookback window, how do you size it, and what does it cost?", short:"A lookback reprocesses a trailing time range each incremental run (e.g. last 3 days) so late-arriving rows are captured. Size it to cover expected source lateness; the cost is reprocessing that overlap every run plus needing merge-based dedup.", detailed:"Instead of loading strictly newer-than-watermark rows, you subtract a buffer so any row that arrived late within that window gets picked up. Pairing with unique_key merge ensures the overlapping reprocessed rows upsert rather than duplicate. Too small a window loses late data; too large wastes compute.", example:"{% if is_incremental() %}\nwhere event_ts >= dateadd('day', -3, (select max(event_ts) from {{ this }}))\n{% endif %}", mistake:"Pairing a lookback with append strategy, which duplicates every row in the overlapping window on each run.", followup:"How do you choose the window size empirically?", senior:"Measure the distribution of arrival lag (source event time vs load time) and set the window above a high percentile (e.g. p99) of observed lateness, balancing against reprocessing cost. Monitor for rows arriving beyond the window and alert, since anything later than the lookback is silently missed unless a periodic full/partition backfill catches it." },
  { tier:"intermediate", cat:"Jinja", q:"How do conditionals with elif and boolean logic work in Jinja for dbt models?", short:"Jinja supports {% if %}/{% elif %}/{% else %}/{% endif %} with and/or/not and comparisons. You branch on vars, target, config values, or run_query results to vary compiled SQL.", detailed:"Conditionals choose which SQL to emit at compile time. You can combine conditions (target.name == 'prod' and var('enable_x')), test membership (x in list), and nest branches. Remember these resolve before execution, so they cannot test row values directly.", example:"{% if target.name == 'prod' %}\n  {# full dataset #}\n{% elif var('sample', false) %}\n  where rand() < 0.01\n{% else %}\n  where created_at >= dateadd('day', -7, current_date)\n{% endif %}", mistake:"Writing an elif as a separate {% if %} without endif chaining, producing wrong branch logic or syntax errors.", followup:"How do you test membership in a list in Jinja?", senior:"Use the in operator ({% if col in excluded %}) or filters like select/reject for list operations. Jinja is Python-like membership works on lists, dicts (keys), and strings, which is handy for excluding columns or gating behavior by environment name sets." },
  { tier:"senior", cat:"Macros", q:"How would you design a reusable macro to generate SCD2-style staging, and why might you still prefer snapshots?", short:"You could write a dispatched macro that computes validity intervals via window functions over a change-detected set, parameterized by key and tracked columns. But snapshots already do this idempotently with hard-delete handling, so a custom macro is justified only for needs snapshots cannot meet.", detailed:"A hand-rolled SCD2 macro would dedupe, detect change, assign dbt_valid_from/to with lead() over the key ordered by time, and compute a surrogate. It is portable via dispatch but must handle late data, deletes, and reruns carefully. Snapshots encapsulate all this and are purpose-built, so reinvent only for bi-temporal logic, custom effective dating, or multi-source merges.", example:"select *, \n  dbt_valid_from,\n  lead(dbt_valid_from) over (partition by id order by dbt_valid_from) as dbt_valid_to\nfrom change_detected", mistake:"Reimplementing SCD2 in a macro and getting validity-interval edge cases (boundaries, deletes, reruns) subtly wrong where snapshots are correct.", followup:"What edge cases make hand-rolled SCD2 risky?", senior:"Boundary semantics (half-open intervals), out-of-order and backdated changes, hard-delete closure, duplicate keys, and idempotent reruns are each easy to get wrong. Snapshots solve these consistently, so a custom macro should only exist when requirements (e.g. transaction-time plus valid-time bi-temporality) genuinely exceed snapshot capabilities." },
  { tier:"architecture", cat:"Incremental", q:"How do you choose between full-refresh table, standard incremental, and microbatch for a large event fact table?", short:"Full-refresh table is simplest but cost scales with total volume. Standard incremental loads deltas cheaply but needs careful late-data/dedup logic. microbatch (newer) gives isolated idempotent time windows, best for very large, backfill-heavy, late-arriving event data on supporting adapters.", detailed:"Pick table if the dataset is small enough that a full rebuild is cheap and simplicity matters. Pick standard incremental when rebuild is too costly and your lateness/dedup needs are modest. Pick microbatch when you have large, time-series event data with meaningful backfills and want per-window idempotency and parallelism, accepting its newer status and adapter requirements.", example:"{{ config(materialized='incremental', incremental_strategy='microbatch', event_time='event_ts', batch_size='day', lookback=3) }}", mistake:"Reaching for microbatch everywhere despite it being newer and adapter-dependent, or clinging to full-refresh on data too large to rebuild.", followup:"What operational benefits does microbatch add over standard incremental for backfills?", senior:"Per-batch isolation means you backfill a date range with --event-time-start/--end rebuilding only those windows, with retries scoped to a single batch and natural parallelism across windows. Standard incremental treats the load as one statement, making targeted backfills and partial-failure recovery clumsier." },
  { tier:"intermediate", cat:"Macros", q:"What does adapter.get_columns_in_relation return, and why is it execution-dependent?", short:"It returns a list of Column objects (name, data_type, etc.) for an existing relation by querying catalog metadata. Because it reads the warehouse, the relation must exist and it is only meaningful during execution, not parse.", detailed:"This introspection powers dynamic column lists (select-except, star, type-aware casts). Since it queries the information schema, the upstream relation must already be built, so DAG order matters and parse-time calls return nothing. Guard with execute and ensure dependencies are materialized first.", example:"{% set cols = adapter.get_columns_in_relation(ref('orders')) %}\n{% for c in cols %}{{ c.name }}{% if not loop.last %},{% endif %}{% endfor %}", mistake:"Calling it on a model that has not been built yet (clean run or wrong DAG order), getting empty results and malformed SQL.", followup:"How does this constraint affect first-time full builds?", senior:"On a from-scratch build, a model that introspects an upstream relation needs that upstream materialized first; dbt is DAG ordering handles this as long as the dependency is a real ref. Introspecting a not-yet-built relation (e.g. via get_relation on a hardcoded name) breaks, which is why passing ref() relations keeps ordering correct." },
  { tier:"beginner", cat:"Snapshots", q:"Which configs are required for a timestamp-strategy snapshot?", short:"A timestamp snapshot needs unique_key, strategy='timestamp', and updated_at (the column dbt watches for change). Optionally invalidate_hard_deletes and target schema/database.", detailed:"unique_key identifies the business key, strategy picks the detection method, and updated_at names the column whose advancement signals a new version. Without a reliable updated_at you would use the check strategy instead. These configs live in the snapshot block or in YAML for newer dbt versions.", example:"{% snapshot orders_snap %}\n{{ config(unique_key='order_id', strategy='timestamp', updated_at='updated_at') }}\nselect * from {{ source('app','orders') }}\n{% endsnapshot %}", mistake:"Specifying strategy=timestamp but pointing updated_at at a column that is not reliably bumped on every change, silently missing updates.", followup:"Can snapshot configs be defined in YAML now?", senior:"Modern dbt supports defining snapshots and their configs in YAML (and recommends the schema-based snapshot definition in recent versions), separating config from SQL. The required keys are the same; only the location/format of the configuration changed." },
  { tier:"intermediate", cat:"Jinja", q:"What is a dictionary (dict) in Jinja and how is it used in dbt configs like partition_by?", short:"Jinja supports dicts ({'key': value}) which dbt uses for structured configs such as partition_by and cluster settings. You pass them to config() and macros to carry multiple named parameters.", detailed:"Dicts group related options, e.g. partition_by={'field': 'dt', 'data_type': 'date', 'granularity': 'day'} on BigQuery. Macros accept dicts for flexible parameterization, and you access members with dict.key or dict['key']. This structured form is how adapter-specific configs are expressed.", example:"{{ config(\n  materialized='incremental',\n  incremental_strategy='insert_overwrite',\n  partition_by={'field': 'event_date', 'data_type': 'date', 'granularity': 'day'}\n) }}", mistake:"Passing a partition_by string where the adapter expects a dict, or using keys the adapter does not recognize.", followup:"Why is partition_by adapter-specific?", senior:"Partitioning is a physical storage feature of engines like BigQuery and Spark; Snowflake has clustering instead, and Postgres has native partitioning with different semantics. So partition_by and insert_overwrite are meaningful only on partition-aware adapters, and the dict is schema differs accordingly, which is why you never assume one partitioning config is portable." },
  { tier:"debugging", cat:"Materializations", q:"A model configured as incremental is doing a full rebuild every run. What would you check?", short:"Verify is_incremental() is actually gating the filter, that --full-refresh is not being passed by the scheduler, that the table was not dropped between runs, and that on_schema_change or a failing merge is not forcing rebuilds.", detailed:"If the incremental branch is missing or mis-gated, the full SELECT always runs and replaces data. Check compiled SQL for the WHERE clause presence. Confirm the orchestrator is not invoking --full-refresh, that the relation persists (not dropped by a pre-hook), and that schema drift or a broken merge is not triggering fallback rebuilds.", example:"{# confirm the guard exists and compiles #}\n{% if is_incremental() %}\n  where loaded_at > (select max(loaded_at) from {{ this }})\n{% endif %}", mistake:"Overlooking a scheduler flag or CI step that passes --full-refresh on every run, masking the model as non-incremental.", followup:"How do you confirm whether it is rebuilding?", senior:"Inspect run logs/artifacts and the compiled SQL: a create or replace / drop indicates full rebuild, while a merge/insert-into-existing indicates true incremental. Row counts and build times per run, plus the actual DDL/DML in logs, tell you definitively which path executed." },
  { tier:"sql", cat:"Macros", q:"Write a dispatched macro skeleton that implements a cross-database operation with a default and one override.", short:"Define a public macro returning adapter.dispatch(name, package)(args), a default__ implementation for most adapters, and an adapter-prefixed override (e.g. bigquery__) where the dialect differs.", detailed:"The public macro is the call site; dispatch routes to default__ unless an adapter-specific version exists. This is the canonical pattern for portable macros and is how dbt_utils and dbt-core cross-db macros are built. The search order can be extended so projects override package implementations.", example:"{% macro safe_divide(a, b) %}\n  {{ return(adapter.dispatch('safe_divide', 'my_pkg')(a, b)) }}\n{% endmacro %}\n{% macro default__safe_divide(a, b) %}\n  {{ a }} / nullif({{ b }}, 0)\n{% endmacro %}\n{% macro bigquery__safe_divide(a, b) %}\n  safe_divide({{ a }}, {{ b }})\n{% endmacro %}", mistake:"Forgetting the default__ implementation, so adapters without a specific override fail to resolve the macro.", followup:"How does dbt decide which implementation to call?", senior:"It builds the candidate name from the active adapter prefix (e.g. bigquery__safe_divide), searches the configured dispatch order of namespaces, and falls back to default__ if no adapter-specific match exists. Configuring the search order lets your project take precedence over a package is implementation." },
  { tier:"fouryear", cat:"Snapshots", q:"How does dbt decide whether to open a new snapshot version versus leave a row unchanged?", short:"For timestamp strategy, if the source row is updated_at is newer than the stored version is, dbt closes the old version and opens a new one. For check strategy, if any tracked column differs from the stored version, it opens a new version; otherwise the row is left as-is.", detailed:"Each run, dbt matches source rows to the current (open) snapshot version by unique_key. Timestamp compares updated_at; check compares check_cols. On a detected change it sets the old version is dbt_valid_to and inserts a new current row; unchanged rows are untouched. New keys are inserted as fresh current versions.", example:"{# timestamp: source.updated_at > snapshot.dbt_updated_at -> new version #}", mistake:"Assuming every run creates versions; only detected changes do, so a run over unchanged data produces no new rows.", followup:"What happens if updated_at goes backward (a correction with an older timestamp)?", senior:"Timestamp strategy compares against the stored value, so a backdated updated_at may not trigger a new version (it is not newer), silently dropping the change. This is a known pitfall; if corrections can lower updated_at, the check strategy or a reliable monotonic column is safer for accurate change capture." },
  { tier:"intermediate", cat:"Incremental", q:"Why must the incremental delta filter live inside the is_incremental() block and not run on first build?", short:"On the first build the target table does not exist, so selecting max() from this would error, and you want the full historical load anyway. is_incremental() is False then, skipping the filter so the complete SELECT populates the table.", detailed:"The delta filter references this to find the watermark, which requires an existing table. is_incremental() returns False on first run and full refresh precisely so the bootstrap loads everything without querying a nonexistent relation. Placing the filter outside the guard would both break the first run and wrongly limit the initial load.", example:"select * from {{ ref('events') }}\n{% if is_incremental() %}\n  where event_ts > (select max(event_ts) from {{ this }})\n{% endif %}", mistake:"Putting the watermark filter outside the guard, causing a missing-relation error on first build and an incomplete initial load.", followup:"What if you want to limit even the first load (e.g. only last 2 years)?", senior:"Add an unconditional date floor outside the guard (where event_ts >= dateadd(year,-2,current_date)) that applies on every run, and keep the watermark filter inside the guard for incremental runs. The two filters serve different purposes: one bounds the historical scope, the other selects the delta." },
  { tier:"senior", cat:"Materializations", q:"What is relation replacement, and how do table and incremental materializations differ in how they treat the existing relation?", short:"Table materialization replaces the relation each run (create or replace / swap), discarding prior contents. Incremental preserves the existing relation and modifies it in place (insert/merge), only replacing it on full refresh.", detailed:"A table build produces a fresh relation and atomically swaps it in, so the old data is gone. Incremental treats the existing table as state to extend, applying deltas without recreating it, which is why its history accumulates and why partial failures can leave it partly updated. full_refresh switches incremental to replacement semantics.", example:"{# table: replace every run; incremental: modify in place unless --full-refresh #}", mistake:"Expecting incremental to replace the relation like table does, then being surprised that stale/duplicate rows persist across runs.", followup:"What are the implications for schema changes?", senior:"Because incremental keeps the relation, column additions/removals require on_schema_change handling or a full refresh, whereas a table rebuild naturally adopts the new SELECT is schema every run. Persisted-in-place state is the source of incremental is power and its schema-evolution complexity." },
  { tier:"beginner", cat:"Tests", q:"What are the four built-in generic tests in dbt and what does each assert?", short:"not_null, unique, accepted_values, and relationships. They assert no nulls, no duplicates, values within a set, and referential integrity to a parent column.", detailed:"dbt ships four generic tests out of the box. not_null asserts a column has no null rows; unique asserts no duplicate values; accepted_values asserts every value is in a supplied list; relationships asserts every value exists in a referenced model's column (a foreign-key check). Each compiles to a SELECT that returns failing rows, and the test passes when zero rows come back.", example:"models:\n  - name: orders\n    columns:\n      - name: order_id\n        tests: [not_null, unique]\n      - name: status\n        tests:\n          - accepted_values:\n              values: ['placed', 'shipped', 'returned']\n      - name: customer_id\n        tests:\n          - relationships:\n              to: ref('customers')\n              field: customer_id", mistake:"Assuming a passing unique+not_null on a surrogate key proves the grain is correct; the key can be unique while the business grain is still wrong.", followup:"How does relationships behave when the child column itself contains nulls?", senior:"Generic tests are cheap structural guarantees, not semantic ones. I treat the four built-ins as a floor, not evidence of correctness." },
  { tier:"intermediate", cat:"Tests", q:"What is a singular test and when would you reach for one over a generic test?", short:"A singular test is a one-off .sql file in the tests/ path that returns failing rows. Use it when the assertion is specific to one model and not worth parameterizing.", detailed:"A singular test is just a SQL query saved under the tests/ directory; if it returns any rows the test fails. Unlike generic tests it takes no arguments and is not reusable across models. Reach for it when the business rule is bespoke, for example cross-column arithmetic or a condition spanning several models, where writing a generic test would add indirection without reuse.", example:"-- tests/assert_total_equals_sum_of_lines.sql\nselect o.order_id\nfrom {{ ref('orders') }} o\njoin {{ ref('order_lines') }} l using (order_id)\ngroup by o.order_id, o.order_total\nhaving o.order_total <> sum(l.line_amount)", mistake:"Writing a singular test with hardcoded references and then copy-pasting it across models instead of promoting it to a generic test.", followup:"How would you convert this singular test into a reusable generic test?", senior:"If I write the same singular test twice, that is the signal to generalize it. Singular tests are for genuinely unique assertions." },
  { tier:"fouryear", cat:"Tests", q:"How do you author a custom generic test, and what are the required arguments?", short:"Define a test block macro (tests/generic/ or macros/) taking model and column_name, returning a query of failing rows. It then works like a built-in test in YAML.", detailed:"A custom generic test is a macro wrapped in {% test name(model, column_name) %} ... {% endtest %}. dbt passes model (the relation under test) and column_name automatically; you can add your own named arguments. The body returns a SELECT of rows that violate the rule. Once defined, you reference it by name in the tests: list of any model, optionally passing your extra arguments.", example:"{% test not_negative(model, column_name) %}\nselect {{ column_name }}\nfrom {{ model }}\nwhere {{ column_name }} < 0\n{% endtest %}\n\n# usage\ncolumns:\n  - name: amount\n    tests:\n      - not_negative", mistake:"Forgetting that the macro must return failing rows, not a boolean; returning a true/false expression makes the test meaningless.", followup:"How would you add a configurable threshold argument to this test?", senior:"Custom generics are how a team encodes its own data-quality vocabulary. I keep them small, well-named, and documented so analysts adopt them." },
  { tier:"intermediate", cat:"Tests", q:"Explain test severity and the difference between warn and error, including thresholds.", short:"severity can be error (fails the run) or warn (reports but passes). error_if / warn_if set row-count thresholds so a few failures warn while many error.", detailed:"Every test has a severity config, defaulting to error, which makes the run fail on any failing rows. Setting severity: warn reports failures without failing the build. For graduated handling, error_if and warn_if accept expressions on the failing row count, e.g. warn above zero but error above a hundred. This lets you tolerate known noise while still blocking on a real regression.", example:"tests:\n  - not_null:\n      config:\n        severity: warn\n        error_if: '>100'\n        warn_if: '>0'", mistake:"Setting everything to warn to make CI green, which quietly disables the quality gate you built.", followup:"Where would you set severity so it differs between CI and production runs?", senior:"Thresholds are a negotiation with reality. I use them to acknowledge known data noise explicitly rather than muting tests wholesale." },
  { tier:"fouryear", cat:"Tests", q:"What are dbt unit tests (1.8+) and how do they differ from data tests?", short:"Unit tests validate model SQL logic against fixed mock inputs and expected output, at build/parse time. Data tests assert on real warehouse data after a model runs.", detailed:"Introduced in dbt Core 1.8, unit tests let you supply mock rows for a model's refs and sources and assert the exact expected output, verifying transformation logic in isolation. They run against synthetic fixtures, not production data, so they catch logic bugs regardless of what is in the warehouse. Data tests (generic and singular) instead query actual materialized data to catch data-quality issues. The two are complementary: unit tests guard logic, data tests guard data.", example:"unit_tests:\n  - name: test_revenue_rounds\n    model: fct_orders\n    given:\n      - input: ref('stg_orders')\n        rows:\n          - {order_id: 1, amount: 10.005}\n    expect:\n      rows:\n        - {order_id: 1, amount: 10.01}", mistake:"Expecting unit tests to catch bad production data; they only validate logic against the mocks you provide.", followup:"Why are unit tests especially valuable for complex incremental or window-function logic?", senior:"Unit tests moved dbt toward real software testing. I use them for gnarly transformations where I want a logic guarantee independent of warehouse state." },
  { tier:"intermediate", cat:"Tests", q:"What does source freshness check, and how does it differ from completeness or correctness?", short:"Freshness checks how recently a source table was loaded, via a timestamp column and warn/error age thresholds. It says nothing about whether the data is complete or correct.", detailed:"dbt source freshness evaluates max(loaded_at) against warn_after and error_after thresholds to detect stale ingestion. It answers only \"was this loaded recently.\" It cannot tell you whether all expected rows arrived (completeness) or whether the values are right (correctness). A source can be perfectly fresh and still be missing half its rows or carry corrupt values.", example:"sources:\n  - name: raw\n    tables:\n      - name: events\n        loaded_at_field: _loaded_at\n        freshness:\n          warn_after: {count: 6, period: hour}\n          error_after: {count: 24, period: hour}", mistake:"Treating a green freshness check as proof the pipeline is healthy, when a stuck loader can replay an old timestamp or deliver partial batches.", followup:"How would you test completeness separately from freshness?", senior:"Freshness, completeness, and correctness are three different questions. Conflating them is how teams get blindsided by a fresh-but-empty table." },
  { tier:"fouryear", cat:"Contracts", q:"What is a dbt model contract and what does enforcing one guarantee?", short:"A contract declares a model's column names, data types, and constraints. When enforced, dbt builds the model with those as DDL and fails if the output does not match.", detailed:"A model contract is set in config with contract: {enforced: true} plus a columns spec of names and data_type. At build time dbt creates the table using that declared schema and raises an error if the model's SELECT does not produce matching columns and types. This protects downstream consumers from silent schema drift. It is enforced at the moment of build, turning the model's interface into a checked promise.", example:"models:\n  - name: dim_customers\n    config:\n      contract: {enforced: true}\n    columns:\n      - name: customer_id\n        data_type: bigint\n        constraints: [{type: not_null}]", mistake:"Assuming a contract validates data values; it validates shape and declared constraints, not business correctness of the rows.", followup:"What happens to the build if a column's data_type in the contract does not match the SELECT output?", senior:"Contracts make a model a stable API. The hard part is governance: deciding which models deserve contracts and how versions evolve." },
  { tier:"senior", cat:"Contracts", q:"How do declared contract constraints differ from warehouse-enforced constraints across adapters?", short:"Declaring a constraint in a contract does not mean the warehouse enforces it. Enforcement depends entirely on the adapter; some only validate the type, not the constraint.", detailed:"A contract's constraints block emits DDL, but whether that DDL is actually enforced is adapter-specific. not_null is enforced on most warehouses, but primary_key, unique, and foreign_key are often informational only. Snowflake, Redshift, and BigQuery accept PK/FK constraints without enforcing uniqueness or referential integrity; Postgres does enforce them. So a declared unique constraint may give false confidence unless the platform actually checks it.", example:"-- On Snowflake a declared primary_key constraint is metadata only;\n-- duplicate keys still load. Add a dbt unique test to truly enforce it.\nconstraints:\n  - type: primary_key   # not enforced on Snowflake/BigQuery/Redshift\n  - type: not_null      # enforced on most adapters", mistake:"Relying on a declared primary_key constraint for uniqueness on Snowflake, where it is not enforced at all.", followup:"Given that, how would you actually guarantee key uniqueness on a cloud warehouse?", senior:"I never trust a declared constraint to be enforced. I pair contracts with dbt tests because the test is the real guard, not the DDL." },
  { tier:"intermediate", cat:"Tests", q:"How do you pass arguments and config to a generic test in YAML?", short:"Named arguments go directly under the test name; dbt-reserved settings go under a config block. Custom args and reserved config are kept separate.", detailed:"When calling a generic test with arguments you nest them under the test name, for example values: for accepted_values. Reserved configuration like severity, where, limit, or store_failures goes under a config: subkey. Mixing a reserved config key in with custom arguments is a common source of confusing errors, so the separation matters.", example:"tests:\n  - accepted_values:\n      values: ['a', 'b']\n      config:\n        severity: warn\n        where: 'created_at > \\'2024-01-01\\''", mistake:"Putting severity at the same level as values instead of under config, which dbt may silently ignore or reject depending on version.", followup:"What does the where config do to the test query?", senior:"The arg-vs-config split trips up newcomers constantly. I review test YAML specifically for this because a misplaced severity silently weakens a gate." },
  { tier:"fouryear", cat:"Tests", q:"A test passes but the number is wrong in a dashboard. How is that possible?", short:"Tests assert structural and declared rules, not business meaning. Valid, non-null, unique, referentially-intact data can still encode the wrong logic.", detailed:"A passing test suite only proves the assertions you wrote hold. If a join fans out and doubles revenue, each row can still be non-null, the key can still look unique at the final grain, and all accepted_values hold, yet the aggregate is wrong. Correctness is about whether the SQL encodes the intended business logic, which generic tests do not inspect. This is the gap unit tests, reconciliation tests, and reviews are meant to close.", example:"-- Valid SQL, wrong result: a 1-to-many join inflates revenue\nselect o.order_id, sum(o.amount) as revenue\nfrom orders o\njoin shipments s on o.order_id = s.order_id  -- multiple shipments per order\ngroup by 1", mistake:"Treating a green test run as sign-off for business correctness and skipping reconciliation against a source of truth.", followup:"What test would have caught the revenue doubling before it shipped?", senior:"Green tests mean \"my assertions held,\" not \"the number is right.\" I always reconcile key metrics against an independent source." },
  { tier:"senior", cat:"Tests", q:"What are common test-coverage blind spots even in a well-tested project?", short:"Intermediate models, metric reconciliation, late-arriving data, grain changes after joins, and cross-model consistency are frequently untested despite heavy column-level testing.", detailed:"Teams often test keys on staging and marts but leave intermediate models and the join logic between them unguarded, which is exactly where grain breaks. Other blind spots: no reconciliation of headline metrics to a trusted total, no test that incremental models are not silently dropping late data, and no cross-model consistency checks. Column-level tests give a false sense of coverage because they rarely catch fan-out or logic drift.", example:"-- A reconciliation test catching grain/fan-out issues\nselect 'mismatch' as failure\nfrom {{ ref('fct_revenue') }}\nhaving sum(revenue) <> (select sum(amount) from {{ ref('stg_payments') }})", mistake:"Measuring coverage by count of tests rather than by which failure modes are actually guarded.", followup:"How would you prioritize where to add tests if you could only add ten?", senior:"I audit coverage by failure mode, not test count. The scariest gaps are always at join boundaries and in the headline metrics leadership watches." },
  { tier:"intermediate", cat:"Tests", q:"What does store_failures do and why is it useful in triage?", short:"store_failures persists each test's failing rows into a table instead of discarding them, so you can inspect exactly which records violated the assertion.", detailed:"By default a test reports only a count of failing rows. Setting store_failures: true writes those failing rows into a table (in a schema you can configure) so you can query them after the run. This turns a red test into an actionable artifact: you can see the specific duplicate keys or orphaned records rather than re-deriving them by hand. It is invaluable during incident triage and for tracking recurring quality issues.", example:"tests:\n  - unique:\n      config:\n        store_failures: true\n        store_failures_as: table", mistake:"Leaving store_failures on for every test in production, bloating the warehouse with failure tables you never query.", followup:"Where do stored failure tables live and how do you control their schema?", senior:"I enable store_failures selectively on the tests whose failures I expect to investigate. For the rest, a count is enough and storage is waste." },
  { tier:"intermediate", cat:"CI/CD", q:"Describe a sound git branching and PR workflow for a dbt project.", short:"Developers branch from main, build and test in a personal dev schema, open a PR that runs CI against a modified subset, and merge only on green checks and review.", detailed:"A typical flow: each developer works on a feature branch, running dbt against an isolated dev target so they never touch prod. The PR triggers a CI job that builds and tests the changed models (ideally just the modified slice). Review covers SQL, tests, and docs. On merge to main, a production deployment job runs the full or state-aware build. Environment isolation via separate target schemas is what keeps this safe.", example:"# profiles: dev target writes to a personal schema\ndbt build --target dev --select state:modified+", mistake:"Running CI against the full project every PR, making checks slow and expensive enough that people stop waiting for them.", followup:"How do you isolate each developer's builds so they do not collide?", senior:"The workflow lives or dies on isolation and fast feedback. Slow CI gets bypassed, so I invest in making the changed-model path quick." },
  { tier:"fouryear", cat:"CI/CD", q:"What is Slim CI and how does state:modified make it work?", short:"Slim CI builds only models changed since production by comparing against prod state artifacts via the state:modified selector, cutting CI time and cost.", detailed:"Slim CI, a dbt platform feature pattern, runs a CI job that defers to the last production run's artifacts and selects state:modified+ so only changed models and their children build. It compares your branch's manifest to the stored production manifest to find what changed. The + builds downstream dependents too, so you still catch breakage. This avoids rebuilding the entire DAG on every PR.", example:"dbt build --select state:modified+ --defer --state ./prod-artifacts", mistake:"Using state:modified without the trailing +, so you test the changed model but miss downstream models it breaks.", followup:"Why do you also need --defer alongside --select state:modified?", senior:"Slim CI is the single biggest CI cost lever. The subtlety is always in getting the state artifact and deferral wired correctly so comparisons are honest." },
  { tier:"fouryear", cat:"CI/CD", q:"What are state artifacts and how does deferral work in dbt Core?", short:"State comparison uses a saved manifest.json from a prior run. --defer plus --state lets unbuilt upstream refs resolve to that prior environment instead of rebuilding them.", detailed:"dbt writes manifest.json describing every node after a run. Passing --state <dir> lets selectors like state:modified compare the current project to that manifest. --defer tells dbt that any ref to a model not selected in this run should resolve to the deferred (e.g. production) relation. Together they let CI build only changed models while their unchanged upstreams are read from prod, so you never rebuild the whole lineage.", example:"# compare against prod manifest, defer unbuilt refs to prod\ndbt build --select state:modified+ \\\n  --defer --state ./prod_artifacts --favor-state", mistake:"Comparing against a stale or wrong manifest, so state:modified either misses real changes or flags everything as modified.", followup:"What does --favor-state change about how refs resolve?", senior:"Deferral is dbt Core plumbing; the platform just packages it. Understanding manifest comparison is what lets you debug a CI job that builds the wrong set." },
  { tier:"senior", cat:"CI/CD", q:"How should warehouse credentials and secrets be handled in dbt CI/CD?", short:"Keep them out of profiles.yml and version control; inject via environment variables from the CI secret store, scoped per environment with least privilege.", detailed:"profiles.yml should reference credentials through env_var() so no secret is committed. CI systems (and the dbt platform) provide encrypted secret stores that inject values as environment variables at runtime. Use distinct, least-privilege service accounts per environment so a CI role cannot write to prod. Rotate keys and avoid printing them in logs. The managed platform handles connection secrets centrally, which is one reason teams adopt it.", example:"# profiles.yml\noutputs:\n  prod:\n    password: \"{{ env_var('DBT_PASSWORD') }}\"\n    schema: \"{{ env_var('DBT_SCHEMA') }}\"", mistake:"Committing a profiles.yml with a real password, or giving the CI service account prod-write access it does not need.", followup:"How would you prevent a secret from leaking into dbt debug logs?", senior:"Secrets handling is a security boundary, not a convenience. Per-environment least-privilege roles are non-negotiable even if it is more setup." },
  { tier:"senior", cat:"CI/CD", q:"Why is full-refresh of an incremental model risky in production, and how do you guard it?", short:"A full-refresh drops and rebuilds the table, which can be slow, costly, and can lose data not reproducible from current sources. Guard it with config and controlled runbooks.", detailed:"Incremental models accumulate history; a --full-refresh truncates and rebuilds from scratch. If the source no longer contains older rows, or the rebuild logic differs subtly, you can permanently lose data. It is also a large, expensive scan. You guard against accidents with full_refresh: false in config on fragile models, restrict who can trigger it, and treat it as a deliberate runbook step rather than a casual flag.", example:"models:\n  - name: fct_events\n    config:\n      materialized: incremental\n      full_refresh: false   # ignore --full-refresh for this model", mistake:"Casually adding --full-refresh to a prod job to fix a glitch, destroying history the source can no longer provide.", followup:"When is a full-refresh actually the correct remediation?", senior:"full_refresh: false on irreplaceable models has saved me real incidents. I treat full-refresh as a destructive operation that needs a runbook." },
  { tier:"senior", cat:"CI/CD", q:"What are the limitations of \"rolling back\" a dbt deployment?", short:"dbt has no built-in rollback; reverting code and re-running does not undo data already written, and incremental/snapshot state may not restore cleanly.", detailed:"Reverting a commit restores the SQL but not the warehouse state it produced. A bad incremental run that dropped or duplicated rows is not undone by reverting; you must rebuild or restore from a backup or time-travel snapshot. Snapshots that recorded spurious versions persist. So rollback is really forward-fix plus data remediation, and your real safety net is warehouse-level time travel or backups, not git.", example:"-- Recovery often relies on warehouse time travel, not dbt\n-- Snowflake example:\ncreate table dim_customers clone dim_customers before (offset => -3600);", mistake:"Believing that git revert + dbt run cleanly rolls back a release, when the corrupted data stays until you remediate it.", followup:"How would warehouse time travel fit into a dbt rollback plan?", senior:"There is no rollback button for data. I design releases assuming forward-fix and lean on warehouse time travel as the actual recovery mechanism." },
  { tier:"fouryear", cat:"CI/CD", q:"How do you validate a release beyond \"the build and tests passed\"?", short:"Add reconciliation checks against prior runs or source-of-truth totals, smoke-test key dashboards, and compare row counts/metrics across the deploy boundary.", detailed:"A green build only proves compilation and your assertions. Release validation adds comparison of headline metrics before and after, row-count deltas on critical tables, and spot checks of downstream dashboards. Techniques include audit-helper style diffs between the new and old version of a model, and canary comparisons. The goal is to catch logic regressions that pass tests but move the numbers.", example:"-- audit_helper style compare of old vs new model output\n{{ audit_helper.compare_relations(\n     a_relation=ref('fct_orders'),\n     b_relation=api.Relation.create(schema='prod', identifier='fct_orders')) }}", mistake:"Shipping on green CI alone and discovering a metric shifted only when a stakeholder complains days later.", followup:"What would you compare to detect a silent metric regression?", senior:"Tests prove invariants; release validation proves the numbers did not move unexpectedly. For regulated or revenue metrics I always diff old vs new." },
  { tier:"fouryear", cat:"CI/CD", q:"How does deployment ordering matter when models depend on each other across jobs?", short:"dbt builds in DAG order within a run, but splitting models across separate jobs can break dependencies if a downstream job runs before its upstream finishes.", detailed:"Within one dbt invocation the DAG guarantees correct ordering. Problems arise when teams split the project into multiple scheduled jobs: if a job building marts runs before the job building their staging inputs completes, the marts read stale or missing data. The fix is to either keep dependent models in one run, use explicit job dependencies in the orchestrator, or use readiness checks before kicking off downstream jobs.", example:"# Airflow: enforce ordering across split dbt jobs\nstaging_task >> marts_task   # marts only after staging succeeds", mistake:"Splitting a project into independently scheduled jobs on timers that happen to overlap, so downstream reads pre-refresh data.", followup:"How would you detect that a downstream job ran against stale upstream data?", senior:"The DAG only protects you inside a single run. The moment you split jobs, ordering becomes the orchestrator's problem and timer-based scheduling will bite you." },
  { tier:"intermediate", cat:"Orchestration", q:"What is the division of responsibility between dbt and an orchestrator like Airflow?", short:"dbt defines and runs transformations; the orchestrator schedules, sequences, retries, and coordinates dbt with ingestion and downstream tasks. dbt is not a scheduler.", detailed:"dbt handles the T in ELT: it compiles and executes SQL transformations in DAG order. An orchestrator like Airflow, Dagster, or the dbt platform scheduler handles when things run, dependencies on ingestion jobs, retries, alerting, and coordination across systems. dbt Core has no built-in scheduler, so something external must trigger it. Keeping transformation logic in dbt and timing/coordination in the orchestrator is the clean separation.", example:"# Airflow sketch\nextract >> load_to_warehouse >> dbt_build >> refresh_bi_cache", mistake:"Trying to encode scheduling logic inside dbt, or conversely rewriting transformation logic in Airflow operators.", followup:"What does the dbt platform provide that raw dbt Core plus Airflow does not?", senior:"The boundary is clean: dbt owns the what, the orchestrator owns the when and the coordination. Blurring it is how projects become unmaintainable." },
  { tier:"fouryear", cat:"Orchestration", q:"What makes a dbt run idempotent, and why does it matter for retries?", short:"A run is idempotent if re-running it produces the same end state. Table/view models are naturally idempotent; incrementals and snapshots can break idempotency on retry.", detailed:"Orchestrators retry failed tasks, so a dbt run must be safe to execute more than once. Fully-rebuilt materializations (table, view) are idempotent because they replace their output. Incremental models can double-count if a retry reprocesses rows already appended, and snapshots can record spurious versions if run twice in a window. Designing incremental logic with merge/dedup keys and bounded windows keeps retries safe.", example:"-- idempotent incremental via merge on a unique key avoids dup inserts\n{{ config(materialized='incremental', unique_key='event_id',\n          incremental_strategy='merge') }}", mistake:"Using an append incremental strategy without a unique key, so an orchestrator retry inserts the same rows twice.", followup:"How does the merge strategy protect against duplicate inserts on retry?", senior:"I assume every task will be retried and design incrementals to survive it. Non-idempotent models are time bombs under any orchestrator." },
  { tier:"fouryear", cat:"Orchestration", q:"How do readiness and freshness checks fit into orchestrating dbt?", short:"Run source freshness or a readiness gate before building, so dbt only transforms once upstream loads have actually landed, avoiding transforming stale or partial data.", detailed:"Before triggering a build you often want to confirm the upstream data is present and current. dbt source freshness can act as a gate: if sources are stale the run is held. More generally, orchestrators check a readiness signal (a load-complete marker, a row count, a freshness result) before kicking off the transformation. This prevents building marts on half-loaded sources and turns timing assumptions into explicit checks.", example:"# gate the build on freshness\ndbt source freshness && dbt build", mistake:"Scheduling the transform on a fixed timer that assumes ingestion always finishes first, instead of checking readiness.", followup:"What do you do when freshness fails: skip, wait, or alert?", senior:"Timers encode a hope that ingestion finished. Readiness checks encode a fact. I convert timing assumptions into explicit gates wherever a mart depends on a load." },
  { tier:"senior", cat:"Orchestration", q:"How do you safely run a backfill without disrupting the regular scheduled pipeline?", short:"Isolate the backfill (separate target/schema or bounded variables), run it off the normal schedule, and ensure it is idempotent so it does not collide with incremental runs.", detailed:"Backfills reprocess historical ranges and can conflict with the ongoing incremental schedule. Safe practice: parameterize the model to accept a date range via vars, run the backfill against an isolated schema or during a controlled window, and make the merge logic idempotent so overlapping ranges do not duplicate. Coordinate so the regular job is paused or does not overlap the backfilled partitions. Validate counts before swapping results in.", example:"dbt run --select fct_events \\\n  --vars '{\"start_date\": \"2023-01-01\", \"end_date\": \"2023-02-01\"}'", mistake:"Running a backfill against prod while the hourly incremental also runs, so the two writers race and produce duplicates or gaps.", followup:"How would you parameterize a model to accept a backfill window?", senior:"Backfills are concurrent writers to the same tables. I isolate them and make the merge idempotent, because the failure mode is silent duplication." },
  { tier:"intermediate", cat:"Orchestration", q:"What causes duplicate scheduling of dbt models and how do you avoid it?", short:"Overlapping jobs that both select the same models, or a timer plus a dependency-triggered run, can build a model twice. Avoid with clear ownership and non-overlapping selectors.", detailed:"Duplicate scheduling happens when two jobs both include a model, for example a nightly full run and a separate hourly job whose selector overlaps, or a model triggered both on a timer and by an event. Besides wasted cost, concurrent builds of the same table can race. Prevent it by giving each model a single owning job, using disjoint selectors or tags, and avoiding timer+trigger duplication for the same target.", example:"# disjoint selectors keep jobs from overlapping\n# job A: dbt build --select tag:hourly\n# job B: dbt build --select tag:daily", mistake:"Adding a new scheduled job with a broad selector that silently re-includes models another job already owns.", followup:"How would tags help you partition ownership cleanly?", senior:"Every model should have exactly one job that owns its schedule. Overlapping selectors are both a cost leak and a concurrency hazard." },
  { tier:"fouryear", cat:"Performance", q:"How do you diagnose and fix an unexpectedly expensive join in a dbt model?", short:"Read the warehouse query profile for the join, check for fan-out, skew, and full scans, then fix with better keys, pre-aggregation, incremental filtering, or clustering.", detailed:"Start with the warehouse's query profiler to see where time and bytes go: a join that explodes row count signals fan-out; uneven partition timing signals skew; a full-table scan signals missing pruning. Fixes depend on the cause: deduplicate or pre-aggregate before joining, filter incrementally so you join less data, add clustering/partitioning so the warehouse prunes, or restructure to avoid a many-to-many. No single trick always wins; the profile tells you which.", example:"-- pre-aggregate one side to kill fan-out before joining\nwith s as (select order_id, sum(amt) amt from lines group by 1)\nselect o.*, s.amt from orders o left join s using (order_id)", mistake:"Throwing a bigger warehouse at a fan-out join instead of fixing the row explosion, paying more for the same bad plan.", followup:"How would you tell fan-out apart from skew in the query profile?", senior:"The query profiler is the ground truth. I diagnose before I tune, because the right fix for fan-out, skew, and missing pruning are completely different." },
  { tier:"intermediate", cat:"Performance", q:"When is materializing a model as a table wasteful versus worthwhile?", short:"Tables cost storage and rebuild compute; they pay off when a view is recomputed often or is expensive. For rarely-queried or cheap logic, a view may be better.", detailed:"A table materialization precomputes and stores results, trading storage and build cost for fast reads. It is worthwhile when many consumers query the result or the underlying logic is expensive to recompute each time. It is wasteful for lightly-used models or thin passthroughs, where a view avoids storage and build cost. No materialization is universally fastest; the right choice depends on query frequency, cost of recomputation, and freshness needs.", example:"-- thin staging passthrough: a view avoids needless rebuild cost\n{{ config(materialized='view') }}\nselect id, lower(email) as email from {{ source('raw','users') }}", mistake:"Materializing every model as a table by default, paying to rebuild staging layers nobody queries directly.", followup:"Where does an ephemeral materialization fit in this tradeoff?", senior:"Materialization is an economics decision per model, not a default. I weigh read frequency against rebuild cost rather than reaching for table everywhere." },
  { tier:"fouryear", cat:"Performance", q:"How do you choose an incremental strategy, and what are the tradeoffs?", short:"Pick append, merge, delete+insert, or insert_overwrite based on whether you have updates, a unique key, and the adapter's support. Each trades correctness guarantees against cost.", detailed:"append is cheapest but cannot handle updates or dedup. merge handles upserts via a unique key and is the default on warehouses that support it, at the cost of a merge operation. delete+insert replaces matched rows and suits some adapters better. insert_overwrite replaces whole partitions, which is efficient for partitioned tables like BigQuery or Spark/Databricks. The right choice depends on update semantics, key availability, and what the adapter supports.", example:"{{ config(\n  materialized='incremental',\n  incremental_strategy='insert_overwrite',\n  partition_by={'field':'event_date','data_type':'date'}\n) }}", mistake:"Using append where records can be updated, so corrections append as duplicates instead of replacing originals.", followup:"Why does insert_overwrite suit partitioned BigQuery tables particularly well?", senior:"Incremental strategy is where correctness and cost collide. I choose it from the update semantics first, then confirm the adapter actually supports that strategy." },
  { tier:"senior", cat:"Performance", q:"How do partition pruning and clustering reduce scan cost, and where do they apply?", short:"Partition pruning skips partitions outside a filter; clustering co-locates related rows so the engine reads fewer micro-partitions. Both cut bytes scanned, but mechanics are adapter-specific.", detailed:"Partition pruning requires the query to filter on the partition column so the engine can skip irrelevant partitions, which is central on BigQuery partitioned tables and Spark/Databricks. Clustering (Snowflake, BigQuery) orders data so rows with similar key values sit together, letting the engine prune micro-partitions on filtered columns. Both only help when queries filter on the partition/cluster keys. They do not exist identically across adapters, so you implement them per warehouse.", example:"-- BigQuery: partition + cluster so date+customer filters prune\n{{ config(partition_by={'field':'dt','data_type':'date'},\n          cluster_by=['customer_id']) }}", mistake:"Partitioning on a column queries never filter on, so no pruning ever happens and you pay for the overhead.", followup:"Why does clustering help nothing if downstream queries never filter on the cluster key?", senior:"Pruning only helps if the query filters on the key. I design the partition/cluster choice around how the data is actually queried, per adapter." },
  { tier:"fouryear", cat:"Cost", q:"How do you attribute warehouse cost to specific dbt models?", short:"Join dbt's run results (model, timing) with the warehouse's query history/billing views on query tags or IDs to see bytes scanned or credits per model.", detailed:"dbt emits run_results.json with per-model timing, and you can set query_tag or comments so warehouse query history ties a query back to its model. On Snowflake you join to the query history and warehouse metering views; on BigQuery to INFORMATION_SCHEMA.JOBS for bytes billed. Correlating these gives per-model cost so you can target the expensive few rather than guessing. The mechanism is adapter-specific but the pattern is the same.", example:"-- tag queries so warehouse history attributes cost per model\n{{ config(query_tag=\"dbt_\" ~ this.name) }}", mistake:"Assuming the longest-running model is the most expensive; a short query can scan enormous bytes while a long one is cheap compute.", followup:"On Snowflake, which views would you join to get credits per model?", senior:"Cost attribution turns optimization from guesswork into a ranked list. I tag queries so warehouse history can point at the real offenders." },
  { tier:"fouryear", cat:"Performance", q:"What causes repeated full scans across a dbt project and how do you reduce them?", short:"Chains of views and non-incremental marts re-scan the same source every run or query. Materialize hot intermediate results and make large fact models incremental.", detailed:"If staging and intermediate layers are all views, each downstream query re-scans the raw sources through the whole chain, repeatedly. Large fact tables rebuilt in full every run re-scan all history. You reduce this by materializing frequently-read intermediate models as tables, making big append-only facts incremental so only new data is scanned, and avoiding view-on-view-on-view chains over huge sources. The goal is to compute expensive scans once.", example:"-- make a large fact incremental so each run scans only new rows\n{{ config(materialized='incremental') }}\nselect * from {{ source('raw','events') }}\n{% if is_incremental() %}\nwhere loaded_at > (select max(loaded_at) from {{ this }})\n{% endif %}", mistake:"Leaving a deep view chain over a huge source so every dashboard query re-scans terabytes through the whole stack.", followup:"How do you decide which intermediate view to promote to a table?", senior:"View-on-view over big sources is a silent repeated scan. I materialize the hot path and make big facts incremental so the costly scan happens once." },
  { tier:"senior", cat:"Cost", q:"How do you detect a cost or performance regression introduced by a dbt change?", short:"Baseline per-model runtime and bytes from run artifacts and warehouse history, then compare after the change; alert on deltas beyond a threshold.", detailed:"Capture a baseline of per-model execution time and bytes scanned from run_results.json and the warehouse query history. After a change, compare the same models; a model that suddenly scans far more bytes or runs much longer flags a regression, often from a lost incremental filter, a new fan-out join, or a dropped partition filter. Automate this as a trend check so regressions surface immediately rather than on the monthly bill.", example:"-- compare bytes billed per model week over week (BigQuery)\nselect labels_model, sum(total_bytes_billed)\nfrom region-us.INFORMATION_SCHEMA.JOBS\ngroup by 1 order by 2 desc", mistake:"Only noticing a cost regression when the warehouse bill spikes at month end, long after the offending merge.", followup:"What change would make a previously incremental model suddenly scan full history?", senior:"Cost regressions should trip a trend alert, not the finance team. I baseline bytes and runtime per model so a bad merge is visible the next run." },
  { tier:"intermediate", cat:"Performance", q:"How does warehouse sizing interact with dbt build performance, and what are the limits?", short:"A bigger warehouse speeds parallelizable scans but does nothing for serial dependencies or skew, and it raises cost. Sizing is a lever, not a cure for bad modeling.", detailed:"Scaling up compute (Snowflake warehouse size, BigQuery slots, Databricks cluster) accelerates large scans and concurrent model builds, up to the point where the DAG's critical path or data skew bottlenecks. A long serial dependency chain will not finish faster on a huge warehouse, and skewed joins stay slow. It also costs proportionally more. So sizing helps throughput for parallel work but cannot fix structural modeling problems.", example:"-- dbt threads control parallelism; warehouse size controls per-query power\n# profiles.yml: threads: 8   (more concurrent models, not faster single model)", mistake:"Scaling up the warehouse to fix a slow model whose real problem is a serial chain or a skewed join.", followup:"What is the difference between adding dbt threads and sizing up the warehouse?", senior:"Compute scaling buys parallel throughput, not a fix for a bad DAG. I reach for it only after confirming the bottleneck is actually parallelizable." },
  { tier:"fouryear", cat:"Adapters", q:"How do incremental partition/overwrite strategies differ between BigQuery and Snowflake?", short:"BigQuery favors insert_overwrite on partitioned tables; Snowflake typically uses merge or delete+insert. The partitioning model and supported strategies differ per adapter.", detailed:"BigQuery tables are partitioned (by date or integer range), so insert_overwrite that replaces whole partitions is efficient and idiomatic. Snowflake uses micro-partitions managed automatically and clustering keys, so partition-overwrite is not the model; merge on a unique key or delete+insert is standard. You should not port one adapter's strategy to the other without checking support; the dbt-adapter package defines which strategies each warehouse accepts.", example:"-- BigQuery\n{{ config(incremental_strategy='insert_overwrite',\n          partition_by={'field':'dt','data_type':'date'}) }}\n-- Snowflake\n{{ config(incremental_strategy='merge', unique_key='id') }}", mistake:"Copying an insert_overwrite + partition_by config from BigQuery into a Snowflake model where that model does not apply.", followup:"Why is manual partitioning not part of the Snowflake materialization model?", senior:"I never infer one adapter's incremental behavior from another. BigQuery partitions and Snowflake micro-partitions are different machines with different idioms." },
  { tier:"senior", cat:"Adapters", q:"How do data distribution and sorting on Redshift differ from clustering on Snowflake/BigQuery?", short:"Redshift needs explicit distkey and sortkey to control node distribution and scan order; Snowflake/BigQuery manage distribution automatically with optional clustering.", detailed:"Redshift is a node-based MPP warehouse where you choose a distribution style (key, even, all) and sort keys to minimize data movement and scan cost; getting these wrong causes shuffles and slow scans. Snowflake and BigQuery abstract storage distribution away and offer clustering/partitioning as the tuning knob instead. So Redshift tuning is about dist+sort keys, while the cloud-native warehouses tune via clustering and partitioning; the dbt configs differ accordingly.", example:"-- Redshift dbt config\n{{ config(dist='customer_id', sort=['order_date']) }}", mistake:"Treating Redshift like Snowflake and ignoring distribution, causing expensive cross-node shuffles on every join.", followup:"What problem does a wrong Redshift distkey cause on a large join?", senior:"Redshift makes you own distribution; the cloud warehouses hide it. Carrying a Snowflake mental model onto Redshift produces painful shuffles." },
  { tier:"intermediate", cat:"Adapters", q:"Which warehouses support the QUALIFY clause, and what should you do when one does not?", short:"Snowflake, BigQuery, Databricks, and Redshift support QUALIFY; Postgres does not. On Postgres, filter window results with a subquery or CTE instead.", detailed:"QUALIFY filters on window-function results in a single statement and is supported on Snowflake, BigQuery, Databricks (recent), and Redshift. Postgres has no QUALIFY, so you must compute the window function in a subquery/CTE and filter in an outer query. Because adapter SQL dialects diverge, portable dbt code either avoids QUALIFY or branches per adapter. Do not assume a clause exists on a warehouse just because it exists on another.", example:"-- portable alternative for warehouses without QUALIFY\nselect * from (\n  select *, row_number() over (partition by id order by ts desc) rn\n  from events\n) where rn = 1", mistake:"Writing QUALIFY in a model intended to run on Postgres, where it fails to compile.", followup:"How would you keep a model portable across adapters with and without QUALIFY?", senior:"Dialect support is not uniform. I check per-adapter support before using convenience clauses like QUALIFY in code meant to be portable." },
  { tier:"fouryear", cat:"Adapters", q:"How does Databricks differ from a cloud warehouse in materialization options for dbt?", short:"dbt-databricks supports Delta table features like merge, insert_overwrite on partitions, and incremental on Delta; it also exposes options like file_format and liquid clustering that warehouses do not.", detailed:"Databricks runs on Delta Lake, so dbt materializations map to Delta tables with capabilities like ACID merge, partition overwrite, and options for file_format, location, and clustering (including liquid clustering on recent runtimes). This differs from Snowflake/BigQuery where storage format is fixed. Incremental strategies and table properties available depend on the Databricks runtime and the dbt-databricks adapter version, so you confirm support rather than assuming warehouse parity.", example:"{{ config(materialized='incremental', incremental_strategy='merge',\n          file_format='delta', partition_by=['event_date']) }}", mistake:"Assuming a Snowflake materialization config works unchanged on Databricks; the Delta-specific options and strategies differ.", followup:"What does liquid clustering change versus static partitioning on Databricks?", senior:"Databricks is a lakehouse, not a warehouse. Its Delta semantics give materialization options that simply do not exist on Snowflake, so I treat it on its own terms." },
  { tier:"intermediate", cat:"Adapters", q:"What differs about running dbt against Postgres versus a cloud analytics warehouse?", short:"Postgres is row-store OLTP: it enforces real constraints and lacks clustering/partition-overwrite idioms, but struggles on large scans. It suits small/dev workloads, not big analytics.", detailed:"Postgres actually enforces unique/PK/FK constraints, unlike most cloud warehouses, so contract constraints mean more there. But it has no micro-partition or columnar-clustering model, its native partitioning works differently, and it is not built for terabyte scans, so large analytical models are slow. Teams often use Postgres for development or small marts and a columnar warehouse for scale. Capabilities and costs differ, so you tune per adapter.", example:"-- On Postgres a unique constraint is genuinely enforced at write time,\n-- unlike Snowflake/BigQuery where it is informational.", mistake:"Benchmarking models on Postgres and assuming the same performance and constraint behavior will hold on the production warehouse.", followup:"Why can a contract's unique constraint be trusted more on Postgres than on Snowflake?", senior:"Postgres enforces constraints for real but does not scale like a columnar warehouse. I never extrapolate its behavior or performance to the cloud target." },
  { tier:"debugging", cat:"Incidents", q:"Late-arriving rows are missing from a mart. The incremental model looks fine. What is happening?", short:"The incremental filter keys on an event timestamp, so records that arrive after their event time fall below the high-water mark and are never picked up.", detailed:"A common incremental pattern filters where event_time > max(event_time) already loaded. If a record lands in the source days after its event timestamp, it is older than the stored high-water mark, so the next run skips it entirely and it is silently dropped. The fix is to key the filter on a load/ingestion timestamp, or widen the lookback window, or use merge over a recent window so late data is reconsidered.", example:"-- vulnerable: filters on event time, drops late arrivals\nwhere event_at > (select max(event_at) from {{ this }})\n-- safer: filter on load time, or add a lookback window\nwhere loaded_at > (select max(loaded_at) from {{ this }}) - interval '3 days'", mistake:"Filtering incrementals on the business event timestamp instead of the ingestion timestamp, assuming data never arrives late.", followup:"How would a lookback window combined with merge recover these rows?", senior:"Late-arriving data is the classic incremental trap. I filter on load time, not event time, and add a lookback window sized to observed lateness." },
  { tier:"debugging", cat:"Incidents", q:"An incremental merge model started failing with a \"duplicate key\" style error. Why?", short:"The unique_key is no longer actually unique in the incoming batch, so the merge cannot decide which source row matches the target, producing an error or non-deterministic result.", detailed:"merge requires the unique_key to identify at most one row per key in the new data. If an upstream change introduced duplicates, or the chosen key is not truly unique at the model grain, the merge has multiple candidate source rows for one target and fails or picks arbitrarily. Diagnose by testing uniqueness of the key on the incremental source; fix by deduplicating before the merge or choosing a key that matches the true grain.", example:"-- dedup to one row per key before the incremental merge\nqualify row_number() over (partition by order_id order by updated_at desc) = 1", mistake:"Assuming the unique_key is unique without a test, then being surprised when an upstream duplicate breaks the merge.", followup:"How would you confirm the key duplication is in the new batch versus the target?", senior:"A merge is only as sound as the uniqueness of its key. I guard the unique_key with a test precisely so this failure is caught before production." },
  { tier:"debugging", cat:"Incidents", q:"Revenue in a report suddenly doubled after a change. Where do you look first?", short:"A join that became one-to-many, fanning out rows so each revenue figure is counted multiple times. Check the grain of every join added or altered.", detailed:"Doubling almost always means fan-out: a join to a table with multiple matching rows per key multiplies the measure. Look at joins touched by the change and verify each preserves grain; a newly joined dimension with duplicate keys, or a header-to-line join without aggregation, is the usual culprit. Confirm by counting rows before and after the join and checking distinct keys. Fix by deduplicating, aggregating the many side first, or joining at the correct grain.", example:"-- detect fan-out: row count should not grow across the join\nselect count(*) from orders;              -- N\nselect count(*) from orders o join ship s using(order_id); -- > N means fan-out", mistake:"Summing a measure after a one-to-many join without first collapsing the many side to the measure's grain.", followup:"What test would have caught this fan-out before the report shipped?", senior:"Doubled totals scream fan-out. My first move is a row-count check across each join, because the grain almost always broke at a join boundary." },
  { tier:"debugging", cat:"Incidents", q:"An upstream source column was renamed. What breaks, and how do you respond?", short:"Models referencing the old name fail to compile or run; the fix is to update the staging layer and, ideally, catch it with freshness/schema tests at the source boundary.", detailed:"Renaming a source column breaks every model that selects it, surfacing as a compile or run error at the first staging model. The right response is to localize source-column references to the staging layer so only one model needs changing, update it, and rebuild downstream. To catch such changes proactively, contracts on sources, schema tests, or source freshness/structure checks at the ingestion boundary alert you before a full run fails.", example:"-- isolate the rename behind one staging rename so downstream is stable\nselect customer_identifier as customer_id  -- was: cust_id\nfrom {{ source('raw','customers') }}", mistake:"Scattering raw source column names across many marts so a single rename forces edits throughout the project.", followup:"How does a staging layer limit the blast radius of a source rename?", senior:"I quarantine every raw column name in staging so an upstream rename touches exactly one file. The blast radius is a design choice, not fate." },
  { tier:"debugging", cat:"Incidents", q:"A model fails to build because its contract no longer matches the output. How do you triage?", short:"The SELECT produced a column set or type that differs from the declared contract. Compare the declared columns/types to the actual output and reconcile one of them.", detailed:"An enforced contract fails the build when the model's output columns, order, or types diverge from the declaration, for example a column dropped, renamed, added, or a type changed by a cast. Triage by reading the error, which names the mismatching column, then decide whether the contract should change (intended evolution) or the SQL regressed. If it is an intended change, update the contract and version if consumers depend on it; if a regression, fix the SQL.", example:"-- contract says amount bigint but SELECT now yields numeric\n-- either cast back, or update the contract if the change is intended\nselect cast(amount as bigint) as amount from {{ ref('stg') }}", mistake:"Loosening the contract to make the build pass without checking whether the output change was intended or a regression.", followup:"When a contract change is intended, how do you avoid breaking downstream consumers?", senior:"A contract failure is the system doing its job. I decide deliberately whether the SQL regressed or the interface should evolve, and version if it is the latter." },
  { tier:"debugging", cat:"Incidents", q:"A relationships test fails: downstream rows reference keys absent from the parent. What now?", short:"Orphaned records exist; the child has foreign keys with no matching parent. Decide whether to fix upstream completeness, filter orphans, or treat it as a load-ordering issue.", detailed:"A failing relationships test means child rows point at parent keys that are not present, i.e. orphans. Causes include the parent not fully loaded yet (ordering/completeness), deleted parent records, or bad keys. Triage with store_failures to see the offending keys, then determine the cause: if it is load ordering, add a readiness gate; if parents were legitimately removed, decide whether to filter or quarantine orphans; if keys are malformed, fix upstream.", example:"tests:\n  - relationships:\n      to: ref('dim_customers')\n      field: customer_id\n      config: {store_failures: true}", mistake:"Deleting orphaned child rows to make the test green without finding out why the parents were missing.", followup:"How would you tell a load-ordering orphan apart from a genuinely deleted parent?", senior:"Orphans are a symptom; the diagnosis is what matters. I use store_failures to see the keys and treat load-ordering, deletion, and bad keys as different fixes." },
  { tier:"debugging", cat:"Incidents", q:"A snapshot has more versions of a record than real changes occurred. What causes that?", short:"A check-strategy snapshot is tracking a column that churns on every load, or timestamp precision/non-determinism makes dbt see changes where there are none.", detailed:"Snapshots record a new version when the tracked columns change. With check strategy, including a volatile column (an updated_at that bumps every load, a floating-point field, or a reformatted value) makes every run look like a change. With timestamp strategy, an unstable updated_at generates spurious versions. The fix is to track only the columns that semantically define a change, and ensure the source timestamp truly reflects real updates.", example:"{% snapshot dim_cust_snap %}\n{{ config(strategy='check',\n          check_cols=['name','tier'])  -- not volatile audit cols\n}}\n{% endsnapshot %}", mistake:"Using check_cols='all' when the source includes an audit timestamp that changes on every extract.", followup:"When is timestamp strategy preferable to check strategy for snapshots?", senior:"Spurious snapshot versions come from tracking columns that are not really the entity's state. I pick check_cols deliberately, never blanket all." },
  { tier:"debugging", cat:"Incidents", q:"A build fails halfway through the DAG. What is the state of the warehouse and how do you recover?", short:"Models before the failure are updated; the failed model and its descendants are not. Fix the cause and re-run from the failure point, not the whole DAG.", detailed:"dbt builds in dependency order and stops the affected path on failure. Upstream models already committed their new state; the failed node and everything downstream of it are stale or unbuilt. So the warehouse is in a partially-updated state. Recover by fixing the root cause, then re-running the failed node and its descendants, which dbt supports via the result:error or a select from the failed model onward.", example:"# re-run only what failed and its downstream, not the whole project\ndbt build --select result:error+ --state ./target", mistake:"Re-running the entire project from scratch after a mid-DAG failure, wasting compute rebuilding already-good models.", followup:"How does result:error+ scope the rerun correctly?", senior:"A mid-DAG failure leaves a partial state by design. I recover surgically with result:error+ rather than torching the whole build." },
  { tier:"debugging", cat:"Incidents", q:"An orchestrator retried a dbt run and now a table has duplicate rows. Why, and how to prevent it?", short:"The model is non-idempotent, likely an append incremental, so the retry re-inserted rows the first attempt had already written. Make it idempotent with merge/dedup.", detailed:"If a run partially succeeds and is retried, a non-idempotent model re-does work. An append-strategy incremental without a unique key inserts the same batch twice across the two attempts. Prevention: use merge or delete+insert on a unique_key so re-running replaces rather than appends, bound the incremental window deterministically, and ensure the high-water mark logic is based on committed state. Idempotency is what makes retries safe.", example:"{{ config(materialized='incremental', unique_key='event_id',\n          incremental_strategy='merge') }}  -- retry-safe upsert", mistake:"Relying on append incrementals in a pipeline whose orchestrator retries failed tasks.", followup:"What makes merge safe to run twice where append is not?", senior:"Retries expose every non-idempotent model. I assume at-least-once execution and build incrementals as upserts so a retry is a no-op, not a duplication." },
  { tier:"debugging", cat:"Incidents", q:"A model wrote to the wrong schema/database in production. How does this happen and how do you prevent it?", short:"Target or schema configuration (profile target, generate_schema_name, env vars) resolved differently than expected, so the model materialized in the wrong place.", detailed:"Where a model lands is determined by the active target, the database/schema config, and the generate_schema_name macro. A misconfigured target, an overridden env_var, or a custom schema macro that behaves unexpectedly in prod can send output to the wrong schema or database. Prevent it by making schema resolution explicit and tested, using distinct targets per environment, and guarding prod with a check on the resolved database/schema before running.", example:"-- a custom generate_schema_name macro controls final schema;\n-- verify it maps dev vs prod exactly as intended before deploy.", mistake:"Overriding generate_schema_name without testing how it resolves under the prod target, so dev and prod land in surprising schemas.", followup:"How does the default generate_schema_name behavior differ from a common override?", senior:"Schema resolution is deceptively subtle once you customize generate_schema_name. I test exactly where each target lands before trusting a prod deploy." },
  { tier:"debugging", cat:"Incidents", q:"After upgrading a dbt package, a macro now behaves differently and numbers changed. How do you respond?", short:"A package upgrade changed a macro's logic or defaults. Pin versions, read the changelog, diff the compiled SQL before and after, and test the metric impact.", detailed:"Packages like dbt_utils evolve, and a new version can change a macro's behavior or default arguments, silently shifting output. Respond by pinning package versions in packages.yml so upgrades are deliberate, reviewing the changelog for breaking changes, and diffing compiled SQL to see exactly what the macro now emits. Validate the metric difference before accepting the upgrade. This is why dependency pinning and release validation matter.", example:"# packages.yml: pin to avoid surprise macro changes\npackages:\n  - package: dbt-labs/dbt_utils\n    version: 1.1.1   # explicit, not a floating range", mistake:"Using a loose version range for packages so an unrelated change pulls in a macro behavior shift unnoticed.", followup:"How would you diff compiled SQL to isolate what the macro changed?", senior:"I pin package versions and treat upgrades as code changes with their own validation. A floating range turns a dependency into an uncontrolled input." },
  { tier:"debugging", cat:"Incidents", q:"A selector in a prod job started building far more models than intended. What went wrong?", short:"A graph operator (+, @) or a tag/path selector is matching more of the DAG than expected, often after new models were added under a matched tag or path.", detailed:"Selection syntax is powerful and easy to over-scope: model+ pulls all descendants, +model all ancestors, @model both, and tag:/path: selectors pick up any newly added model that matches. If someone added models under a matched tag or folder, or an extra + crept in, the job balloons. Diagnose with dbt ls using the same selector to list exactly what it resolves to, then tighten the selector or the tags.", example:"# see exactly what a selector resolves to before running it\ndbt ls --select tag:nightly+  # lists every matched node", mistake:"Trusting a selector by eye instead of running dbt ls to see the actual resolved set after the DAG changed.", followup:"What is the difference between model+, +model, and @model in selection?", senior:"Selectors silently widen as the DAG grows. I validate scope with dbt ls, because a stray + or an over-broad tag quietly doubles a job." },
  { tier:"debugging", cat:"Incidents", q:"An upstream model changed and several downstream dashboards broke. How do you find the blast radius?", short:"Use dbt lineage: list descendants of the changed model to see every affected node, including exposures tied to dashboards. The DAG is the impact map.", detailed:"The dbt DAG records every dependency, so the impact of a change is exactly its descendants. dbt ls --select model+ enumerates downstream models, and if you declared exposures for dashboards, those appear too, mapping the change to specific BI assets. This lets you assess blast radius before or after a change rather than discovering it through broken reports. Exposures are the mechanism that connects models to the downstream tools consuming them.", example:"# enumerate everything downstream, including exposures\ndbt ls --select fct_orders+ --resource-type model --resource-type exposure", mistake:"Changing a widely-used upstream model without first enumerating its descendants and the exposures that depend on it.", followup:"How do exposures help connect a model change to specific dashboards?", senior:"Lineage is the impact map. I enumerate descendants and exposures before touching a shared model, so breakage is predicted rather than discovered." },
  { tier:"architecture", cat:"System design", q:"How do you organize a dbt project for a large team to keep it maintainable?", short:"Layer by staging, intermediate, and marts; align folders to source and business domains; enforce naming conventions, ownership, and clear model boundaries.", detailed:"A maintainable large project separates concerns into layers: staging (one-to-one cleaned sources), intermediate (reusable business logic), and marts (consumer-facing facts/dims). Folder structure mirrors sources at staging and business domains at marts, with naming conventions (stg_, int_, fct_, dim_) that make lineage legible. Ownership is assigned per domain, models are documented, and interfaces between domains are explicit so teams can work in parallel without stepping on each other.", example:"models/\n  staging/<source>/stg_*.sql\n  intermediate/<domain>/int_*.sql\n  marts/<domain>/fct_*.sql dim_*.sql", mistake:"Letting marts reference raw sources directly, bypassing staging and scattering cleaning logic across the project.", followup:"Why insist marts never reference sources directly, only staging/intermediate?", senior:"Structure is what lets many people work without colliding. I enforce layers and domain ownership so the DAG stays legible as the team scales." },
  { tier:"architecture", cat:"System design", q:"How do you manage shared conformed dimensions across multiple domains?", short:"Build conformed dimensions once in a shared layer with clear ownership, give them a contract, and have every domain reference that single model rather than rebuilding it.", detailed:"Shared dimensions like customer or date should be modeled once as conformed dimensions in a common area, owned by a specific team, and exposed as a stable interface. Domains consume them by ref rather than each maintaining their own copy, which prevents divergent definitions of \"customer.\" Contracts and versioning on these shared models protect consumers, and ownership makes changes deliberate. The risk you are managing is multiple inconsistent definitions of the same entity.", example:"-- one owned, contracted conformed dimension; all domains ref it\nmodels/marts/core/dim_customers.sql   # single source of truth", mistake:"Letting each domain build its own customer dimension, producing conflicting definitions and metrics that never reconcile.", followup:"How would a contract on a conformed dimension protect its many consumers?", senior:"Conformed dimensions are where consistency is won or lost. One owned, contracted definition beats five domain copies that quietly disagree." },
  { tier:"senior", cat:"System design", q:"What are the tradeoffs of dbt Mesh and cross-project references?", short:"Mesh splits one monolith into governed projects with public model interfaces, improving ownership and build isolation, at the cost of coordination overhead and versioned contracts.", detailed:"dbt Mesh (a platform capability) lets teams own separate projects that reference each other's public, contracted models across project boundaries. Benefits: clear domain ownership, smaller faster builds, and enforced interfaces. Costs: you must define public access and contracts, manage versions across projects, and coordinate changes that cross boundaries. It suits large organizations where a single monolith has become a bottleneck; for small teams the overhead outweighs the gain.", example:"-- consuming project references another project's public model\nselect * from {{ ref('analytics', 'dim_customers') }}", mistake:"Splitting into cross-project mesh prematurely, adding governance overhead a small team cannot justify.", followup:"What must a model expose to be safely referenced across projects?", senior:"Mesh trades coordination cost for ownership and build isolation. I only reach for it once the monolith is genuinely the bottleneck, not before." },
  { tier:"senior", cat:"System design", q:"How do you version a dbt model so you can evolve it without breaking consumers?", short:"Use model versions with contracts: publish a new version, keep the prior one available during migration, mark the latest, and deprecate on a timeline.", detailed:"dbt supports model versions, letting ref target a specific version like ref('dim_customers', version=2). You introduce a breaking change as a new version while the old version keeps serving existing consumers, set a latest_version, and give consumers a deprecation window to migrate. Combined with contracts, this turns schema evolution into a managed process instead of a breaking surprise. It is the mechanism for changing a model that many teams depend on.", example:"models:\n  - name: dim_customers\n    latest_version: 2\n    versions:\n      - v: 1\n        deprecation_date: '2026-01-01'\n      - v: 2", mistake:"Making a breaking change in place and expecting consumers to adapt instantly, instead of running versions side by side.", followup:"How do deprecation_date and latest_version coordinate a migration?", senior:"Versioning makes a model's interface evolvable. Running the old and new versions in parallel with a deprecation date is how you change shared models without an outage." },
  { tier:"architecture", cat:"System design", q:"How do you design dbt models for an auditable, regulated domain?", short:"Favor snapshots for history, immutable append patterns, strong contracts and tests, documented lineage, and store_failures so every assertion and change is traceable.", detailed:"Regulated domains require that you can reconstruct what the data was at any point and prove controls ran. Use snapshots to capture slowly-changing history, prefer append/immutable patterns over destructive updates, enforce contracts and tests as controls, and persist test failures for evidence. Document lineage and ownership via exposures and descriptions. The emphasis shifts from pure efficiency to traceability, reproducibility, and demonstrable data-quality controls.", example:"-- snapshot captures every state change for audit history\n{% snapshot customer_pii_snap %}\n{{ config(strategy='timestamp', updated_at='updated_at',\n          invalidate_hard_deletes=true) }}\n{% endsnapshot %}", mistake:"Using destructive full-refresh patterns in a regulated model, destroying the history auditors require.", followup:"Why does invalidate_hard_deletes matter for an auditable snapshot?", senior:"In regulated domains, reproducibility beats efficiency. I design for the audit question \"what did this look like then,\" which pushes me toward snapshots and immutability." },
  { tier:"senior", cat:"System design", q:"How do you decide data product ownership and domain boundaries in an analytics platform?", short:"Draw boundaries around business capabilities with stable interfaces; each domain owns its sources, models, and published products, exposing contracted models to others.", detailed:"Ownership should follow business domains (orders, marketing, finance) so the team closest to the data owns its modeling and quality. Boundaries are drawn where interfaces can be made stable: a domain owns its staging and marts and publishes a small set of contracted, documented models as its products. Cross-domain needs go through those published interfaces, not by reaching into another domain's internals. This is the data-mesh idea applied pragmatically with dbt contracts and exposures.", example:"-- a domain publishes a few contracted \"products\"; internals stay private\n# finance domain exposes fct_revenue (contracted); keeps int_* private", mistake:"Drawing domain boundaries by table or by team convenience rather than by stable business interfaces, creating tangled cross-references.", followup:"What distinguishes a published data product from an internal intermediate model?", senior:"Boundaries belong where interfaces can be kept stable. I let teams own their internals freely but hold the published, contracted products to a high bar." },
  { tier:"senior", cat:"System design", q:"When would you build custom tooling around dbt versus adopt the managed platform?", short:"Buy the platform for scheduling, CI, docs hosting, and governance when the team is large or lacks platform engineers; build custom when you have specific needs and the expertise to maintain it.", detailed:"dbt Core plus your own orchestrator, CI, and artifact hosting is cheaper in license but costs engineering time to build and maintain scheduling, Slim CI, docs, access control, and lineage. The managed platform provides these out of the box plus mesh and governance. The decision weighs team size, available platform engineering, specific requirements the platform does not meet, and total cost of ownership. For most teams the platform wins on time-to-value; large sophisticated teams sometimes justify custom stacks.", example:"# Core DIY: you assemble these yourself\n# airflow (schedule) + github actions (slim ci) + s3 (artifacts) + custom RBAC", mistake:"Building a bespoke orchestration and CI stack to save license cost, then spending more engineer-hours maintaining it than the platform would have cost.", followup:"Which capabilities are hardest to replicate yourself on dbt Core?", senior:"Build-vs-buy is a total-cost-of-ownership question, not a license one. I count the engineer-hours to replicate Slim CI, governance, and scheduling before going DIY." },
  { tier:"architecture", cat:"System design", q:"How do you structure staging so source changes have minimal downstream impact?", short:"Make staging a thin one-to-one layer that renames, casts, and lightly cleans each source, so all raw-name coupling lives there and downstream models never touch sources.", detailed:"The staging layer should mirror each source table one-to-one, doing only renaming, type casting, and basic cleaning, exposing a stable interface to the rest of the project. Because every raw column name and type is quarantined here, a source rename, retype, or restructure is absorbed by editing one staging model while downstream intermediate and mart models, which only ref staging, remain unchanged. This containment is the main architectural reason staging exists.", example:"-- stg isolates all source coupling behind stable names\nselect\n  id::bigint as customer_id,\n  lower(email_addr) as email   -- raw name hidden here\nfrom {{ source('raw','customers') }}", mistake:"Putting business logic or joins in staging, so it stops being a stable interface and source changes ripple further.", followup:"Why should staging avoid joins and business logic entirely?", senior:"Staging's job is containment: one thin model per source so upstream churn stops there. The moment logic leaks into staging, that insulation is gone." },
  { tier:"architecture", cat:"System design", q:"How do exposures fit into the architecture, and what do they buy you?", short:"Exposures declare downstream consumers (dashboards, apps, ML) of dbt models in the DAG, enabling impact analysis, documentation, and freshness/validation on what actually matters.", detailed:"An exposure is a declared node representing a downstream use of your models, such as a BI dashboard or a data app. It extends the lineage graph beyond the warehouse so you can see which consumers depend on which models, run and test just the models feeding a critical dashboard, and document ownership and purpose. Exposures turn \"who uses this model\" from tribal knowledge into queryable metadata, which is essential for safe change management at scale.", example:"exposures:\n  - name: exec_revenue_dashboard\n    type: dashboard\n    depends_on: [ref('fct_revenue')]\n    owner: {name: Analytics, email: a@co.com}", mistake:"Never declaring exposures, so impact analysis stops at the warehouse edge and dashboard breakage is always a surprise.", followup:"How would you use exposures to run only the models behind a key dashboard?", senior:"Exposures extend lineage to where people actually consume data. Without them, impact analysis blinds out exactly where breakage hurts most." },
];
